#include <bits/stdc++.h>
#include <cmath>
using namespace std;

typedef long long ll;
typedef pair<ll, ll> pii;
typedef pair<pii, ll> piii;

const ll INF = 1000LL * 1000 * 1000;
const ll MOD1 = 998244353;
const ll MOD2 = 1000000009;
const ll MOD3 = 1000000007;

struct Edge {
    ll to, cap, cost, flow;
    size_t rev;
};

void add_edge(vector<vector<Edge>>& graph, ll u, ll v, ll cap, ll cost) {
    graph[u].push_back({v, cap, cost, 0, graph[v].size()});
    graph[v].push_back({u, 0, -cost, 0, graph[u].size() - 1});
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n_nodes = 50 * 99 + 1;
    ll num_nodes = n_nodes;
    ll s = 0, t = 1;
    ll k_val, m_val, k_req, c_val, d_val;

    cin >> k_val >> m_val >> k_req >> c_val >> d_val;

    vector<vector<Edge>> graph(num_nodes);
    vector<ll> lr(55);

    for (ll i = 1; i <= k_req; ++i) {
        cin >> lr[i];
        add_edge(graph, 0, lr[i], 1, 0);
    }

    const ll TIME_STEPS = 99;
    for (ll j = 0; j < TIME_STEPS - 1; ++j) {
        for (ll i = 2; i <= k_val; ++i) {
            add_edge(graph, j * 50 + i, (j + 1) * 50 + i, 50, c_val);
        }
    }

    for (ll j = 1; j < TIME_STEPS; ++j) {
        add_edge(graph, j * 50 + 1, 1, 50, 0);
    }

    vector<vector<ll>> adj(55);
    for (ll i = 0; i < m_val; ++i) {
        ll x, y;
        cin >> x >> y;
        adj[x].push_back(y);
        adj[y].push_back(x);

        for (ll j = 0; j < TIME_STEPS - 1; ++j) {
            for (ll l = 0; l < 50; ++l) {
                ll delta_cost = c_val + d_val * ((l + 1) * (l + 1) - l * l);
                add_edge(graph, j * 50 + x, (j + 1) * 50 + y, 1, delta_cost);
                add_edge(graph, j * 50 + y, (j + 1) * 50 + x, 1, delta_cost);
            }
        }
    }

    ll total_flow = 0;
    ll total_cost = 0;

    while (total_flow < k_req) {
        vector<ll> dist(num_nodes, INF);
        vector<ll> parent(num_nodes, -1);
        vector<size_t> parent_edge_idx(num_nodes);
        vector<ll> in_queue(num_nodes, 0);
        queue<ll> q;

        dist[s] = 0;
        q.push(s);
        in_queue[s] = 1;

        while (!q.empty()) {
            ll u = q.front();
            q.pop();
            in_queue[u] = 0;

            for (size_t i = 0; i < graph[u].size(); ++i) {
                Edge& e = graph[u][i];
                if (e.flow < e.cap && dist[u] + e.cost < dist[e.to]) {
                    dist[e.to] = dist[u] + e.cost;
                    parent[e.to] = u;
                    parent_edge_idx[e.to] = i;
                    if (!in_queue[e.to]) {
                        q.push(e.to);
                        in_queue[e.to] = 1;
                    }
                }
            }
        }

        if (dist[t] == INF) break;

        ll flow_add = k_req - total_flow;
        for (ll v = t; v != s; v = parent[v]) {
            ll u = parent[v];
            size_t idx = parent_edge_idx[v];
            flow_add = min(flow_add, graph[u][idx].cap - graph[u][idx].flow);
        }

        for (ll v = t; v != s; v = parent[v]) {
            ll u = parent[v];
            size_t idx = parent_edge_idx[v];
            ll rev_idx = graph[u][idx].rev;
            graph[u][idx].flow += flow_add;
            graph[v][rev_idx].flow -= flow_add;
            total_cost += graph[u][idx].cost * flow_add;
        }

        total_flow += flow_add;
    }

    cout << total_cost << "\n";
    return 0;
}

