const int MAX_NODES = 10000, MAX_EDGES = MAX_NODES * 100;
const long long INF = LLONG_MAX / 32;

struct MinCostMaxFlow {
    int head[MAX_NODES], to[MAX_EDGES], next_edge[MAX_EDGES], cap[MAX_EDGES], cost[MAX_EDGES], idx;
    long long dist[MAX_NODES], flow_cost;
    int pre_node[MAX_NODES], pre_edge[MAX_NODES];
    bool in_queue[MAX_NODES];

    MinCostMaxFlow() {
        memset(head, -1, sizeof(head));
        idx = 0;
    }

    void add_edge(int u, int v, int capacity, int c) {
        to[idx] = v; next_edge[idx] = head[u]; cap[idx] = capacity; cost[idx] = c; head[u] = idx++;
        to[idx] = u; next_edge[idx] = head[v]; cap[idx] = 0; cost[idx] = -c; head[v] = idx++;
    }

    bool spfa(int source, int sink) {
        fill(dist, dist + MAX_NODES, INF);
        fill(in_queue, in_queue + MAX_NODES, false);
        queue<int> q;
        dist[source] = 0;
        q.push(source);
        in_queue[source] = true;

        while (!q.empty()) {
            int u = q.front(); q.pop();
            in_queue[u] = false;

            for (int e = head[u]; ~e; e = next_edge[e]) {
                if (cap[e] > 0 && dist[to[e]] > dist[u] + cost[e]) {
                    dist[to[e]] = dist[u] + cost[e];
                    pre_node[to[e]] = u;
                    pre_edge[to[e]] = e;
                    if (!in_queue[to[e]]) {
                        in_queue[to[e]] = true;
                        q.push(to[e]);
                    }
                }
            }
        }
        return dist[sink] != INF;
    }

    pair<long long, long long> min_cost_flow(int source, int sink) {
        long long total_flow = 0;
        flow_cost = 0;

        while (spfa(source, sink)) {
            long long augment = INF;
            for (int v = sink; v != source; v = pre_node[v]) {
                augment = min(augment, (long long)cap[pre_edge[v]]);
            }
            for (int v = sink; v != source; v = pre_node[v]) {
                int e = pre_edge[v];
                cap[e] -= augment;
                cap[e ^ 1] += augment;
                flow_cost += augment * cost[e];
            }
            total_flow += augment;
        }
        return {total_flow, flow_cost};
    }
};

