using namespace std;

using pii = pair<int, int>;
using ll = long long;

const int INF = 0x3f3f3f3f;
const ll MOD = 1000000007LL;

struct Edge {
    int to, capacity, cost, index;
    Edge(int t, int cap, int c, int idx) : to(t), capacity(cap), cost(c), index(idx) {}
};

struct MinCostFlow {
    int nodes;
    vector<vector<Edge>> adj;
    vector<int> dist, prevv, preve;

    MinCostFlow(int n) : nodes(n), adj(n) {
        dist.resize(n);
        prevv.resize(n);
        preve.resize(n);
    }

    void addEdge(int u, int v, int cap, int c) {
        adj[u].emplace_back(v, cap, c, adj[v].size());
        adj[v].emplace_back(u, 0, -c, adj[u].size()-1);
    }

    bool dijkstra(int s, int t) {
        fill(dist.begin(), dist.end(), INF);
        using P = pair<int, int>;
        priority_queue<P, vector<P>, greater<P>> pq;
        dist[s] = 0;
        pq.push({0, s});

        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue;
            for (int i = 0; i < adj[u].size(); ++i) {
                auto &e = adj[u][i];
                if (e.capacity > 0 && dist[e.to] > dist[u] + e.cost) {
                    dist[e.to] = dist[u] + e.cost;
                    prevv[e.to] = u;
                    preve[e.to] = i;
                    pq.push({dist[e.to], e.to});
                }
            }
        }
        return dist[t] < INF;
    }

    int getMinCost(int s, int t) {
        int totalFlow = 0, totalCost = 0;
        while (dijkstra(s, t)) {
            int flow = INF;
            for (int v = t; v != s; v = prevv[v]) {
                flow = min(flow, adj[prevv[v]][preve[v]].capacity);
            }
            totalFlow += flow;
            totalCost += dist[t] * flow;
            for (int v = t; v != s; v = prevv[v]) {
                auto &e = adj[prevv[v]][preve[v]];
                e.capacity -= flow;
                adj[v][e.index].capacity += flow;
            }
        }
        return totalCost;
    }
};

