typedef long long ll;
const ll MOD = 1000000007;
const int INF = 0x3f3f3f3f;

struct Edge {
    int dest, cap, cost, revIdx;
    Edge(int d, int c, int cs, int r) : dest(d), cap(c), cost(cs), revIdx(r) {}
};

struct MCMF {
    int N;
    vector<vector<Edge>> gph;
    vector<int> dist, prevV, prevE;

    MCMF(int n) : N(n), gph(n) {
        dist.resize(n);
        prevV.resize(n);
        prevE.resize(n);
    }

    void addEdge(int from, int to, int capacity, int cost) {
        gph[from].emplace_back(to, capacity, cost, (int)gph[to].size());
        gph[to].emplace_back(from, 0, -cost, (int)gph[from].size()-1);
    }

    bool shortestPath(int src, int dst) {
        fill(dist.begin(), dist.end(), INF);
        dist[src] = 0;
        vector<bool> inq(N, false);
        queue<int> q;
        q.push(src);
        inq[src] = true;

        while (!q.empty()) {
            int u = q.front(); q.pop();
            inq[u] = false;

            for (int i = 0; i < gph[u].size(); ++i) {
                auto &e = gph[u][i];
                if (e.cap > 0 && dist[e.dest] > dist[u] + e.cost) {
                    dist[e.dest] = dist[u] + e.cost;
                    prevV[e.dest] = u;
                    prevE[e.dest] = i;
                    if (!inq[e.dest]) {
                        inq[e.dest] = true;
                        q.push(e.dest);
                    }
                }
            }
        }
        return dist[dst] < INF;
    }

    int compute(int s, int t) {
        int totalCost = 0;
        while (shortestPath(s, t)) {
            int flow = INF;
            for (int v = t; v != s; v = prevV[v]) {
                flow = min(flow, gph[prevV[v]][prevE[v]].cap);
            }
            totalCost += dist[t] * flow;
            for (int v = t; v != s; v = prevV[v]) {
                auto &e = gph[prevV[v]][prevE[v]];
                e.cap -= flow;
                gph[v][e.revIdx].cap += flow;
            }
        }
        return totalCost;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    int src = 0;
    int dst = n * 100 + 1;
    MCMF mcmf(dst + 1);

    // Connect all nodes at level 100 to sink
    for (int level = 1; level <= 100; ++level) {
        mcmf.addEdge(level, dst, 100, 0);
    }

    // Connect source to starting positions
    for (int i = 0; i < k; ++i) {
        int startPos;
        cin >> startPos;
        mcmf.addEdge(src, (startPos - 1) * 100 + 1, 1, 0);
    }

    // Connect positions within same node: i -> i+1
    for (int node = 1; node <= n; ++node) {
        for (int level = 1; level < 100; ++level) {
            int from = (node - 1) * 100 + level;
            int to = (node - 1) * 100 + level + 1;
            mcmf.addEdge(from, to, 100, c);
        }
    }

    // Connect positions between nodes
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;

        for (int level = 1; level < 100; ++level) {
            int fromU = (u - 1) * 100 + level;
            int toV = (v - 1) * 100 + level + 1;
            for (int step = 1; step <= 50; ++step) {
                int edgeCost = c + (step * step - (step - 1) * (step - 1)) * d;
                mcmf.addEdge(fromU, toV, 1, edgeCost);
            }
        }

        for (int level = 1; level < 100; ++level) {
            int fromV = (v - 1) * 100 + level;
            int toU = (u - 1) * 100 + level + 1;
            for (int step = 1; step <= 50; ++step) {
                int edgeCost = c + (step * step - (step - 1) * (step - 1)) * d;
                mcmf.addEdge(fromV, toU, 1, edgeCost);
            }
        }
    }

    cout << mcmf.compute(src, dst) << '\n';

    return 0;
}

