struct Edge {
    int next, target, cap, cost;
} edges[MAX_EDGES];

int head[MAX_NODES], edgeCount = 1;

void addEdge(int from, int to, int capacity, int cost) {
    edges[++edgeCount] = {head[from], to, capacity, cost};
    head[from] = edgeCount;
    edges[++edgeCount] = {head[to], from, 0, -cost};
    head[to] = edgeCount;
}

int source, sink, predecessor[MAX_NODES], lastEdge[MAX_NODES], flowToNode[MAX_NODES], dist[MAX_NODES];
bool inQueue[MAX_NODES];
queue<int> queueObj;

int spfa() {
    for (int i = 1; i <= sink; ++i) {
        dist[i] = INF;
        flowToNode[i] = 0;
    }
    flowToNode[source] = INF;
    dist[source] = 0;
    queueObj.push(source);
    inQueue[source] = true;

    while (!queueObj.empty()) {
        int u = queueObj.front();
        inQueue[u] = false;
        queueObj.pop();

        for (int i = head[u], v; i; i = edges[i].next) {
            if (edges[i].cap && dist[v = edges[i].target] > dist[u] + edges[i].cost) {
                dist[v] = dist[u] + edges[i].cost;
                flowToNode[v] = min(flowToNode[u], edges[i].cap);
                lastEdge[v] = i;
                predecessor[v] = u;
                if (!inQueue[v]) {
                    inQueue[v] = true;
                    queueObj.push(v);
                }
            }
        }
    }
    return flowToNode[sink];
}

