#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <climits>

using namespace std;

const long long INF = 1e18;

struct Edge {
    int from, to;
    long long capacity, flow, cost;
    Edge(int f, int t, long long cap, long long fl, long long cst)
        : from(f), to(t), capacity(cap), flow(fl), cost(cst) {}
};

int n, m, k, c, d;
vector<Edge> edges;
vector<int> graph[8500];
long long dist[8500];
int prev_edge[8500];
long long min_capacity[8500];
bool in_queue[8500];

void add_edge(int u, int v, long long cap, long long cost) {
    graph[u].push_back(edges.size());
    edges.emplace_back(u, v, cap, 0, cost);
    graph[v].push_back(edges.size());
    edges.emplace_back(v, u, 0, 0, -cost);
}

pair<long long, long long> min_cost_flow(int source, int sink, int total_nodes) {
    long long total_flow = 0, total_cost = 0;

    while (true) {
        fill(dist, dist + total_nodes, INF);
        fill(prev_edge, prev_edge + total_nodes, -1);
        fill(min_capacity, min_capacity + total_nodes, 0);
        fill(in_queue, in_queue + total_nodes, false);

        queue<int> q;
        dist[source] = 0;
        min_capacity[source] = INF;
        q.push(source);
        in_queue[source] = true;

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            in_queue[u] = false;

            for (int idx : graph[u]) {
                Edge& e = edges[idx];
                if (e.capacity > e.flow && dist[e.to] > dist[u] + e.cost + 1e-9) {
                    dist[e.to] = dist[u] + e.cost;
                    prev_edge[e.to] = idx;
                    min_capacity[e.to] = min(min_capacity[u], e.capacity - e.flow);
                    if (!in_queue[e.to]) {
                        q.push(e.to);
                        in_queue[e.to] = true;
                    }
                }
            }
        }

        if (prev_edge[sink] == -1) break;

        long long path_flow = min_capacity[sink];
        total_flow += path_flow;
        total_cost += path_flow * dist[sink];

        int cur = sink;
        while (cur != source) {
            int idx = prev_edge[cur];
            edges[idx].flow += path_flow;
            edges[idx ^ 1].flow -= path_flow;
            cur = edges[idx].from;
        }
    }

    return {total_flow, total_cost};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m >> k >> c >> d;

    // Add edges from source to k special nodes
    for (int i = 0; i < k; i++) {
        int x;
        cin >> x;
        x--;
        add_edge(0, x + 1, 1, 0);
    }

    // Add edges for m connections with time layers
    for (int i = 0; i < m; i++) {
        int x, y;
        cin >> x >> y;
        x--; y--;
        for (int layer = 0; layer < 105; layer++) {
            for (int j = 0; j < 51; j++) {
                long long cost = c + d * (2LL * j + 1);
                add_edge(layer * n + x + 1, (layer + 1) * n + y + 1, 1, cost);
                add_edge(layer * n + y + 1, (layer + 1) * n + x + 1, 1, cost);
            }
        }
    }

    // Add edges for staying in place across time layers
    for (int layer = 0; layer < 105; layer++) {
        for (int node = 0; node < n; node++) {
            add_edge(layer * n + node + 1, (layer + 1) * n + node + 1, 51, c);
        }
    }

    // Add edges from last layer to sink
    for (int layer = 0; layer < 105; layer++) {
        add_edge(layer * n + 1, 105 * n + 1, 51, 0);
    }

    int total_nodes = 6 + 107 * n;
    auto result = min_cost_flow(0, 105 * n + 1, total_nodes);
    cout << result.second << '\n';

    return 0;
}

