                    resid = -self.supp[dst]
                    src = dst
                    block = -1

                    path = []
                    while last[src] is not None and not shut[src]:
                        path.append(src)
                        if resid >= last[src].cap:
                            resid = last[src].cap
                            block = src
                        src = last[src].src

                    if shut[src]:
                        block = src
                    else:
