import heapq
from collections import defaultdict
import sys

class FlowBase:
    class Edge:
        def __init__(self, src, dst, cap, cost, rev=None):
            self.src = src
            self.dst = dst
            self.cap = cap
            self.cost = cost
            self.rev = rev

    def __init__(self, n=0):
        self.adj = [list() for _ in range(n)]

    def __len__(self):
        return len(self.adj)

    def __getitem__(self, node):
        return self.adj[node]

    def add_edge(self, src, dst, cap, cost):
        if cap <= 0:
            return
        edge1 = self.Edge(src, dst, cap, cost, None)
        edge2 = self.Edge(dst, src, 0, -cost, None)
        edge1.rev = edge2
        edge2.rev = edge1
        self.adj[src].append(edge1)
        self.adj[dst].append(edge2)


class MinCostFlow(FlowBase):
    def __init__(self, n=0):
        super().__init__(n)
        self.min_cost = 0
        self.total_cost = 0
        self.supp = [0] * n
        self.ptnl = [0] * n

    def add_edge(self, src, dst, cap, cost):
        if src == dst:
            return
        if cap <= 0:
            return
        if cost < 0:
            self.supp[src] -= cap
            self.supp[dst] += cap
            self.min_cost += cap * cost
            self.total_cost -= cap * cost
            super().add_edge(dst, src, cap, -cost)
        else:
            self.total_cost += cap * cost
            super().add_edge(src, dst, cap, cost)

    def supply(self, node, vol):
        self.supp[node] += vol

    def dijkstra(self, last):
        infty = self.total_cost + 1
        dist = [infty] * len(self)
        que = []
        for node in range(len(self)):
            if self.supp[node] > 0:
                dist[node] = 0
                heapq.heappush(que, (0, node))

        while que:
            nsp, node = heapq.heappop(que)
            if -nsp != dist[node]:
                continue
            self.ptnl[node] -= nsp
            if self.ptnl[node] > infty:
                self.ptnl[node] = infty
            dist[node] = -1  # mark as invalid

            for e in self.adj[node]:
                if dist[e.dst] == -1 or e.cap == 0:
                    continue
                new_dist = self.ptnl[node] + e.cost - self.ptnl[e.dst]
                if dist[e.dst] == infty or dist[e.dst] > new_dist:
                    dist[e.dst] = new_dist
                    last[e.dst] = e
                    heapq.heappush(que, (-new_dist, e.dst))

    def flow(self):
        for _ in range(1000):  # max iterations
            aug = False
            last = [None] * len(self)
            self.dijkstra(last)
            shut = [False] * len(self)

            for dst in range(len(self)):
                if self.supp[dst] < 0 and last[dst] is not None:
                    resid = -self.supp[dst]
                    src = dst
                    block = -1

                    path = []
                    while last[src] is not None and not shut[src]:
                        path.append(src)
                        if resid >= last[src].cap:
                            resid = last[src].cap
                            block = src
                        src = last[src].src

                    if shut[src]:
                        block = src
                    else:
                        if resid >= self.supp[src]:
                            resid = self.supp[src]
                            block = src

                        # Update edges along the path
                        for node in path:
                            if last[node] is not None:
                                last[node].cap -= resid
                                last[node].rev.cap += resid

                        self.supp[src] -= resid
                        self.supp[dst] += resid
                        self.min_cost += self.ptnl[dst] * resid
                        aug = True

                    if block != -1:
                        for node in path:
                            if node != block:
                                shut[node] = True
                        shut[block] = True

            if not aug:
                break

        for s in self.supp:
            if s > 0:
                return False
        return True

    def optimal(self):
        assert self.flow()
        return self.min_cost


