};

const int MAX_N = 14043;
vector<FlowEdge> edges;
vector<vector<int>> graph(MAX_N);
ll distance[MAX_N];
int parent_vertex[MAX_N];
int parent_edge[MAX_N];
bool in_queue[MAX_N];

const ll infinity = (ll)1e18;
int source_node = MAX_N - 2, target_node = MAX_N - 1;

int residual_capacity(int idx) {
    return edges[idx].capacity - edges[idx].flow;
}

void shortest_path_update() {
    fill(distance, distance + MAX_N, infinity);
    fill(parent_vertex, parent_vertex + MAX_N, -1);
    fill(parent_edge, parent_edge + MAX_N, -1);
    fill(in_queue, in_queue + MAX_N, false);
    distance[source_node] = 0;
    queue<int> bfs;
    bfs.push(source_node);
    in_queue[source_node] = true;

    while (!bfs.empty()) {
        int u = bfs.front(); bfs.pop();
        in_queue[u] = false;
        for (int idx : graph[u]) {
            if (!residual_capacity(idx)) continue;
            int v = edges[idx].to;
            int w = edges[idx].cost;
            if (distance[v] > distance[u] + w) {
                distance[v] = distance[u] + w;
                parent_vertex[v] = u;
                parent_edge[v] = idx;
                if (!in_queue[v]) {
                    in_queue[v] = true;
                    bfs.push(v);
                }
            }
        }
    }
}

void push() {
    shortest_path_update();
    int cur = target_node;
    while (cur != source_node) {
        edges[parent_edge[cur]].flow++;
        edges[parent_edge[cur] ^ 1].flow--;
        cur = parent_vertex[cur];
    }
}

void connect(int u, int v, int cap, int cost) {
    graph[u].emplace_back(edges.size());
    edges.emplace_back(v, cap, 0, cost);
    graph[v].emplace_back(edges.size());
    edges.emplace_back(u, 0, 0, -cost);
}

