#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
using namespace std;

using llong = long long;
using P = pair<llong, int>;

const int MAX_NODES = 5500;
const llong INF = 1000000007LL;

int N, M, K, C, D;
int SOURCE, SINK;
int total_flow = 0;
llong total_cost = 0;
llong dist[MAX_NODES];
int prev_edge_idx[MAX_NODES];

struct Edge {
    int dest;
    int weight;
    int reverse_index;
    int cap;
};

vector<Edge> adj[MAX_NODES];

void connect(int u, int v, int w, int capacity) {
    int sz_u = adj[u].size();
    int sz_v = adj[v].size();
    adj[u].emplace_back(Edge{v, w, sz_v, capacity});
    adj[v].emplace_back(Edge{u, -w, sz_u, 0});
}

void shortest_path() {
    fill(dist, dist + MAX_NODES, INF);
    priority_queue<P, vector<P>, greater<P>> heap;
    dist[SOURCE] = 0;
    heap.emplace(0, SOURCE);

    while (!heap.empty()) {
        auto [d_val, u] = heap.top();
        heap.pop();
        if (d_val != dist[u]) continue;

        for (const auto& e : adj[u]) {
            if (e.cap > 0 && dist[e.dest] > d_val + e.weight) {
                dist[e.dest] = d_val + e.weight;
                prev_edge_idx[e.dest] = e.reverse_index;
                heap.emplace(dist[e.dest], e.dest);
            }
        }
    }
}

void update_flow() {
    int bottleneck = K;
    int cur = SINK;
    while (cur != SOURCE) {
        int prev = adj[cur][prev_edge_idx[cur]].dest;
        int idx = adj[cur][prev_edge_idx[cur]].reverse_index;
        bottleneck = min(bottleneck, adj[prev][idx].cap);
        cur = prev;
    }

    total_flow += bottleneck;
    total_cost += bottleneck * dist[SINK];

    cur = SINK;
    while (cur != SOURCE) {
        int prev = adj[cur][prev_edge_idx[cur]].dest;
        int idx = adj[cur][prev_edge_idx[cur]].reverse_index;
        adj[cur][prev_edge_idx[cur]].cap += bottleneck;
        adj[prev][idx].cap -= bottleneck;
        cur = prev;
    }
}

int get_node(int vertex, int time_step) {
    return vertex + time_step * N;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> M >> K >> C >> D;
    SOURCE = MAX_NODES - 2;
    SINK = MAX_NODES - 1;
    int max_time = N + K;

    for (int i = 0; i < K; ++i) {
        cin >> u;
        connect(SOURCE, get_node(u, 0), 0, 1);
    }

    for (int t = 0; t <= max_time; ++t) {
        connect(get_node(1, t), SINK, 1LL * C * t, K);
    }

    for (int v = 1; v <= N; ++v) {
        for (int t = 0; t < max_time; ++t) {
            connect(get_node(v, t), get_node(v, t + 1), 0, K);
        }
    }

    while (M--) {
        cin >> u >> v;
        for (int i = 1; i <= K; ++i) {
            for (int t = 0; t < max_time; ++t) {
                int w = D * (2 * i - 1);
                connect(get_node(u, t), get_node(v, t + 1), w, 1);
                connect(get_node(v, t), get_node(u, t + 1), w, 1);
            }
        }
    }

    while (total_flow < K) {
        shortest_path();
        update_flow();
    }

    cout << total_cost;
    return 0;
}

