void link(int u, int v, int w, int cap) {
    int sz1 = g[u].size(), sz2 = g[v].size();
    g[u].push_back({v, w, sz2, cap});
    g[v].push_back({u, -w, sz1, 0});
}

void spfa() {
    fill(ddist, ddist + MAXN, INF);
    queue<int> q;
    ddist[src] = 0;
    q.push(src);

    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (const auto& e : g[u]) {
            if (e.cap > 0 && ddist[e.to] > ddist[u] + e.w) {
                ddist[e.to] = ddist[u] + e.w;
                par[e.to] = e.rev;
                q.push(e.to);
            }
        }
    }
}

void path_augment() {
    int f = k;
    int cur = dst;
    while (cur != src) {
        int prev = g[cur][par[cur]].to;
        int idx = g[cur][par[cur]].rev;
        f = min(f, g[prev][idx].cap);
        cur = prev;
    }

    flow += f;
    cost += f * ddist[dst];

    cur = dst;
    while (cur != src) {
        int prev = g[cur][par[cur]].to;
        int idx = g[cur][par[cur]].rev;
        g[cur][par[cur]].cap += f;
        g[prev][idx].cap -= f;
        cur = prev;
    }
}

