struct FlowEdge {
    int target;
    int maxCap;
    int currentFlow;
    int unitCost;
};

const int MAX_VERTEX = 10000;
const long long INFINITY = 1e18;

vector<FlowEdge> flowEdges;
vector<int> adjacencyList[MAX_VERTEX];
long long shortestDist[MAX_VERTEX];
int predecessorNode[MAX_VERTEX];
int predecessorEdge[MAX_VERTEX];
bool visitedQueue[MAX_VERTEX];

void connectNodes(int from, int to, int capacity, int cost) {
    adjacencyList[from].push_back(flowEdges.size());
    flowEdges.push_back({to, capacity, 0, cost});
    adjacencyList[to].push_back(flowEdges.size());
    flowEdges.push_back({from, 0, 0, -cost});
}

bool computeShortestPath(int source, int sink) {
    fill(shortestDist, shortestDist + MAX_VERTEX, INFINITY);
    fill(predecessorNode, predecessorNode + MAX_VERTEX, -1);
    fill(predecessorEdge, predecessorEdge + MAX_VERTEX, -1);
    fill(visitedQueue, visitedQueue + MAX_VERTEX, false);

    queue<int> q;
    q.push(source);
    shortestDist[source] = 0;
    visitedQueue[source] = true;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        visitedQueue[u] = false;

        for (int idx : adjacencyList[u]) {
            FlowEdge& e = flowEdges[idx];
            if (e.maxCap - e.currentFlow <= 0) continue;
            int v = e.target;
            long long alt = shortestDist[u] + e.unitCost;
            if (alt < shortestDist[v]) {
                shortestDist[v] = alt;
                predecessorNode[v] = u;
                predecessorEdge[v] = idx;
                if (!visitedQueue[v]) {
                    visitedQueue[v] = true;
                    q.push(v);
                }
            }
        }
    }

    if (shortestDist[sink] == INFINITY) return false;

    int cur = sink;
    while (cur != source) {
        flowEdges[predecessorEdge[cur]].currentFlow++;
        flowEdges[predecessorEdge[cur] ^ 1].currentFlow--;
        cur = predecessorNode[cur];
    }

    return true;
}

