from collections import deque

INF = 0x3f3f3f3f

class Edge:
    __slots__ = ('to', 'rev', 'cap', 'w')
    def __init__(self, to, rev, cap, w):
        self.to = to
        self.rev = rev
        self.cap = cap
        self.w = w

class MCMF:
    def __init__(self):
        self.g = [[] for _ in range(10001)]
        self.n = 0

    def addv(self, c):
        while c:
            self.g[self.n].clear()
            self.n += 1
            c -= 1
        return self.n - 1

    def adde(self, u, v, c, w):
        self.g[u].append(Edge(v, len(self.g[v]), c, w))
        self.g[v].append(Edge(u, len(self.g[u]) - 1, 0, -w))

    def dijkstra(self, s, t, dis, vis, pot):
        for i in range(self.n):
            dis[i] = INF
            vis[i] = 0
        dis[s] = 0
        q = [(0, s)]
        while q:
            du, u = heapq.heappop(q)
            if vis[u]:
                continue
            vis[u] = 1
            for e in self.g[u]:
                v = e.to
                dv = du + pot[u] + e.w - pot[v]
                if not e.cap or vis[v] or dis[v] <= dv:
                    continue
                dis[v] = dv
                heapq.heappush(q, (dv, v))
        return vis[t]

    def dinic_bfs(self, s, t, dis, vis, pot):
        for i in range(self.n):
            vis[i] = 0
        q = deque()
        q.append(s)
        vis[s] = 1
        while q:
            u = q.popleft()
            for e in self.g[u]:
                v = e.to
                if vis[v] or not e.cap:
                    continue
                if dis[v] != dis[u] + e.w - pot[v] + pot[u]:
                    continue
                vis[v] = vis[u] + 1
                q.append(v)
        return vis[t]

    def dinic_dfs(self, u, t, f, dis, vis, pot, cur):
        if u == t:
            return f
        sf = 0
        while cur[u] < len(self.g[u]):
            e = self.g[u][cur[u]]
            v = e.to
            if not e.cap or vis[v] != vis[u] + 1:
                cur[u] += 1
                continue
            if dis[v] != dis[u] + e.w - pot[v] + pot[u]:
                cur[u] += 1
                continue
            df = self.dinic_dfs(v, t, min(e.cap, f), dis, vis, pot, cur)
            if df > 0:
                sf += df
                f -= df
                e.cap -= df
                self.g[v][e.rev].cap += df
                if f == 0:
                    break
            else:
                cur[u] += 1
        return sf

    def mcmf(self, s, t, mf):
        sf = 0
        sc = 0
        pot = [0] * self.n
        dis = [INF] * self.n
        vis = [0] * self.n
        cur = [0] * self.n

        while self.dijkstra(s, t, dis, vis, pot):
