void fastRead(int &val) {
    val = 0;
    char ch = getchar();
    bool negative = false;
    while (ch < '0' || ch > '9') { if (ch == '-') negative = true; ch = getchar(); }
    while (ch >= '0' && ch <= '9') { val = val * 10 + (ch - '0'); ch = getchar(); }
    if (negative) val = -val;
}

struct Connection {
    int target, nextLink;
    int flow, cost;
};

int N, M, K, V1, V2, SRC, DST;
int distToNode[MAX_NODES];
bool inQueue[MAX_NODES];
Connection links[MAX_NODES];
int firstLink[MAX_NODES], totalLinks = 1;

void connect(int u, int v, int cap, int w) {
    links[++totalLinks] = {v, firstLink[u], cap, w};
    firstLink[u] = totalLinks;
    links[++totalLinks] = {u, firstLink[v], 0, -w};
    firstLink[v] = totalLinks;
}

bool findPath() {
    fill(distToNode + SRC, distToNode + DST + 1, INF_COST);
    fill(inQueue + SRC, inQueue + DST + 1, false);
    queue<int> q;
    q.push(SRC);
    distToNode[SRC] = 0;
    inQueue[SRC] = true;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        inQueue[u] = false;

        for (int i = firstLink[u]; i; i = links[i].nextLink) {
            int v = links[i].target, w = links[i].cost;
            if (links[i].flow > 0 && distToNode[v] > distToNode[u] + w) {
                distToNode[v] = distToNode[u] + w;
                if (!inQueue[v]) {
                    inQueue[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return distToNode[DST] != INF_COST;
}

int pushFlow(int u, int limit, bool visited[]) {
    if (u == DST) return limit;
    visited[u] = true;
    int pushed = 0, remaining = limit;

    for (int i = firstLink[u]; i; i = links[i].nextLink) {
        int v = links[i].target, cap = links[i].flow;
        if (visited[v] || cap == 0 || distToNode[v] != distToNode[u] + links[i].cost) continue;
        int f = pushFlow(v, min(remaining, cap), visited);
        if (f > 0) {
            remaining -= f;
            links[i].flow -= f;
            links[i ^ 1].flow += f;
            pushed += f;
            if (remaining == 0) break;
        }
    }
    return pushed;
}

int minCostFlow() {
    int total = 0;
    while (findPath()) {
        bool visited[MAX_NODES] = {false};
        int flow = pushFlow(SRC, INF_COST, visited);
        if (flow > 0) total += flow * distToNode[DST];
    }
    return total;
}

