using ll = long long;
using tf = ll;
using tc = ll;
const tf INF = 1e9;

struct MCF {
    int n;
    vector<tc> prio, pot;
    vector<tf> curflow;
    vector<int> prevedge, prevnode;
    priority_queue<pair<tc, int>, vector<pair<tc, int>>, greater<pair<tc, int>>> q;

    struct edge {
        int to, rev;
        tf f, cap;
        tc cost;
    };

    vector<vector<edge>> g;

    MCF(int n) : n(n), prio(n), curflow(n), prevedge(n), prevnode(n), pot(n), g(n) {}

    void add_edge(int s, int t, tf cap, tc cost) {
        g[s].push_back({t, (int)g[t].size(), 0, cap, cost});
        g[t].push_back({s, (int)g[s].size() - 1, 0, 0, -cost});
    }

    pair<tf, tc> get_flow(int s, int t) {
        tf flow = 0;
        tc flowcost = 0;

        while (true) {
            q.push({0, s});
            fill(prio.begin(), prio.end(), INF);
            prio[s] = 0;
            curflow[s] = INF;

            while (!q.empty()) {
                auto cur = q.top();
                tc d = cur.first;
                int u = cur.second;
                q.pop();

                if (d != prio[u]) continue;

                for (int i = 0; i < (int)g[u].size(); ++i) {
                    edge &e = g[u][i];
                    int v = e.to;

                    if (e.cap <= e.f) continue;

                    tc nprio = prio[u] + e.cost + pot[u] - pot[v];
                    if (prio[v] > nprio) {
                        prio[v] = nprio;
                        q.push({nprio, v});
                        prevnode[v] = u;
                        prevedge[v] = i;
                        curflow[v] = min(curflow[u], e.cap - e.f);
                    }
                }
            }

            if (prio[t] == INF) break;

            for (int i = 0; i < n; ++i)
                pot[i] += prio[i];

            tf df = min(curflow[t], INF - flow);
            flow += df;

            for (int v = t; v != s; v = prevnode[v]) {
                edge &e = g[prevnode[v]][prevedge[v]];
                e.f += df;
                g[v][e.rev].f -= df;
                flowcost += df * e.cost;
            }
        }

        return {flow, flowcost};
    }
};

int main() {
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    const int T = 500;
    int N = n * T;
    MCF mcf(N + 2);

    // Wait edges: stay in same city for next time unit
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < T - 1; ++j)
            mcf.add_edge(i * T + j, i * T + j + 1, INF, c);

    // Source connections: arrival at city 0 at time i
    for (int i = 0; i < T; ++i)
        mcf.add_edge(i, N + 1, INF, 0);

    // People starting at their cities at time 0
    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        --x;
        mcf.add_edge(N, x * T, 1, 0);
    }

    // Travel edges between cities
    for (int i = 0; i < m; ++i) {
        int x, y;
        cin >> x >> y;
        --x; --y;

        for (int j = 0; j < T - 1; ++j) {
            int cur = 1;
            for (int _ = 0; _ < k; ++_) {
                mcf.add_edge(x * T + j, y * T + j + 1, 1, cur * d + c);
                mcf.add_edge(y * T + j, x * T + j + 1, 1, cur * d + c);
                cur += 2;
            }
        }
    }

    auto p = mcf.get_flow(N, N + 1);
    assert(p.first == k);
    cout << p.second << endl;

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

using llong = long long;
using flow_t = llong;
using cost_t = llong;
const flow_t INF_FLOW = 1000000000LL;

struct MinCostMaxFlow {
    int vertex_count;
    vector<cost_t> distance, potential;
    vector<flow_t> bottleneck;
    vector<int> prev_edge, prev_vertex;
    priority_queue<pair<cost_t, int>, vector<pair<cost_t, int>>, greater<pair<cost_t, int>>> min_heap;

    struct Connection {
        int target;
        int reverse;
        flow_t flow;
        flow_t capacity;
        cost_t weight;
    };

    vector<vector<Connection>> graph;

    MinCostMaxFlow(int n) : vertex_count(n), distance(n), potential(n), bottleneck(n), prev_edge(n), prev_vertex(n), graph(n) {}

    void link(int u, int v, flow_t cap, cost_t cost) {
        graph[u].push_back({v, (int)graph[v].size(), 0, cap, cost});
        graph[v].push_back({u, (int)graph[u].size() - 1, 0, 0, -cost});
    }

    pair<flow_t, cost_t> min_cost_flow(int source, int sink) {
        flow_t total_flow = 0;
        cost_t total_cost = 0;

        while (true) {
            min_heap.emplace(0, source);
            fill(distance.begin(), distance.end(), INF_FLOW);
            distance[source] = 0;
            bottleneck[source] = INF_FLOW;

            while (!min_heap.empty()) {
                auto [dist, u] = min_heap.top();
                min_heap.pop();

                if (dist != distance[u]) continue;

                for (int idx = 0; idx < (int)graph[u].size(); ++idx) {
                    Connection &edge = graph[u][idx];
                    int v = edge.target;

                    if (edge.capacity <= edge.flow) continue;

                    cost_t new_dist = distance[u] + edge.weight + potential[u] - potential[v];
                    if (distance[v] > new_dist) {
                        distance[v] = new_dist;
                        min_heap.emplace(new_dist, v);
                        prev_vertex[v] = u;
                        prev_edge[v] = idx;
                        bottleneck[v] = min(bottleneck[u], edge.capacity - edge.flow);
                    }
                }
            }

            if (distance[sink] == INF_FLOW) break;

            for (int i = 0; i < vertex_count; ++i)
                potential[i] += distance[i];

            flow_t delta = min(bottleneck[sink], INF_FLOW - total_flow);
            total_flow += delta;

            for (int v = sink; v != source; v = prev_vertex[v]) {
                Connection &edge = graph[prev_vertex[v]][prev_edge[v]];
                edge.flow += delta;
                graph[v][edge.reverse].flow -= delta;
                total_cost += delta * edge.weight;
            }
        }

        return {total_flow, total_cost};
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    const int T = 500;
    int total_vertices = n * T;
    MinCostMaxFlow solver(total_vertices + 2);

    // Waiting edges
    for (int i = 0; i < n; ++i)
        for (int t = 0; t < T - 1; ++t)
            solver.link(i * T + t, i * T + t + 1, INF_FLOW, c);

    // Arrival edges to sink
    for (int t = 0; t < T; ++t)
        solver.link(t, total_vertices + 1, INF_FLOW, 0);

    // Source connections for people
    for (int i = 0; i < k; ++i) {
        int city;
        cin >> city;
        --city;
        solver.link(total_vertices, city * T, 1, 0);
    }

    // Travel edges
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;

        for (int t = 0; t < T - 1; ++t) {
            int multiplier = 1;
            for (int p = 0; p < k; ++p) {
                solver.link(u * T + t, v * T + t + 1, 1, multiplier * d + c);
                solver.link(v * T + t, u * T + t + 1, 1, multiplier * d + c);
                multiplier += 2;
            }
        }
    }

    auto result = solver.min_cost_flow(total_vertices, total_vertices + 1);
    assert(result.first == k);
    cout << result.second << '\n';

    return 0;
}
