    input_index = [0]

    def read_int():
        x = 0
        neg = False
        while input_index[0] < len(input_data):
            c = input_data[input_index[0]]
            input_index[0] += 1
            if c == ord('-'):
                neg = True
                continue
            if ord('0') <= c <= ord('9'):
                x = x * 10 + (c - ord('0'))
                continue
            if x != 0 or neg:
                break
        return -x if neg else x

    N = read_int()
    M = read_int()
    K = read_int()
    C = read_int()
    D = read_int()

    cnt = [0] * (N + 1)
    for _ in range(K):
        cnt[read_int()] += 1

    maxn = 55
    maxt = 2 * maxn
    maxp = maxt * maxn
    maxe = 5 * maxt * maxn * maxn

    eg = [None] * (maxe + 1)
    egh = [0] * (maxp + 1)
    ect = 1

    def adeg(a, b, c, l):
        nonlocal ect
        ect += 1
        eg[ect] = Edge(b, l, c, egh[a])
        egh[a] = ect

    def ade(a, b, c, l):
        adeg(a, b, c, l)
        adeg(b, a, -c, 0)

    id_map = [[0] * (K + M + 3) for _ in range(maxn)]
    S = 1
    E = 2
    pct = 2

    for i in range(1, N + 1):
        for j in range(1, K + M + 3):
            pct += 1
            id_map[i][j] = pct
            if i == 1:
                ade(id_map[i][j], E, C * (j - 1), float('inf'))
            if j > 1:
                ade(id_map[i][j - 1], id_map[i][j], 0, float('inf'))
        if cnt[i]:
            ade(S, id_map[i][1], 0, cnt[i])

    for _ in range(M):
        a = read_int()
        b = read_int()
        for j in range(1, K + M + 2):
            for k in range(1, 2 * K, 2):
                ade(id_map[a][j], id_map[b][j + 1], k * D, 1)
                ade(id_map[b][j], id_map[a][j + 1], k * D, 1)

    flag = [False] * (maxp + 1)
    dis = [float('inf')] * (maxp + 1)
    ans = 0

