        for i in range(1, pct + 1):
            flag[i] = False
            dis[i] = float('inf')
        dis[S] = 0
        q = deque([S])
        while q:
            p = q.popleft()
            flag[p] = False
            i = egh[p]
            while i:
                if eg[i].l > 0 and dis[eg[i].b] > dis[p] + eg[i].c:
                    dis[eg[i].b] = dis[p] + eg[i].c
                    if not flag[eg[i].b]:
                        flag[eg[i].b] = True
                        q.append(eg[i].b)
                i = eg[i].ne
        return dis[E] < float('inf')

    def dinic(x, y):
        if x == S:
            return y
        flag[x] = True
        tmp = y
        i = egh[x]
        while i:
            b = eg[i].b
            if not flag[b] and eg[i ^ 1].l > 0 and dis[x] < dis[b] + eg[i ^ 1].c:
