                    }
                }
            }
        }

        if (dist[sink] == MAX_COST) break;

        int flowIncrement = k - totalFlow;
        for (int v = sink; v != source; v = prevNode[v]) {
            int u = prevNode[v];
            size_t idx = prevEdge[v];
            flowIncrement = min(flowIncrement, graph[u][idx].capacity - graph[u][idx].flow);
