				ll cur=q.top();
				int d=cur>>32, u=cur;
				q.pop();
				if(d!=prio[u])
					continue;
				for(int i=0; i<SZ(adj[u]); ++i) {
					Edge &e=adj[u][i];
					int v=e.to;
