template<typename T, typename U>
void update_max(T& a, U b) { if (a < b) a = b; }

template<typename T, typename U>
void update_min(T& a, U b) { if (a > b) a = b; }

inline void mod_add(int& a, int b) {
    a += b;
    while (a >= MOD) a -= MOD;
}

inline int compute_gcd(int a, int b) {
    return b == 0 ? a : compute_gcd(b, a % b);
}

inline int mod_pow(int base, int exp) {
    int result = 1;
    while (exp) {
        if (exp & 1) result = (ll)result * base % MOD;
        base = (ll)base * base % MOD;
        exp >>= 1;
    }
    return result;
}

struct Edge {
    int to, capacity, cost, next;
};

Edge graph_edges[MAX_N << 2];
int edge_count = 0;
int adjacency_list[MAX_N];
int dist[MAX_N], parent_edge[MAX_N], in_queue[MAX_N];

void insert_edge(int u, int v, int cap, int cost) {
    graph_edges[edge_count] = {v, cap, cost, adjacency_list[u]};
    adjacency_list[u] = edge_count++;
    graph_edges[edge_count] = {u, 0, -cost, adjacency_list[v]};
    adjacency_list[v] = edge_count++;
}

bool shortest_path(int source, int sink) {
    fill(dist, dist + sink + 1, INF);
    fill(in_queue, in_queue + sink + 1, 0);
    queue<int> q;
    q.push(source);
    dist[source] = 0;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        in_queue[u] = 0;

        for (int idx = adjacency_list[u]; ~idx; idx = graph_edges[idx].next) {
            int v = graph_edges[idx].to;
            if (graph_edges[idx].capacity && dist[v] > dist[u] + graph_edges[idx].cost) {
                dist[v] = dist[u] + graph_edges[idx].cost;
                parent_edge[v] = idx;
                if (!in_queue[v]) {
                    in_queue[v] = 1;
                    q.push(v);
                }
            }
        }
    }
    return dist[sink] < INF;
}

int min_cost_flow(int source, int sink) {
    int total_flow = 0, total_cost = 0;
    while (shortest_path(source, sink)) {
        int flow = INF;
        for (int node = sink; node != source; node = graph_edges[parent_edge[node] ^ 1].to) {
            update_min(flow, graph_edges[parent_edge[node]].capacity);
        }
        total_cost += flow * dist[sink];
        total_flow += flow;
        for (int node = sink; node != source; node = graph_edges[parent_edge[node] ^ 1].to) {
            graph_edges[parent_edge[node]].capacity -= flow;
            graph_edges[parent_edge[node] ^ 1].capacity += flow;
        }
    }
    cerr << "flow=" << total_flow << "\n";
    return total_cost;
}

