struct Edge {
    i32 to, cap, cost, next;
};

Edge E[MAX_NODES << 2];
i32 E_cnt = 0;
i32 head[MAX_NODES];
i32 d[MAX_NODES], pre[MAX_NODES], inq[MAX_NODES];

void link(i32 u, i32 v, i32 c, i32 w) {
    E[E_cnt] = {v, c, w, head[u]};
    head[u] = E_cnt++;
    E[E_cnt] = {u, 0, -w, head[v]};
    head[v] = E_cnt++;
}

bool find_path(i32 s, i32 t) {
    fill(d, d + t + 1, INF);
    fill(inq, inq + t + 1, 0);
    queue<i32> q;
    q.push(s);
    d[s] = 0;

    while (!q.empty()) {
        i32 u = q.front(); q.pop();
        inq[u] = 0;

        for (i32 i = head[u]; ~i; i = E[i].next) {
            i32 v = E[i].to;
            if (E[i].cap && d[v] > d[u] + E[i].cost) {
                d[v] = d[u] + E[i].cost;
                pre[v] = i;
                if (!inq[v]) {
                    inq[v] = 1;
                    q.push(v);
                }
            }
        }
    }
    return d[t] < INF;
}

i32 solve(i32 s, i32 t) {
    i32 flow = 0, cost = 0;
    while (find_path(s, t)) {
        i32 f = INF;
        for (i32 x = t; x != s; x = E[pre[x] ^ 1].to) {
            f = min(f, E[pre[x]].cap);
        }
        cost += f * d[t];
        flow += f;
        for (i32 x = t; x != s; x = E[pre[x] ^ 1].to) {
            E[pre[x]].cap -= f;
            E[pre[x] ^ 1].cap += f;
        }
    }
    cerr << "flow=" << flow << "\n";
    return cost;
}

