            i32 v = E[i].to;
            if (E[i].cap && d[v] > d[u] + E[i].cost) {
                d[v] = d[u] + E[i].cost;
                pre[v] = i;
                if (!inq[v]) {
                    inq[v] = 1;
                    q.push(v);
                }
            }
        }
    }
    return d[t] < INF;
}

inline i32 mcmf(i32 s, i32 t) {
    i32 flow = 0, cost = 0;
    while (spfa(s, t)) {
        i32 f = INF;
        for (i32 x = t; x != s; x = E[pre[x] ^ 1].to) {
            f = min(f, E[pre[x]].cap);
        }
        cost += f * d[t];
        flow += f;
        for (i32 x = t; x != s; x = E[pre[x] ^ 1].to) {
            E[pre[x]].cap -= f;
            E[pre[x] ^ 1].cap += f;
        }
    }
    cerr << "flow=" << flow << "\n";
    return cost;
}

