};

vector<Edge> edges;
const int MAX_N = 14043;
vector<int> adj[MAX_N];

long long totalCost = 0;
long long dist[MAX_N];
int parent[MAX_N];
int parentEdge[MAX_N];
bool inQueue[MAX_N];

const long long INF = 1e18;

int source = MAX_N - 2;
int sink = MAX_N - 1;

int remaining(int idx) {
    return edges[idx].cap - edges[idx].flow;
}

void bellmanFord() {
    for (int i = 0; i < MAX_N; ++i) {
        dist[i] = INF;
        parent[i] = -1;
        parentEdge[i] = -1;
        inQueue[i] = false;
    }
    dist[source] = 0;
    queue<int> q;
    q.push(source);
    inQueue[source] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        inQueue[u] = false;

        for (int idx : adj[u]) {
            if (remaining(idx) == 0) continue;
            int v = edges[idx].y;
            int w = edges[idx].cost;
            if (dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                parent[v] = u;
                parentEdge[v] = idx;
                if (!inQueue[v]) {
                    inQueue[v] = true;
                    q.push(v);
                }
            }
        }
    }
}

void augmentPath() {
    int cur = sink;
    while (cur != source) {
        int edgeIdx = parentEdge[cur];
        edges[edgeIdx].flow++;
        edges[edgeIdx ^ 1].flow--;
        cur = parent[cur];
    }
    if (dist[sink] != INF) {
        totalCost += dist[sink];
    }
}

void addEdge(int u, int v, int capacity, int cost) {
    adj[u].push_back(edges.size());
    edges.emplace_back(v, capacity, 0, cost);
    adj[v].push_back(edges.size());
    edges.emplace_back(u, 0, 0, -cost);
}

