}

void computeMinCostPath() {
    fill(shortestPathDist, shortestPathDist + MAX_SIZE, LARGE_INF);
    fill(nodeParent, nodeParent + MAX_SIZE, -1);
    fill(edgeParent, edgeParent + MAX_SIZE, -1);
    fill(inQueueFlag, inQueueFlag + MAX_SIZE, false);

    shortestPathDist[sourceNode] = 0;
    queue<int> bfsQueue;
    bfsQueue.push(sourceNode);
