};

class Network {
public:
    vector<vector<Edge>> g;
    int n;

    Network(int size) : n(size), g(size) {}

    void link(int u, int v, i64 cap, i64 w) {
        g[u].push_back({v, cap, w, (int)g[v].size()});
        g[v].push_back({u, 0, -w, (int)g[u].size() - 1});
    }

    i64 min_cost_flow(int src, int dst, i64 flow) {
        vector<i64> dist(n, numeric_limits<i64>::max());
        vector<i64> h(n, 0);
        vector<int> prev_v(n), prev_e(n);

        i64 ans = 0;

        while (flow > 0) {
            fill(dist.begin(), dist.end(), numeric_limits<i64>::max());
            priority_queue<pair<i64, int>, vector<pair<i64, int>>, greater<pair<i64, int>>> pq;
            dist[src] = 0;
            pq.emplace(0, src);

            while (!pq.empty()) {
                auto [d, u] = pq.top(); pq.pop();
                if (d > dist[u]) continue;
                for (int i = 0; i < g[u].size(); ++i) {
                    auto& e = g[u][i];
                    if (e.capacity > 0 && dist[e.target] > dist[u] + e.cost + h[u] - h[e.target]) {
                        dist[e.target] = dist[u] + e.cost + h[u] - h[e.target];
                        prev_v[e.target] = u;
                        prev_e[e.target] = i;
                        pq.emplace(dist[e.target], e.target);
                    }
                }
            }

            if (dist[dst] == numeric_limits<i64>::max()) return -1;
            for (int i = 0; i < n; ++i) h[i] += dist[i];

            i64 f = flow;
            for (int v = dst; v != src; v = prev_v[v]) {
                f = min(f, g[prev_v[v]][prev_e[v]].capacity);
            }

            flow -= f;
            ans += f * h[dst];

            for (int v = dst; v != src; v = prev_v[v]) {
                auto& e = g[prev_v[v]][prev_e[v]];
                e.capacity -= f;
                g[v][e.rev].capacity += f;
            }
        }
        return ans;
    }
};

