        for (int node = 0; node < N; ++node) {
            g.link(d * N + node, (d + 1) * N + node, K, 0);
        }
        for (int e = 0; e < M; ++e) {
            for (int k = 1; k <= K; ++k) {
                g.link(d * N + U[e], (d + 1) * N + V[e], 1, (2 * k - 1) * D);
                g.link(d * N + V[e], (d + 1) * N + U[e], 1, (2 * k - 1) * D);
