struct Edge {
    int to, cap, cost, next;
};

vector<Edge> edges;
vector<int> head;

void add_edge(int u, int v, int cap, int cost) {
    edges.push_back({v, cap, cost, head[u]});
    head[u] = edges.size() - 1;
    edges.push_back({u, 0, -cost, head[v]});
    head[v] = edges.size() - 1;
}

int source, sink;
vector<int> dist, flow, prev_node, prev_edge;
vector<bool> in_queue;

bool spfa() {
    fill(dist.begin(), dist.end(), INF);
    fill(flow.begin(), flow.end(), 0);
    fill(prev_node.begin(), prev_node.end(), -1);
    fill(prev_edge.begin(), prev_edge.end(), -1);
    fill(in_queue.begin(), in_queue.end(), false);

    queue<int> q;
    dist[source] = 0;
    flow[source] = INF;
    q.push(source);
    in_queue[source] = true;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        in_queue[u] = false;

        for (int i = head[u]; ~i; i = edges[i].next) {
            int v = edges[i].to;
            int cap = edges[i].cap;
            int cost = edges[i].cost;

            if (cap > 0 && dist[v] > dist[u] + cost) {
                dist[v] = dist[u] + cost;
                flow[v] = min(flow[u], cap);
                prev_node[v] = u;
                prev_edge[v] = i;
                if (!in_queue[v]) {
                    q.push(v);
                    in_queue[v] = true;
                }
            }
        }
    }

    return prev_node[sink] != -1;
}

int max_flow, min_cost;

void mcmf() {
    while (spfa()) {
        int flow_here = flow[sink];
        max_flow += flow_here;
        min_cost += flow_here * dist[sink];

        int cur = sink;
        while (cur != source) {
            edges[prev_edge[cur]].cap -= flow_here;
            edges[prev_edge[cur] ^ 1].cap += flow_here;
            cur = prev_node[cur];
        }
    }
}

