class Edge:
    __slots__ = ('dest', 'cap', 'cost', 'reverse')
    def __init__(self, dest, cap, cost, reverse):
        self.dest = dest
        self.cap = cap
        self.cost = cost
        self.reverse = reverse

class MinCostFlow:
    def __init__(self):
        self.nodeCount = 0
        self.graph = defaultdict(list)
        self.potential = {}
        self.distance = {}
        self.parentV = {}
        self.parentE = {}

    def setup(self, n):
        self.nodeCount = n
        self.graph = defaultdict(list)
        self.potential = {}
        self.distance = {}
        self.parentV = {}
        self.parentE = {}

    def connect(self, u, v, capacity, cost):
        # Forward edge
        forward_idx = len(self.graph[v])
        reverse_idx = len(self.graph[u])
        self.graph[u].append(Edge(v, capacity, cost, forward_idx))
        # Backward edge
        self.graph[v].append(Edge(u, 0, -cost, reverse_idx))

    def compute(self, source, target, requiredFlow):
        totalFlow = 0
        totalExpense = 0

        # Initialize potential
        self.potential = {i: 0 for i in range(self.nodeCount + 1)}

        while requiredFlow > 0:
            # Dijkstra's algorithm with priority queue
            self.distance = {i: float('inf') for i in range(self.nodeCount + 1)}
            self.distance[source] = 0
            heap = [(0, source)]

            while heap:
                d, u = heapq.heappop(heap)
                if d > self.distance[u]:
                    continue
                for idx, e in enumerate(self.graph[u]):
                    if e.cap > 0:
                        new_dist = self.distance[u] + e.cost + self.potential.get(u, 0) - self.potential.get(e.dest, 0)
                        if new_dist < self.distance[e.dest]:
                            self.distance[e.dest] = new_dist
                            self.parentV[e.dest] = u
                            self.parentE[e.dest] = idx
                            heapq.heappush(heap, (new_dist, e.dest))

            if self.distance.get(target, float('inf')) == float('inf'):
                break

            # Update potential
            for i in range(self.nodeCount + 1):
                if i in self.distance:
                    self.potential[i] = self.potential.get(i, 0) + self.distance[i]

            # Find augmenting path capacity
            augment = requiredFlow
            v = target
            while v != source:
                u = self.parentV[v]
                idx = self.parentE[v]
