using namespace std;

using ll = long long;
using PII = pair<int, int>;

const int INF = 0x3f3f3f3f;
const int MAXN = 6555;

struct Edge {
    int dest;
    int cap;
    int cost;
    int rev;
    Edge(int d, int c, int cst, int r) : dest(d), cap(c), cost(cst), rev(r) {}
};

struct MCMF {
    int V;
    int H[MAXN + 5];
    int dis[MAXN + 5];
    int PreV[MAXN + 5];
    int PreE[MAXN + 5];
    vector<Edge> adj[MAXN + 5];

    void reset(int n) {
        V = n;
        for (int i = 0; i <= V; ++i) adj[i].clear();
    }

    void link(int u, int v, int capacity, int cost) {
        adj[u].push_back(Edge(v, capacity, cost, (int)adj[v].size()));
        adj[v].push_back(Edge(u, 0, -cost, (int)adj[u].size() - 1));
    }

    int min_cost_flow(int s, int t, int f) {
        int total_flow = 0, total_cost = 0;
        memset(H, 0, sizeof(H));
        while (f > 0) {
            priority_queue<PII, vector<PII>, greater<PII>> pq;
            fill(dis, dis + V + 1, INF);
            dis[s] = 0;
            pq.push({0, s});
            while (!pq.empty()) {
                auto [d, u] = pq.top(); pq.pop();
                if (d > dis[u]) continue;
                for (int i = 0; i < adj[u].size(); ++i) {
                    Edge& e = adj[u][i];
                    if (e.cap > 0 && dis[e.dest] > dis[u] + e.cost + H[u] - H[e.dest]) {
                        dis[e.dest] = dis[u] + e.cost + H[u] - H[e.dest];
                        PreV[e.dest] = u;
                        PreE[e.dest] = i;
                        pq.push({dis[e.dest], e.dest});
                    }
                }
            }
            if (dis[t] == INF) break;
            for (int i = 0; i <= V; ++i) H[i] += dis[i];
            int flow = f;
            for (int v = t; v != s; v = PreV[v])
                flow = min(flow, adj[PreV[v]][PreE[v]].cap);
            f -= flow;
            total_flow += flow;
            total_cost += flow * H[t];
            for (int v = t; v != s; v = PreV[v]) {
                Edge& e = adj[PreV[v]][PreE[v]];
                e.cap -= flow;
                adj[v][e.rev].cap += flow;
            }
        }
        return total_cost;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    MCMF solver;
    solver.reset(n * (n + 55) + 2);

    for (int i = 0; i < k; ++i) {
        int u; cin >> u;
        solver.link(0, u, 1, 0);
    }

    vector<PII> edges(m);
    for (int i = 0; i < m; ++i) {
        cin >> edges[i].first >> edges[i].second;
    }

    int sink = n * (n + 55) + 1;
    for (int t = 0; t < n + 54; ++t) {
        for (const auto& e : edges) {
            for (int j = 1; j <= k; ++j) {
                int cost = c + d * (2 * j - 1);
                solver.link(e.first + t * n, e.second + (t + 1) * n, 1, cost);
                solver.link(e.second + t * n, e.first + (t + 1) * n, 1, cost);
            }
        }
        for (int i = 2; i <= n; ++i) {
            solver.link(i + t * n, i + (t + 1) * n, k, c);
        }
        solver.link(1 + t * n, sink, k, 0);
    }

    cout << solver.min_cost_flow(0, sink, k) << '\n';
    return 0;
}

