#define SZ(a) ((int)(a).size())
#define mset(a, b) memset(a, b, sizeof(a))
#define ALL(a) (a).begin(), (a).end()
#define fst first
#define snd second

const int MAXN = 50015;
const int SRC = MAXN - 1;
const int SNC = MAXN - 2;

using tf = ll;
const tf INFFLUJO = 1e14;
using tc = ll;
const tc INFCOSTO = 1e14;

struct edge {
    int u, v;
    tf cap, flow;
    tc cost;
    tf rem() const { return cap - flow; }
};

int nodes = MAXN;
vector<int> g[MAXN];
vector<edge> edges;

void add_edge(int u, int v, tf cap, tc cost) {
    g[u].pb(SZ(edges));
    edges.pb({u, v, cap, 0, cost});
    g[v].pb(SZ(edges));
    edges.pb({v, u, 0, 0, -cost});
}

tc dist[MAXN];
tc mncost;
int pre[MAXN];
tf cap[MAXN];
tf mxflow;
bool in_queue[MAXN];

void flow(int s, int t) {
    mset(in_queue, 0);
    mxflow = mncost = 0;
    while (true) {
        fill(dist, dist + nodes, INFCOSTO);
        dist[s] = 0;
        mset(pre, -1);
        pre[s] = 0;
        mset(cap, 0);
        cap[s] = INFFLUJO;
        queue<int> q;
        q.push(s);
        in_queue[s] = true;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            in_queue[u] = false;
            for (int idx : g[u]) {
                edge &E = edges[idx];
                if (E.rem() && dist[E.v] > dist[u] + E.cost + 1e-9) {
                    dist[E.v] = dist[u] + E.cost;
                    pre[E.v] = idx;
                    cap[E.v] = min(cap[u], E.rem());
                    if (!in_queue[E.v]) {
                        q.push(E.v);
                        in_queue[E.v] = true;
                    }
                }
            }
        }
        if (pre[t] < 0) break;
        mxflow += cap[t];
        mncost += cap[t] * dist[t];
        for (int v = t; v != s; v = edges[pre[v]].u) {
            edges[pre[v]].flow += cap[t];
            edges[pre[v] ^ 1].flow -= cap[t];
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    int MAXT = n + k;
    vector<int> a(k);
    fore(i, 0, k) {
        cin >> a[i];
        --a[i];
        add_edge(SRC, a[i] * MAXT, 1, 0);
    }
    fore(j, 0, MAXT) add_edge(j, SNC, k, 0);
    fore(i, 0, m) {
        int x, y;
        cin >> x >> y;
        --x; --y;
        fore(j, 0, MAXT - 1) fore(K, 1, k + 1) {
            add_edge(x * MAXT + j, y * MAXT + j + 1, 1, c + d * (2 * K - 1));
        }
        fore(j, 0, MAXT - 1) fore(K, 1, k + 1) {
            add_edge(y * MAXT + j, x * MAXT + j + 1, 1, c + d * (2 * K - 1));
        }
    }
    fore(i, 0, n) {
        fore(j, 0, MAXT - 1) fore(K, 1, k + 1) {
            add_edge(i * MAXT + j, i * MAXT + j + 1, 1, c);
        }
    }
    flow(SRC, SNC);
    cout << mncost << '\n';
    return 0;
}

