#include <bits/stdc++.h>
using namespace std;
const int MAX_NODES = 10000010, INF = 0x3f3f3f3f;
int n, m, c, d, k, src, dst, min_cost;
int edge_idx = 1, first[MAX_NODES], to[MAX_NODES], next_edge[MAX_NODES], cap[MAX_NODES], wgt[MAX_NODES];
int dist[MAX_NODES], min_flow[MAX_NODES], parent_edge[MAX_NODES]; bool inq[MAX_NODES];

void connect(int u, int v, int capacity, int weight) {
	to[++edge_idx] = v;
	next_edge[edge_idx] = first[u];
	first[u] = edge_idx;
	cap[edge_idx] = capacity;
	wgt[edge_idx] = weight;
	to[++edge_idx] = u;
	next_edge[edge_idx] = first[v];
	first[v] = edge_idx;
	cap[edge_idx] = 0;
	wgt[edge_idx] = -weight;
}
bool find_path() {
	memset(min_flow, 0, sizeof(min_flow));
	memset(dist, 0x3f, sizeof(dist));
	memset(inq, 0, sizeof(inq));
	queue<int> q;
	q.push(src);
	min_flow[src] = INF;
	dist[src] = 0;
	inq[src] = true;
	while (!q.empty()) {
		int u = q.front(); q.pop();
		inq[u] = false;
		for (int e = first[u]; e; e = next_edge[e]) {
			if (!cap[e] || dist[to[e]] <= dist[u] + wgt[e]) continue;
			dist[to[e]] = dist[u] + wgt[e];
			min_flow[to[e]] = min(min_flow[u], cap[e]);
			parent_edge[to[e]] = e;
			if (!inq[to[e]]) {
				inq[to[e]] = true;
				q.push(to[e]);
			}
		}
	}
	return dist[dst] != INF;
}
void push_flow() {
	int f = min_flow[dst];
	int cur = dst;
	while (cur != src) {
		int e = parent_edge[cur];
		cap[e] -= f;
		cap[e ^ 1] += f;
		cur = to[e ^ 1];
	}
	min_cost += f * dist[dst];
}
int main() {
	scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
	dst = (n + k - 1) * n + 1;
	for (int i = 1, x; i <= k; i++) {
		scanf("%d", &x);
		connect(src, x, 1, 0);
	}
	for (int i = 1, u, v; i <= m; i++) {
		scanf("%d %d", &u, &v);
		for (int layer = 1; layer <= n + k; layer++) {
			for (int hop = 1; hop <= k; hop++) {
				int weight = d * hop * 2 - d + c;
				connect(u + (layer - 1) * n, v + layer * n, 1, weight);
				connect(v + (layer - 1) * n, u + layer * n, 1, weight);
			}
		}
	}
	for (int layer = 1; layer < n + k; layer++) {
		for (int node = 2; node <= n; node++) {
			connect(node + (layer - 1) * n, node + layer * n, 1000000000, c);
		}
		connect(1 + (layer - 1) * n, 1 + layer * n, 1000000000, 0);
	}
	while (find_path()) push_flow();
	printf("%d\n", min_cost);
	return 0;
}

