int shortest_dist[MAXN], augment_flow[MAXN], last_edge[MAXN]; bool visited[MAXN];

void add_edge(int u, int v, int cap, int w) {
	dest[++edge_num] = v;
	next_link[edge_num] = first_node[u];
	first_node[u] = edge_num;
	flow_cap[edge_num] = cap;
	edge_cost[edge_num] = w;
	dest[++edge_num] = u;
	next_link[edge_num] = first_node[v];
	first_node[v] = edge_num;
	flow_cap[edge_num] = 0;
	edge_cost[edge_num] = -w;
}
bool find_shortest_path() {
	memset(augment_flow, 0, sizeof(augment_flow));
	memset(shortest_dist, 0x3f, sizeof(shortest_dist));
	memset(visited, 0, sizeof(visited));
	queue<int> q;
	q.push(src);
	augment_flow[src] = INF;
	shortest_dist[src] = 0;
	visited[src] = true;
	while (!q.empty()) {
		int u = q.front(); q.pop();
		visited[u] = false;
		for (int e = first_node[u]; e; e = next_link[e]) {
			if (!flow_cap[e] || shortest_dist[dest[e]] <= shortest_dist[u] + edge_cost[e]) continue;
			shortest_dist[dest[e]] = shortest_dist[u] + edge_cost[e];
			augment_flow[dest[e]] = min(augment_flow[u], flow_cap[e]);
			last_edge[dest[e]] = e;
			if (!visited[dest[e]]) {
				visited[dest[e]] = true;
				q.push(dest[e]);
			}
		}
	}
	return shortest_dist[dst] != INF;
}
void update_flow() {
	int f = augment_flow[dst];
	int cur = dst;
	while (cur != src) {
		int e = last_edge[cur];
		flow_cap[e] -= f;
		flow_cap[e ^ 1] += f;
		cur = dest[e ^ 1];
	}
	cost_sum += f * shortest_dist[dst];
}
int main() {
	scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
	dst = (n + k - 1) * n + 1;
	for (int i = 1, x; i <= k; i++) {
