        priority_queue<node, vector<node>, greater<node>> pq;
        dist[source] = 0;
        pq.push(node(0, source));
        while (!pq.empty())
        {
            const node p = pq.top(); pq.pop();
            if (dist[p.second] < p.first) continue;
            if (p.second == sink) break;
            for (edge &e : adj[p.second])
                if (e.flow < e.cap && dist[e.dst] > dist[e.src] + rcost(e))
                {
                    back[e.dst] = &e;
                    dist[e.dst] = dist[e.src] + rcost(e);
                    pq.push(node(dist[e.dst], e.dst));
                }
        }
        return dist[sink];
    }
    pair<flow_type, cost_type> max_flow(int source, int sink)
    {
        flow_type flow = 0;
        cost_type cost = 0;
        for (int u = 0; u < n; ++u)
            for (edge &e : adj[u])
                e.flow = 0;
        potential.assign(n, 0);
        dist.assign(n, oo);
        back.assign(n, nullptr);
        while (dijkstra(source, sink) < oo)
        {
            for (int u = 0; u < n; ++u)
                if (dist[u] < dist[sink])
                    potential[u] += dist[u] - dist[sink];
            flow_type f = numeric_limits<flow_type>::max();
            for (edge * e = back[sink]; e; e = back[e->src])
                f = min(f, e->cap - e->flow);
            for (edge * e = back[sink]; e; e = back[e->src])
                e->flow += f, adj[e->dst][e->rev].flow -= f;
            flow += f;
            cost += f * (potential[sink] - potential[source]);
        }
        return {flow, cost};
    }
};

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n,m,k,c,d,u,v;
    cin >> n >> m >> k >> c >> d;
    min_cost_max_flow<int,int> g((n+2)*102);
    for(int i=0;i<102;i++)
        g.add_edge((i*(n+2))+1,i*(n+2),100,(i*c));
    for(int i=0;i<101;i++)
        for(int j=0;j<n+1;j++)
            g.add_edge(j+(i*(n+2)),j+((i+1)*(n+2)),100,0);
    for(int i=0;i<k;i++)
    {
        cin >> u;
        g.add_edge(n+1,u,1,0);
    }
    for(int i=0;i<m;i++)
    {
        cin >> u >> v;
        for(int j=0;j<101;j++)
            for(int f=0;f<k;f++)
            {
                g.add_edge(u+(j*(n+2)),v+((j+1)*(n+2)),1,((2*f)+1)*d);
                g.add_edge(v+(j*(n+2)),u+((j+1)*(n+2)),1,((2*f)+1)*d);
            }
    }
    cerr << "";
