            n = self.N
        self.mc = 0
        self.sz = [0] * n
        self.adj = [[] for _ in range(n)]

    def add_edge(self, a, b, c=1, p=0):
        self.mc = max(self.mc, c)
        self.adj[a].append({'v': b, 'r': self.sz[b], 'f': 0, 'c': c, 'p': p})
        self.sz[b] += 1
        self.adj[b].append({'v': a, 'r': self.sz[a], 'f': 0, 'c': 0, 'p': -p})
        self.sz[a] += 1

    def pot_init(self, n):
        self.pot = [0] * n
        for i in range(1, n):
            for u in range(n):
                for e in self.adj[u]:
                    if e['c'] > 0:
                        self.pot[e['v']] = min(self.pot[e['v']], self.pot[u] + e['p'])

    def mcf(self, s, t, n, sparse):
        vis = [False] * n
        par = [-1] * n
        dist = [INF] * n
        dist[s] = 0

        if sparse:
            dk = deque()
            dk.append(s)
