                for e in self.adj[u]:
                    if e['f'] < e['c'] and dist[e['v']] > dist[u] + self.pot[u] - self.pot[e['v']] + e['p']:
                        dist[e['v']] = dist[u] + self.pot[u] - self.pot[e['v']] + e['p']
                        par[e['v']] = e['r']
                        dk.append(e['v'])
        else:
            for _ in range(n):
                u = -1
                best = INF
                for i in range(n):
                    if not vis[i] and dist[i] < best:
                        best = dist[i]
                        u = i
                if u == -1:
                    break
                vis[u] = True
                for e in self.adj[u]:
                    if e['f'] < e['c'] and dist[e['v']] > dist[u] + self.pot[u] - self.pot[e['v']] + e['p']:
                        dist[e['v']] = dist[u] + self.pot[u] - self.pot[e['v']] + e['p']
                        par[e['v']] = e['r']

        if dist[t] >= INF:
            return 0

        df = INF
        u = t
        while u != s:
            r = self.adj[u][par[u]]
            df = min(df, self.adj[r['v']][r['r']]['c'] - self.adj[r['v']][r['r']]['f'])
