using namespace std;

const int MAXN = 10000;
const int MAXM = 2000000;
const int INF = 0x3f3f3f3f;

struct Edge {
    int to, cap, flow, cost, rev;
    Edge(int t, int c, int f, int co, int r) : to(t), cap(c), flow(f), cost(co), rev(r) {}
};

vector<vector<Edge>> graph;
int dist[MAXN], prevv[MAXN], preve[MAXN];

void add_edge(int from, int to, int cap, int cost) {
    graph[from].emplace_back(to, cap, 0, cost, graph[to].size());
    graph[to].emplace_back(from, 0, 0, -cost, graph[from].size() - 1);
}

pair<int, int> min_cost_flow(int s, int t) {
    int flow = 0, cost = 0;
    while (true) {
        fill(dist, dist + MAXN, INF);
        dist[s] = 0;
        bool update = true;
        while (update) {
            update = false;
            for (int v = 0; v < MAXN; ++v) {
                if (dist[v] == INF) continue;
                for (int i = 0; i < graph[v].size(); ++i) {
                    Edge &e = graph[v][i];
                    if (e.cap > e.flow && dist[e.to] > dist[v] + e.cost) {
                        dist[e.to] = dist[v] + e.cost;
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        update = true;
                    }
                }
            }
        }
        if (dist[t] == INF) break;

        int d = INF;
        for (int v = t; v != s; v = prevv[v]) {
            d = min(d, graph[prevv[v]][preve[v]].cap - graph[prevv[v]][preve[v]].flow);
        }

        flow += d;
        cost += d * dist[t];
        for (int v = t; v != s; v = prevv[v]) {
            Edge &e = graph[prevv[v]][preve[v]];
            e.flow += d;
            graph[v][e.rev].flow -= d;
        }
    }
    return {flow, cost};
}

