void setup(int n) {
    node_count = n;
    edge_counter = 0;
    memset(head, -1, sizeof(head));
}

void connect(int u, int v, int cap, int cost) {
    edge_list[edge_counter] = {v, cap, 0, cost, head[u]};
    head[u] = edge_counter++;

    edge_list[edge_counter] = {u, 0, 0, -cost, head[v]};
    head[v] = edge_counter++;
}

bool find_path(int source, int sink) {
    fill(dist, dist + node_count, INF);
    fill(visited, visited + node_count, false);
    fill(prev_node, prev_node + node_count, -1);

    queue<int> q;
    dist[source] = 0;
    visited[source] = true;
    q.push(source);

    while (!q.empty()) {
        int u = q.front(); q.pop();
        visited[u] = false;

        for (int i = head[u]; i != -1; i = edge_list[i].next) {
            int v = edge_list[i].to;
            if (edge_list[i].capacity > edge_list[i].flow && dist[v] > dist[u] + edge_list[i].cost) {
