                if (!visited[v]) {
                    visited[v] = true;
                    q.push(v);
                }
            }
        }
    }

    return prev_node[sink] != -1;
}

int calculate_min_cost(int source, int sink) {
    int total_flow = 0, total_cost = 0;

    while (find_path(source, sink)) {
        int bottleneck = INF;
        for (int v = sink; v != source; v = prev_node[v]) {
            bottleneck = min(bottleneck, edge_list[prev_edge[v]].capacity - edge_list[prev_edge[v]].flow);
        }

        for (int v = sink; v != source; v = prev_node[v]) {
            int idx = prev_edge[v];
            edge_list[idx].flow += bottleneck;
            edge_list[idx ^ 1].flow -= bottleneck;
            total_cost += edge_list[idx].cost * bottleneck;
        }

        total_flow += bottleneck;
    }

    return total_cost;
}

