    first_edge[u] = edge_count++;

    graph[edge_count] = {u, 0, 0, -cost, first_edge[v]};
    first_edge[v] = edge_count++;
}

bool shortest_path(int source, int sink) {
    fill(distance, distance + total_nodes, INF);
    fill(in_queue, in_queue + total_nodes, false);
    fill(parent_edge, parent_edge + total_nodes, -1);

    queue<int> q;
    distance[source] = 0;
    in_queue[source] = true;
    q.push(source);

    while (!q.empty()) {
        int u = q.front(); q.pop();
        in_queue[u] = false;

        for (int i = first_edge[u]; i != -1; i = graph[i].next_edge) {
            int v = graph[i].destination;
            if (graph[i].capacity > graph[i].flow && distance[v] > distance[u] + graph[i].cost) {
                distance[v] = distance[u] + graph[i].cost;
                parent_edge[v] = i;
                if (!in_queue[v]) {
                    in_queue[v] = true;
                    q.push(v);
                }
            }
        }
    }

    return parent_edge[sink] != -1;
}

int min_cost_flow(int source, int sink) {
    int total_flow = 0, total_cost = 0;

    while (shortest_path(source, sink)) {
        int bottleneck = INF;
        for (int i = parent_edge[sink]; i != -1; i = parent_edge[graph[i ^ 1].destination]) {
            bottleneck = min(bottleneck, graph[i].capacity - graph[i].flow);
        }

        for (int i = parent_edge[sink]; i != -1; i = parent_edge[graph[i ^ 1].destination]) {
            graph[i].flow += bottleneck;
            graph[i ^ 1].flow -= bottleneck;
            total_cost += graph[i].cost * bottleneck;
        }

        total_flow += bottleneck;
    }

    return total_cost;
}

