inline bool lt(int u, int v) {
	return pi[u] < pi[v] || (pi[u] == pi[v] && kk[u] < kk[v]);
}

int get_child(int i) {
	i *= 2;
	if (i > pq_size) return 0;
	if (i < pq_size && lt(pq[i+1], pq[i])) return i+1;
	return i;
}

void heap_up(int u) {
	int i = iq[u];
	int j;
	while ((j = i / 2) && lt(u, pq[j])) {
		pq[iq[pq[j]] = i] = pq[j];
		i = j;
	}
	pq[iq[u] = i] = u;
}

void heap_down(int u) {
	int i = iq[u];
	int j;
	while ((j = get_child(i)) && lt(pq[j], u)) {
		pq[iq[pq[j]] = i] = pq[j];
		i = j;
	}
	pq[iq[u] = i] = u;
}

void heap_insert(int u) {
	iq[u] = ++pq_size;
	heap_up(u);
}

int heap_extract() {
	int u = pq[1];
	int v = pq[pq_size--];
	iq[v] = 1;
	heap_down(v);
	return u;
}

