    int to, next, val, w;
};

struct FlowResult {
    int c, f;
};

int n, m, k, c_val, d_val, s, t, tot;
int head[N], pre[N], edge_id = 1;
Edge e[8 * N * (int)sqrt(N) + 10];
vector<pii> edges;

void add_edge(int u, int v, int val, int w) {
    edge_id++;
    e[edge_id].next = head[u];
    e[edge_id].to = v;
    e[edge_id].val = val;
    e[edge_id].w = w;
    head[u] = edge_id;
}

void add(int u, int v, int val, int w) {
    add_edge(u, v, val, w);
    add_edge(v, u, 0, -w);
}

int dis[N];
bool vis[N];

bool SPFA() {
    fill(dis + 1, dis + tot + 1, INF);
    queue<int> q;
    q.push(s);
    dis[s] = 0;
    memset(vis, 0, sizeof(vis));
    vis[s] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        vis[u] = false;
        for (int i = head[u]; i; i = e[i].next) {
            int v = e[i].to;
            if (e[i].val && dis[v] > dis[u] + e[i].w) {
                dis[v] = dis[u] + e[i].w;
                pre[v] = i;
                if (!vis[v]) {
                    vis[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return dis[t] < INF;
}

FlowResult mcmf() {
    FlowResult res = {0, 0};
    while (SPFA()) {
        int flow = INF;
        for (int x = t; x != s; x = e[pre[x] ^ 1].to)
            flow = min(flow, e[pre[x]].val);
        for (int x = t; x != s; x = e[pre[x] ^ 1].to) {
            e[pre[x]].val -= flow;
            e[pre[x] ^ 1].val += flow;
        }
        res.f += flow;
        res.c += dis[t] * flow;
    }
    return res;
}

#define P(i, j) ((i) * n + (j))

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m >> k >> c_val >> d_val;
    int cs = 2 * k;
    tot = cs * n;
    s = ++tot;
    t = ++tot;

    for (int i = 1; i <= k; i++) {
        int tp;
        cin >> tp;
        add(s, P(0, tp), 1, 0);
    }

    edges.resize(m);
    for (int i = 0; i < m; i++) {
        cin >> edges[i].fi >> edges[i].se;
    }

    for (int i = 1; i <= cs - 1; i++) {
        add(P(i, 1), t, k, c_val * i);
        for (int j = 1; j <= n; j++) {
            add(P(i - 1, j), P(i, j), k, 0);
        }
        for (int j = 0; j < m; j++) {
            int u = edges[j].fi, v = edges[j].se;
            for (int t_val = 1; t_val <= k; t_val++) {
                add(P(i - 1, u), P(i, v), 1, (2 * t_val - 1) * d_val);
                add(P(i - 1, v), P(i, u), 1, (2 * t_val - 1) * d_val);
            }
        }
    }

    cout << mcmf().c << endl;
    return 0;
}

