void init_graph(int nodes) {
    NODES = nodes;
    head.assign(nodes, -1);
    next_edge.resize(MAX_M);
    to.resize(MAX_M);
    cap.resize(MAX_M);
    cost.resize(MAX_M);
}

void add_edge(int u, int v, int c, int w) {
    to[edge_id] = v;
    cap[edge_id] = c;
    cost[edge_id] = w;
    next_edge[edge_id] = head[u];
    head[u] = edge_id++;
}

void add_flow(int u, int v, int c, int w) {
    add_edge(u, v, c, w);
    add_edge(v, u, 0, -w);
}

int dist[MAX_N];
int pre[MAX_N];
bool inq[MAX_N];

bool spfa() {
    fill(dist, dist + NODES, INF);
    queue<int> q;
    q.push(S);
    dist[S] = 0;
    memset(inq, 0, sizeof(inq));
    inq[S] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        inq[u] = false;

        for (int i = head[u]; ~i; i = next_edge[i]) {
            int v = to[i];
            if (cap[i] > 0 && dist[v] > dist[u] + cost[i]) {
                dist[v] = dist[u] + cost[i];
                pre[v] = i;
                if (!inq[v]) {
                    inq[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return dist[T] < INF;
}

pii min_cost_max_flow() {
    pii res = {0, 0};
    while (spfa()) {
        int f = INF;
        for (int x = T; x != S; x = to[pre[x] ^ 1]) {
            f = min(f, cap[pre[x]]);
        }
        for (int x = T; x != S; x = to[pre[x] ^ 1]) {
            cap[pre[x]] -= f;
            cap[pre[x] ^ 1] += f;
        }
        res.first += f;
        res.second += f * dist[T];
    }
    return res;
}

