constexpr int MAX_N = 5005;
constexpr int MAX_E = 4 * MAX_N * (int)sqrt(MAX_N) + 100;
constexpr int INF = 1e9;

struct Edge {
    int to, cap, cost, rev;
};

struct MCMF {
    int N, S, T;
    vector<vector<Edge>> g;
    vector<int> dist, prevv, preve;

    MCMF(int n, int s, int t) : N(n), S(s), T(t),
        g(n), dist(n), prevv(n), preve(n) {}

    void link(int u, int v, int cap, int cost) {
        g[u].emplace_back(Edge{v, cap, cost, (int)g[v].size()});
        g[v].emplace_back(Edge{u, 0, -cost, (int)g[u].size() - 1});
    }

    pii solve() {
        pii result = {0, 0};
        while (true) {
            fill(dist.begin(), dist.end(), INF);
            dist[S] = 0;
            vector<bool> inq(N, false);
            queue<int> q;
            q.push(S);
            inq[S] = true;

            while (!q.empty()) {
                int u = q.front(); q.pop();
                inq[u] = false;

                for (int i = 0; i < (int)g[u].size(); ++i) {
                    auto& e = g[u][i];
                    if (e.cap > 0 && dist[e.to] > dist[u] + e.cost) {
                        dist[e.to] = dist[u] + e.cost;
                        prevv[e.to] = u;
                        preve[e.to] = i;
                        if (!inq[e.to]) {
                            inq[e.to] = true;
                            q.push(e.to);
                        }
                    }
                }
            }

            if (dist[T] == INF) break;

            int flow = INF;
            for (int v = T; v != S; v = prevv[v])
                flow = min(flow, g[prevv[v]][preve[v]].cap);

            result.first += flow;
            result.second += flow * dist[T];

            for (int v = T; v != S; v = prevv[v]) {
                Edge& e = g[prevv[v]][preve[v]];
                e.cap -= flow;
                g[v][e.rev].cap += flow;
            }
        }
        return result;
    }
};

int idx(int i, int j, int n) { return i * n + j; }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    int cs = 2 * k;
    int total = cs * n + 2;
    int src = total - 2, dst = total - 1;

    MCMF solver(total, src, dst);

    for (int i = 0; i < k; ++i) {
        int tp;
        cin >> tp;
        solver.link(src, idx(0, tp, n), 1, 0);
    }

    vector<pii> E(m);
    for (int i = 0; i < m; ++i) {
        cin >> E[i].first >> E[i].second;
    }

    for (int layer = 1; layer <= cs - 1; ++layer) {
        solver.link(idx(layer, 1, n), dst, k, c * layer);
        for (int node = 1; node <= n; ++node) {
            solver.link(idx(layer - 1, node, n), idx(layer, node, n), k, 0);
        }
        for (int i = 0; i < m; ++i) {
            int u = E[i].first, v = E[i].second;
            for (int t = 1; t <= k; ++t) {
                int w = (2 * t - 1) * d;
                solver.link(idx(layer - 1, u, n), idx(layer, v, n), 1, w);
                solver.link(idx(layer - 1, v, n), idx(layer, u, n), 1, w);
            }
        }
    }

    cout << solver.solve().second << endl;
    return 0;
}

