    i64 flow;
    i64 cost_val;
};

class MinCostFlowSolver {
public:
    int n;
    vector<int> g[MAX_NODE_LIMIT];
    vector<Edge> e;
    i64 dist[MAX_NODE_LIMIT];
    bool vis[MAX_NODE_LIMIT];
    int par_edge[MAX_NODE_LIMIT];
    i64 cap_on_path[MAX_NODE_LIMIT];

    MinCostFlowSolver(int total_nodes) : n(total_nodes) {}

    void link(int u, int v, i64 cap, i64 c) {
        e.push_back({u, v, cap, 0, c});
        e.push_back({v, u, 0, 0, -c});
        int idx = e.size();
        g[u].push_back(idx - 2);
        g[v].push_back(idx - 1);
    }

    bool find_path(i64 &f, i64 &c) {
        fill(dist, dist + n, INF);
        fill(vis, vis + n, false);
        queue<int> q;
        dist[0] = 0;
        vis[0] = true;
        cap_on_path[0] = INF;
        q.push(0);

        while (!q.empty()) {
            int u = q.front(); q.pop();
            vis[u] = false;
            for (int idx : g[u]) {
                Edge &ed = e[idx];
                if (ed.capacity > ed.flow && dist[ed.dst] > dist[u] + ed.cost_val) {
                    dist[ed.dst] = dist[u] + ed.cost_val;
                    par_edge[ed.dst] = idx;
                    cap_on_path[ed.dst] = min(cap_on_path[u], ed.capacity - ed.flow);
                    if (!vis[ed.dst]) {
                        vis[ed.dst] = true;
                        q.push(ed.dst);
                    }
                }
            }
        }

        if (dist[1] == INF) return false;
        f = cap_on_path[1];
        c = dist[1];
        int cur = 1;
        while (cur != 0) {
            int idx = par_edge[cur];
            e[idx].flow += f;
            e[idx ^ 1].flow -= f;
            cur = e[idx].src;
        }
        return true;
    }

    pair<i64, i64> mincost(int src, int dst) {
        int orig_n = n;
        i64 total_flow = 0, total_cost = 0;
        i64 f, c;

        while (find_path(f, c)) {
            total_flow += f;
            total_cost += f * c;
        }

        return make_pair(total_flow, total_cost);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, C, D;
    cin >> n >> m >> k >> C >> D;

    MinCostFlowSolver g(n * MAX_T + 2);
    int source_id = n * MAX_T;
    int sink_id   = n * MAX_T + 1;

    for (int t = 0; t < MAX_T; ++t)
        g.link(t, sink_id, k, C * t);

    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        --x;
        g.link(source_id, x * MAX_T, 1, 0);
    }

    for (int i = 0; i < n; ++i)
        for (int t = 1; t < MAX_T; ++t)
            g.link(i * MAX_T + t - 1, i * MAX_T + t, k, 0);

    while (m--) {
        int u, v;
        cin >> u >> v;
        --u, --v;

        for (int t = 1; t < MAX_T; ++t) {
            int a = u * MAX_T + t - 1;
            int b = v * MAX_T + t;
            int c = v * MAX_T + t - 1;
            int d = u * MAX_T + t;

            for (int i = 1, cc = D; i <= k; ++i, cc += 2 * D) {
                g.link(a, b, 1, cc);
                g.link(c, d, 1, cc);
            }
        }
    }

    auto ans = g.mincost(source_id, sink_id);
    cout << ans.second << '\n';

    return 0;
}

#include <bits/stdc++.h>
