typedef long long ll;
const ll INF = 1000000007LL;
const int MAXN = 5005;
const int MAXT = 100;

struct Edge {
    int u, v;
    ll cap, flow, cost;
};

class MinCostFlow {
public:
    int n;
    vector<int> G[MAXN];
    vector<Edge> edges;
    ll dis[MAXN];
    bool inq[MAXN];
    int pre[MAXN];
    ll a[MAXN];

    MinCostFlow(int nodes) : n(nodes) {}

    void add_edge(int u, int v, ll cap, ll cost) {
        edges.push_back({u, v, cap, 0LL, cost});
        edges.push_back({v, u, 0LL, 0LL, -cost});
        int idx = edges.size();
        G[u].push_back(idx - 2);
        G[v].push_back(idx - 1);
    }

    bool spfa(int s, int t, ll &flow, ll &cost) {
        fill(dis, dis + n, INF);
        fill(inq, inq + n, false);
        dis[s] = 0;
        inq[s] = true;
        pre[s] = -1;
        a[s] = INF;
        queue<int> q;
        q.push(s);

        while (!q.empty()) {
            int u = q.front(); q.pop();
            inq[u] = false;

            for (int eid : G[u]) {
                Edge &e = edges[eid];
                if (e.cap > e.flow && dis[e.v] > dis[u] + e.cost) {
                    dis[e.v] = dis[u] + e.cost;
                    pre[e.v] = eid;
                    a[e.v] = min(a[u], e.cap - e.flow);

                    if (!inq[e.v]) {
                        inq[e.v] = true;
                        q.push(e.v);
                    }
                }
            }
        }

        if (dis[t] == INF) return false;

        flow = a[t];
        cost = dis[t];

        int cur = t;
        while (pre[cur] != -1) {
            edges[pre[cur]].flow += a[t];
            edges[pre[cur] ^ 1].flow -= a[t];
            cur = edges[pre[cur]].u;
        }
        return true;
    }

    pair<ll, ll> solve(int s, int t) {
        ll total_flow = 0, total_cost = 0;
        ll f, c;

        while (spfa(s, t, f, c)) {
            total_flow += f;
            total_cost += f * c;
        }

        return make_pair(total_flow, total_cost);
    }
};

