int residualCapacity(int x) {
  return e[x].capacity - e[x].flow;
}

void pushFlow() {
  FOR(i, 0, N) {
    dist[i] = INF64;
    pred[i] = -1;
    pe[i] = -1;
    inq[i] = 0;
  }
  dist[source] = 0;
  queue<int> q;
  q.push(source);
  inq[source] = 1;
  while (!q.empty()) {
    int k = q.front(); q.pop();
    inq[k] = 0;
    for (auto x : g[k]) {
      if (!residualCapacity(x)) {
        continue;
      }
      int cost = e[x].cost;
      int y = e[x].y;
      if (dist[y] > dist[k] + cost) {
        dist[y] = dist[k] + cost;
        pred[y] = k;
        pe[y] = x;
        if (inq[y] == 0) {
          inq[y] = 1;
          q.push(y);
        }
      }
    }
  }
  int cur = target;
  //vec<int> zz(1, cur);
  while (cur != source) {
    e[pe[cur]].flow++;
    e[pe[cur] ^ 1].flow--;
    cur = pred[cur];
    //zz.push_back(cur);
  }
  //reverse(zz.begin(), zz.end());
  //for (auto x : zz) {cerr << x << " ";}
  //cerr << "\n";
  ans += dist[target];
}

