    sink_node = n - 1;
    for (int i = 0; i < n; ++i) graph[i].clear();
    edges.clear();
}

void add_edge(int from, int to, int cap, int cost, int type) {
    graph[from].push_back(edges.size());
    edges.emplace_back(to, cap, cost, type);
    graph[to].push_back(edges.size());
    if (type == 1) {
        edges.emplace_back(from, 0, -C_param + d_param, type);
    } else {
        edges.emplace_back(from, 0, -cost, type);
    }
}

int spfa() {
    fill(dist, dist + node_count, INT_MAX);
    fill(inq, inq + node_count, 0);
    dist[0] = 0;
    int qh = 0, qt = 0;
    queue_arr[qt++] = 0;

    while (qh < qt) {
        int u = queue_arr[qh++];
        inq[u] = 0;
        for (int idx : graph[u]) {
            Edge& e = edges[idx];
            if (e.cap > 0 && dist[u] + e.cost < dist[e.to]) {
                dist[e.to] = dist[u] + e.cost;
                prevv[e.to] = u;
                preve[e.to] = idx;
                if (!inq[e.to]) {
                    inq[e.to] = 1;
                    queue_arr[qt++] = e.to;
                }
            }
        }
    }

    if (dist[sink_node] == INT_MAX) return -1;

    int cur = sink_node;
    while (cur != 0) {
        int idx = preve[cur];
        if (edges[idx].type == 1) {
            if (idx & 1) {
                edges[idx].cost += 2 * d_param;
                edges[idx ^ 1].cost -= 2 * d_param;
            } else {
                edges[idx].cost += 2 * d_param;
                edges[idx ^ 1].cost -= 2 * d_param;
            }
        }
        edges[idx].cap--;
        edges[idx ^ 1].cap++;
        cur = prevv[cur];
    }
    return dist[sink_node];
}

int compute_flow(int iterations) {
    int total = 0;
    for (int i = 0; i < iterations; ++i) {
        int cost = spfa();
        if (cost == -1) break;
        total += cost;
    }
    return total;
}

