    Edge(int d, int c, int w, int t) : dest(d), capacity(c), weight(w), edge_type(t) {}
};

vector<Edge> edge_list;
vector<int> adj[MAX_NODES];
int distance[MAX_NODES], parent_node[MAX_NODES], parent_edge[MAX_NODES], in_queue[MAX_NODES];
int bfs_queue[MAX_NODES * 10];
int total_nodes, sink_node, C_value, d_value;

void reset_graph(int n) {
    total_nodes = n;
    sink_node = n - 1;
    for (int i = 0; i < n; ++i) adj[i].clear();
    edge_list.clear();
}

void insert_edge(int src, int dst, int cap, int wgt, int typ) {
    adj[src].push_back(edge_list.size());
    edge_list.emplace_back(dst, cap, wgt, typ);
    adj[dst].push_back(edge_list.size());
    if (typ == 1) {
        edge_list.emplace_back(src, 0, -C_value + d_value, typ);
    } else {
        edge_list.emplace_back(src, 0, -wgt, typ);
    }
}

int find_shortest_path() {
    fill(distance, distance + total_nodes, INT_MAX);
    fill(in_queue, in_queue + total_nodes, 0);
    distance[0] = 0;
    int qhead = 0, qtail = 0;
    bfs_queue[qtail++] = 0;

    while (qhead < qtail) {
        int u = bfs_queue[qhead++];
        in_queue[u] = 0;
        for (int idx : adj[u]) {
            Edge& e = edge_list[idx];
            if (e.capacity > 0 && distance[u] + e.weight < distance[e.dest]) {
                distance[e.dest] = distance[u] + e.weight;
                parent_node[e.dest] = u;
                parent_edge[e.dest] = idx;
                if (!in_queue[e.dest]) {
                    in_queue[e.dest] = 1;
                    bfs_queue[qtail++] = e.dest;
                }
            }
        }
    }

    if (distance[sink_node] == INT_MAX) return -1;

    int cur = sink_node;
    while (cur != 0) {
        int idx = parent_edge[cur];
        if (edge_list[idx].edge_type == 1) {
            if (idx & 1) {
                edge_list[idx].weight += 2 * d_value;
                edge_list[idx ^ 1].weight -= 2 * d_value;
            } else {
                edge_list[idx].weight += 2 * d_value;
                edge_list[idx ^ 1].weight -= 2 * d_value;
            }
        }
        edge_list[idx].capacity--;
        edge_list[idx ^ 1].capacity++;
        cur = parent_node[cur];
    }
    return distance[sink_node];
}

int compute_min_cost_flow(int num_paths) {
    int total_cost = 0;
    for (int i = 0; i < num_paths; ++i) {
        int cost = find_shortest_path();
        if (cost == -1) break;
        total_cost += cost;
    }
    return total_cost;
}

