#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <cstdio>
using namespace std;

using ll = long long;
const ll INF = 1e18;

struct Edge {
    int src, dst, cap, flow, cost;
    Edge(int s, int d, int c, int f, int co) : src(s), dst(d), cap(c), flow(f), cost(co) {}
};

vector<Edge> edgeList;
vector<int> adj[1000007];
ll dist[1000007];
int prevNode[1000007], prevEdge[1000007];
bool inQueue[1000007];

int srcNode = 1000005, dstNode = 1000006;
ll totalCost = 0;

int getResidual(int idx) {
    return edgeList[idx].cap - edgeList[idx].flow;
}

void dijkstra() {
    fill(dist, dist + 1000007, INF);
    fill(prevNode, prevNode + 1000007, -1);
    fill(prevEdge, prevEdge + 1000007, -1);
    fill(inQueue, inQueue + 1000007, false);

    dist[srcNode] = 0;
    queue<int> q;
    q.push(srcNode);
    inQueue[srcNode] = true;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        inQueue[u] = false;

        for (int idx : adj[u]) {
            if (!getResidual(idx)) continue;
            int v = edgeList[idx].src;
            int cost = edgeList[idx].cost;
            if (dist[v] > dist[u] + cost) {
                dist[v] = dist[u] + cost;
                prevNode[v] = u;
                prevEdge[v] = idx;
                if (!inQueue[v]) {
                    inQueue[v] = true;
                    q.push(v);
                }
            }
        }
    }
}

void augmentPath() {
    dijkstra();
    if (dist[dstNode] >= INF) return;

    int cur = dstNode;
    while (cur != srcNode) {
        int idx = prevEdge[cur];
        edgeList[idx].flow++;
        edgeList[idx ^ 1].flow--;
        cur = prevNode[cur];
    }
    totalCost += dist[dstNode];
}

void addEdge(int u, int v, int cap, int cost) {
    adj[u].push_back(edgeList.size());
    edgeList.emplace_back(u, v, cap, 0, cost);
    adj[v].push_back(edgeList.size());
    edgeList.emplace_back(v, u, 0, 0, -cost);
}

int n, m, k, c, d;
const int TIME_LAYERS = 101;

void buildGraph() {
    scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);

    for (int i = 0; i < k; ++i) {
        int x; scanf("%d", &x); --x;
        addEdge(srcNode, x, 1, 0);
    }

    for (int t = 0; t < TIME_LAYERS; ++t) {
        addEdge(t * n, dstNode, k, t * c);
    }

    for (int i = 0; i < m; ++i) {
        int u, v; scanf("%d %d", &u, &v); --u, --v;
        for (int t = 0; t < TIME_LAYERS - 1; ++t) {
            for (int j = 0; j < k; ++j) {
                addEdge(u + t * n, v + (t + 1) * n, 1, d * (2 * j + 1));
            }
        }
        for (int t = 0; t < TIME_LAYERS - 1; ++t) {
            for (int j = 0; j < k; ++j) {
                addEdge(v + t * n, u + (t + 1) * n, 1, d * (2 * j + 1));
            }
        }
    }
}

void runSolver() {
    for (int t = 0; t < TIME_LAYERS - 1; ++t) {
        for (int i = 0; i < n; ++i) {
            addEdge(i + t * n, i + (t + 1) * n, k, 0);
        }
    }

    for (int i = 0; i < k; ++i) {
        augmentPath();
    }

    printf("%lld\n", totalCost);
}

int main() {
    buildGraph();
    runSolver();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = 1e18;

struct Edge {
    int from, to, cap, flow, cost;
    Edge() {}
    Edge(int f, int t, int c, int fl, int co) : from(f), to(t), cap(c), flow(fl), cost(co) {}
};

vector<Edge> edges;
vector<int> graph[1000007];
ll d[1000007];
int parent[1000007], edgeIdx[1000007];
bool inq[1000007];

int S = 1000005, T = 1000006;
ll total = 0;

inline int residual(int i) { return edges[i].cap - edges[i].flow; }

void spfa() {
    fill(d, d + 1000007, INF);
    fill(parent, parent + 1000007, -1);
    fill(edgeIdx, edgeIdx + 1000007, -1);
    fill(inq, inq + 1000007, false);

    d[S] = 0;
    queue<int> q;
    q.push(S);
    inq[S] = true;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = false;

        for (int i : graph[u]) {
            if (!residual(i)) continue;
            int v = edges[i].from;
            int w = edges[i].cost;
            if (d[v] > d[u] + w) {
                d[v] = d[u] + w;
                parent[v] = u;
                edgeIdx[v] = i;
                if (!inq[v]) {
                    inq[v] = true;
                    q.push(v);
                }
            }
        }
    }
}

void augment() {
    spfa();
    if (d[T] >= INF) return;

    int cur = T;
    while (cur != S) {
        int idx = edgeIdx[cur];
        edges[idx].flow++;
        edges[idx ^ 1].flow--;
        cur = parent[cur];
    }
    total += d[T];
}

void link(int u, int v, int cap, int cost) {
    graph[u].push_back(edges.size());
    edges.emplace_back(u, v, cap, 0, cost);
    graph[v].push_back(edges.size());
    edges.emplace_back(v, u, 0, 0, -cost);
}

int n, m, k, c, d;
const int LAYERS = 101;

void construct() {
    scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);

    for (int i = 0; i < k; ++i) {
        int x; scanf("%d", &x); --x;
        link(S, x, 1, 0);
    }

    for (int t = 0; t < LAYERS; ++t) {
        link(t * n, T, k, t * c);
    }

    for (int i = 0; i < m; ++i) {
        int u, v; scanf("%d %d", &u, &v); --u, --v;
        for (int t = 0; t < LAYERS - 1; ++t) {
            for (int j = 0; j < k; ++j) {
                link(u + t * n, v + (t + 1) * n, 1, d * (2 * j + 1));
            }
        }
        for (int t = 0; t < LAYERS - 1; ++t) {
            for (int j = 0; j < k; ++j) {
                link(v + t * n, u + (t + 1) * n, 1, d * (2 * j + 1));
            }
        }
    }
}

void process() {
    for (int t = 0; t < LAYERS - 1; ++t) {
        for (int i = 0; i < n; ++i) {
            link(i + t * n, i + (t + 1) * n, k, 0);
        }
    }

    for (int i = 0; i < k; ++i) {
        augment();
    }

    printf("%lld\n", total);
}

int main() {
    construct();
    process();
    return 0;
}

