using namespace std;

struct Edge {
    int dest;
    int capacity;
    int flow;
    int cost;
    Edge() : dest(0), capacity(0), flow(0), cost(0) {}
    Edge(int d, int c, int f, int co) : dest(d), capacity(c), flow(f), cost(co) {}
};

vector<Edge> edgeList;
const int MAX_N = 14043;
vector<int> graph[MAX_N];

long long minCost = 0;
long long distance[MAX_N];
int prevNode[MAX_N];
int prevEdge[MAX_N];
bool inQueue[MAX_N];

const long long INF = 1000000000000000000LL;

int src = MAX_N - 2;
int dst = MAX_N - 1;

int residual(int idx) {
    return edgeList[idx].capacity - edgeList[idx].flow;
}

void findShortestPath() {
    fill(distance, distance + MAX_N, INF);
    fill(prevNode, prevNode + MAX_N, -1);
    fill(prevEdge, prevEdge + MAX_N, -1);
    fill(inQueue, inQueue + MAX_N, false);

    distance[src] = 0;
    queue<int> q;
    q.push(src);
    inQueue[src] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        inQueue[u] = false;

        for (int idx : graph[u]) {
            if (residual(idx) <= 0) continue;
            int v = edgeList[idx].dest;
            int w = edgeList[idx].cost;
            if (distance[v] > distance[u] + w) {
                distance[v] = distance[u] + w;
                prevNode[v] = u;
                prevEdge[v] = idx;
                if (!inQueue[v]) {
                    inQueue[v] = true;
                    q.push(v);
                }
            }
        }
    }

    int cur = dst;
    while (cur != src) {
        int idx = prevEdge[cur];
        edgeList[idx].flow += 1;
        edgeList[idx ^ 1].flow -= 1;
        cur = prevNode[cur];
    }

    if (distance[dst] < INF) {
        minCost += distance[dst];
    }
}

void connect(int u, int v, int cap, int cost) {
    graph[u].push_back(edgeList.size());
