void addEdge(int u, int v, int capacity, int cost) {
    edges.push_back({u, v, 0, capacity, cost});
    adj[u].push_back(edges.size() - 1);
    edges.push_back({v, u, 0, 0, -cost});
    adj[v].push_back(edges.size() - 1);
}

int dist[MAX_N + 2], inq[MAX_N + 2], minFlow[MAX_N + 2], parentEdge[MAX_N + 2];

pair<int, int> spfa(int n) {
    fill(dist, dist + n + 2, INF);
    queue<int> q;
    q.push(source);
    dist[source] = 0;
    inq[source] = 1;
    minFlow[source] = INF;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = 0;
        for (int id : adj[u]) {
            int v = edges[id].to;
            if (edges[id].cap > edges[id].flow && dist[v] > dist[u] + edges[id].cost) {
                dist[v] = dist[u] + edges[id].cost;
                parentEdge[v] = id;
                minFlow[v] = min(minFlow[u], edges[id].cap - edges[id].flow);
                if (!inq[v]) {
                    q.push(v);
                    inq[v] = 1;
                }
            }
        }
    }

    if (dist[sink] == INF) return {0, 0};

    int augment = minFlow[sink];
    int cur = sink;
    while (cur != source) {
        int eid = parentEdge[cur];
        edges[eid].flow += augment;
        edges[eid ^ 1].flow -= augment;
        cur = edges[eid].from;
    }

    return {augment, augment * dist[sink]};
}

pair<int, int> mcmf(int n) {
    int totalFlow = 0, totalCost = 0;
    while (true) {
        auto [flow, cost] = spfa(n);
        if (flow == 0) break;
        totalFlow += flow;
        totalCost += cost;
    }
    return {totalFlow, totalCost};
}

