                    in_queue[v] = 1;
                }
            }
        }
    }

    if (distance[sink_node] == INF) return {0, 0};

    int augment = flow_limit[sink_node];
    int cur = sink_node;
    while (cur != source_node) {
        int eid = prev_edge[cur];
        edge_list[eid].flow += augment;
        edge_list[eid ^ 1].flow -= augment;
        cur = edge_list[eid].src;
    }

    return {augment, augment * distance[sink_node]};
}

