    e.push_back({v, u, 0, 0, -cost});
    adj[v].push_back(e.size() - 1);
}

int dist[MAXN], inq[MAXN], flow[MAXN], par[MAXN];

pii spfa(int n) {
    fill(dist, dist + n + 2, INF);
    queue<int> q;
    q.push(src);
    dist[src] = 0;
    inq[src] = 1;
    flow[src] = INF;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = 0;
        for (int id : adj[u]) {
            int v = e[id].v;
            if (e[id].c > e[id].f && dist[v] > dist[u] + e[id].w) {
                dist[v] = dist[u] + e[id].w;
                par[v] = id;
                flow[v] = min(flow[u], e[id].c - e[id].f);
                if (!inq[v]) {
                    q.push(v);
                    inq[v] = 1;
                }
            }
        }
    }

    if (dist[dst] == INF) return {0, 0};

    int aug = flow[dst];
    int cur = dst;
    while (cur != src) {
        int id = par[cur];
        e[id].f += aug;
        e[id ^ 1].f -= aug;
        cur = e[id].u;
    }

    return {aug, aug * dist[dst]};
}

pii mcmf(int n) {
    int flow_sum = 0, cost_sum = 0;
    while (true) {
        pii res = spfa(n);
        if (res.first == 0) break;
        flow_sum += res.first;
        cost_sum += res.second;
    }
