        if r > n // 2:
            r = n - r
        for i in range(n, n - r, -1):
            ret *= i
        for i in range(2, r + 1):
            ret //= i
        return ret

class Sort:
    def __init__(self, n: int):
        self.N = n
        self.tmp = [0] * (n + 4)

    def merge_sort(self, x: List[int], lo: int, hi: int):
        if lo >= hi:
            return
        mid = (lo + hi) // 2
        self.merge_sort(x, lo, mid)
        self.merge_sort(x, mid + 1, hi)
        i, j, k = lo, mid + 1, lo
        while i <= mid and j <= hi:
            if x[i] < x[j]:
                self.tmp[k] = x[i]
                i += 1
            else:
                self.tmp[k] = x[j]
                j += 1
            k += 1
        while i <= mid:
            self.tmp[k] = x[i]
            i += 1
            k += 1
        while j <= hi:
            self.tmp[k] = x[j]
            j += 1
            k += 1
        for i in range(lo, hi + 1):
            x[i] = self.tmp[i]

class PSum:
    def makeSum1D(self, a: List[int]) -> List[int]:
        ret = [0] * len(a)
        ret[0] = a[0]
        for i in range(1, len(a)):
            ret[i] = ret[i - 1] + a[i]
        return ret

    def makeSum2D(self, a: List[List[int]], n: int, m: int) -> List[List[int]]:
        ret = [[0] * m for _ in range(n)]
        for i in range(n):
            ret[i][0] = a[i][0]
        for i in range(n):
            for j in range(1, m):
                ret[i][j] = ret[i][j - 1] + a[i][j]
        return ret

    def getSum1D(self, psum: List[int], a: int, b: int) -> int:
        if a == 0:
            return psum[b]
        return psum[b] - psum[a - 1]

    def getSum2D(self, psum: List[List[int]], r1: int, c1: int, r2: int, c2: int) -> int:
        ret = psum[r2][c2]
        if r1 > 0:
            ret -= psum[r1 - 1][c2]
        if c1 > 0:
            ret -= psum[r2][c1 - 1]
        if r1 > 0 and c1 > 0:
            ret += psum[r1 - 1][c1 - 1]
        return ret

class DisjointSet:
    def __init__(self, n: int):
        self.N = n
        self.P = list(range(n + 1))
        self.R = [0] * (n + 1)
        self.A = [1] * (n + 1)

    def getA(self, x: int) -> int:
        return self.A[x]

    def find_set(self, x: int) -> int:
        if self.P[x] == x:
            return x
        pa = self.find_set(self.P[x])
        self.P[x] = pa
        return pa

    def union_set(self, x: int, y: int) -> int:
        px = self.find_set(x)
        py = self.find_set(y)
        if px == py:
            return px
        if self.R[px] > self.R[py]:
            self.P[py] = px
            self.A[px] += self.A[py]
            return px
        else:
            self.P[px] = py
            self.A[py] += self.A[px]
            if self.R[px] == self.R[py]:
                self.R[py] += 1
            return py

class LIS:
    def __init__(self, n: int):
        self.N = n

    def execute(self, A: List[int]) -> int:
        v = []
        vi = -1
        if A:
            v.append(A[0])
            vi = 0
        for i in range(1, len(A)):
            if A[i] > v[vi]:
                v.append(A[i])
                vi += 1
                continue
            lo, hi = 0, vi
            while lo < hi:
                mid = (lo + hi) // 2
                if v[mid] >= A[i]:
                    hi = mid
                else:
                    lo = mid + 1
            v[hi] = A[i]
        return vi + 1

    def execute2(self, A: List[int]) -> Tuple[List[int], int]:
        v = []
        v1 = []
        p = [-1] * len(A)
        if A:
            v.append(A[0])
            v1.append(0)
        for i in range(1, len(A)):
            if v[-1] < A[i]:
                p[i] = v1[-1]
                v.append(A[i])
                v1.append(i)
            else:
                idx = 0
                while idx < len(v) and v[idx] < A[i]:
                    idx += 1
                if idx < len(v):
                    v[idx] = A[i]
                    if idx != 0:
                        p[i] = v1[idx - 1]
                    v1[idx] = i
        length = len(v1)
        ret = [0] * length
        i = v1[-1]
        j = length - 1
        while i != -1:
            ret[j] = A[i]
            i = p[i]
            j -= 1
        return ret, length

    def execute3(self, A: List[int]) -> int:
        v = [0] * len(A)
        for i in range(len(A)):
            for j in range(i):
                if A[j] < A[i] and v[i] < v[j]:
                    v[i] = v[j]
            v[i] += 1
        return max(v) if v else 0

class SegmentTreeSum:
    def __init__(self, n: int):
        self.N = n
        self.ST = [0] * (n * 4 + 4)
        self.A = [0] * (n + 4)

    def _init(self, a: List[int], left: int, right: int, node: int) -> int:
        if left == right:
            self.ST[node] = a[left]
            return self.ST[node]
        mid = (left + right) // 2
        lv = self._init(a, left, mid, node * 2)
        rv = self._init(a, mid + 1, right, node * 2 + 1)
        self.ST[node] = lv + rv
        return self.ST[node]

    def _query(self, left: int, right: int, node: int, nodeLeft: int, nodeRight: int) -> int:
        if right < nodeLeft or nodeRight < left:
            return 0
        if left <= nodeLeft and nodeRight <= right:
            return self.ST[node]
        mid = (nodeLeft + nodeRight) // 2
        lv = self._query(left, right, node * 2, nodeLeft, mid)
        rv = self._query(left, right, node * 2 + 1, mid + 1, nodeRight)
        return lv + rv

    def _update(self, index: int, newValue: int, node: int, nodeLeft: int, nodeRight: int) -> int:
        if index < nodeLeft or nodeRight < index:
            return self.ST[node]
        if nodeLeft == nodeRight:
            self.ST[node] = newValue
            return self.ST[node]
        mid = (nodeLeft + nodeRight) // 2
        lv = self._update(index, newValue, node * 2, nodeLeft, mid)
        rv = self._update(index, newValue, node * 2 + 1, mid + 1, nodeRight)
        self.ST[node] = lv + rv
        return self.ST[node]

    def setA(self, x: int, y: int):
        self.A[x] = y

    def init(self):
        self._init(self.A, 1, self.N, 1)

    def query(self, left: int, right: int) -> int:
