class TreeFromExpression:
    def make(self, s: str) -> Tuple[List[Tuple[int, int]], int]:
        cur = 1
        E = [(0, 0)] * 10000
        S = []
        for cc in s:
            if '1' <= cc <= '9':
                E[cur] = (ord(cc) - ord('0'), 0)
                S.append(cur)
                cur += 1
            elif cc == ')':
                a = S.pop()
                b = S.pop()
                E[cur] = (a, b)
                S.append(cur)
                cur += 1
        root = cur - 1
        return E, root

