import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    a = [0] * 5  # We only need up to 5 elements

    idx = 1
    if n - 0 > 0:
        a[0] = int(data[idx])
        idx += 1
    if n - 1 > 0:
        a[1] = int(data[idx])
        idx += 1
    if n - 2 > 0:
        a[2] = int(data[idx])
        idx += 1
    if n - 3 > 0:
        a[3] = int(data[idx])
        idx += 1
    if n == 5:
        a[4] = int(data[idx])
        idx += 1

    # Bubble sort for the first n elements
    for i in range(n - 1):
        for j in range(n - i - 1):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]

    t = (a[0] + a[n - 1]) >> 1

    i = -1
    j = n

    while i < n - 1 and a[i + 1] <= t:
        i += 1

    while j > 0 and a[j - 1] >= t:
        j -= 1

    # Determine the result
    if i >= 0 and j < n:
        if a[i] - t < t - a[j] and (i == 0 or a[i - 1] - t > a[i] - t):
            result = a[i]
        elif i >= 1 and a[i - 1] - t < t - a[j]:
            result = a[i - 1]
        else:
            result = a[j]
    elif i >= 0:
        result = a[i]
    else:
        result = a[j]

