import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    idx = 0
    real_n = int(data[idx]); idx += 1
    k = int(data[idx]); idx += 1

    real_p = []
    for i in range(real_n):
        real_p.append(float(data[idx])); idx += 1

    # Filter out probabilities <= 1e-4
    p = []
    id_list = []
    for i in range(real_n):
        if real_p[i] > 1e-4:
            id_list.append(i)
            p.append(real_p[i])

    n = len(p)
    k = min(k, n)

    # Precompute kb[t] = number of 1 bits in t
    max_mask = 1 << n
    kb = [0] * max_mask
    for t in range(1, max_mask):
        kb[t] = kb[t & (t - 1)] + 1

    # Initialize f array
    f = [0.0] * max_mask
    f[0] = 1.0

    # Initialize ans array
    ans = [0.0] * real_n

    # Process all masks
    for t in range(max_mask):
        if kb[t] == k:
            for j in range(n):
                if t & (1 << j):
                    ans[id_list[j]] += f[t]
            continue

        total = 0.0
        for j in range(n):
            if not (t & (1 << j)):
                total += p[j]

        q = f[t] / total if total != 0 else 0.0

        for j in range(n):
            if not (t & (1 << j)):
                f[t | (1 << j)] += p[j] * q

    # Output results
    output = []
    for i in range(real_n):
        if i > 0:
            output.append(' ')
        output.append('{:.17f}'.format(ans[i]))
