from functools import lru_cache

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    p = [float(data[2 + i]) for i in range(n)]

    # Precompute bit counts
    def bit_count(x):
        return bin(x).count('1')

    EPS = 1e-9

    def solve(vr):
        if p[vr] < EPS:
            return 0.0

        # dp[msk] = (a, b) representing a * alp + b
        dp = {}
        dp[0] = (1.0, 0.0)

        total_masks = 1 << n

        for msk in range(1, total_masks):
            if msk & (1 << vr):
                continue

            ri_a, ri_b = 0.0, 0.0
            same = 0.0

            for i in range(n):
                if i != vr and (msk & (1 << i)):
                    same += p[i]
                    prev_msk = msk ^ (1 << i)
                    prev_a, prev_b = dp[prev_msk]
                    # Multiply dp[prev_msk] by p[i] and add to ri
                    ri_a += p[i] * prev_a
                    ri_b += p[i] * prev_b

            # dp[msk] = ri / (1 - same)
            denom = 1.0 - same
            dp[msk] = (ri_a / denom, ri_b / denom)

        # Calculate total
        tot_a, tot_b = 1.0, 0.0
        for msk in range(1, total_masks):
            if not (msk & (1 << vr)):
                a, b = dp[msk]
                tot_a += a
                tot_b += b

        alp = (1.0 - tot_b) / tot_a

        # Calculate bad
