    return f"{val:.12f}"

def solve(n: int, k: int, p: List[float], vr: int) -> float:
    EPS = 1e-9

    if p[vr] < EPS:
        return 0.0

    # dp[msk] = (a, b) representing a * alp + b
    dp = {}

    dp[0] = (1.0, 0.0)

    # Iterate over all masks
    for msk in range(1, 1 << n):
        if msk & (1 << vr):
            continue

        ri = (0.0, 0.0)
        same = 0.0

        for i in range(n):
            if i != vr and (msk & (1 << i)):
                same += p[i]
                prev_msk = msk ^ (1 << i)
                # Multiply dp[prev_msk] by p[i] and add to ri
                prev_val = dp[prev_msk]
                ri = (ri[0] + prev_val[0] * p[i], ri[1] + prev_val[1] * p[i])

        # dp[msk] = ri / (1.0 - same)
        denom = 1.0 - same
        dp[msk] = (ri[0] / denom, ri[1] / denom)

