        int bits = __builtin_popcount(mask);
        if (bits > k || dp[mask] < 1e-100) continue;
        double remaining = 1.0 - sum_mask[mask];
        if (remaining < 1e-6) continue;
        for (int i = 0; i < n; ++i) {
