    bits = [0] * M
    sums = [0.0] * M

    for mask in range(M):
        for j in range(n):
            if (mask >> j) & 1:
                bits[mask] += 1
                sums[mask] += p[j]

    coef = [0.0] * k
    coef[k - 1] = 1.0
    for i in range(k - 2, -1, -1):
