using namespace std;
using ll = long long;
const int MOD = 1000000007;

ll mod_pow(ll base, ll exp, ll mod) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

struct DSU {
    vector<int> parent, rank;

    void init(int n) {
        parent.resize(n);
        rank.resize(n, 1);
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    void merge(int x, int y) {
        x = find(x), y = find(y);
        if (x == y) return;
        if (rank[x] < rank[y]) swap(x, y);
        parent[y] = x;
        rank[x] += rank[y];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    if (k == 0) {
        cout << mod_pow(n, n - 1, MOD) << '\n';
        return 0;
    }

    DSU dsu;
    dsu.init(n);

    for (int i = 0; i < n; ++i) {
        dsu.merge(i, (1LL * i * k) % n);
    }

    ll answer = 1;
    for (int i = 0; i < n; ++i) {
        if (dsu.find(i) != i) continue;
        ll cycle_length = dsu.rank[i];
        ll value = mod_pow(k, cycle_length, n);
        if (value == 1) {
            answer = (answer * n) % MOD;
        }
    }

    cout << answer << '\n';
    return 0;
}

