#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

constexpr int64 MOD = 1000000007LL;

int64 pow_mod(int64 base, int64 exp) {
    int64 result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

struct UnionFind {
    vector<int> parent;
    vector<int> height;
    int numComponents;

    explicit UnionFind(int size) : parent(size), height(size, 0), numComponents(size) {
        for (int i = 0; i < size; ++i) parent[i] = i;
    }

    int find(int node) {
        if (parent[node] != node) {
            parent[node] = find(parent[node]);
        }
        return parent[node];
    }

    void connect(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (height[a] > height[b]) {
            swap(a, b);
        }
        parent[a] = b;
        if (height[a] == height[b]) ++height[b];
        --numComponents;
    }

    int getComponentCount() const { return numComponents; }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 p, k;
    cin >> p >> k;

    vector<char> visited(p, 0);
    UnionFind uf(p);

    for (int64 start = 0; start < p; ++start) {
        for (int64 pos = start; !visited[pos]; pos = (pos * k) % p) {
            visited[pos] = 1;
            uf.connect(start, pos);
