struct DS {
    vector<int> par, lvl;
    int cnt;

    DS(int n) : par(n), lvl(n, 0), cnt(n) {
        for (int i = 0; i < n; ++i) par[i] = i;
    }

    int root(int x) {
        return par[x] == x ? x : par[x] = root(par[x]);
    }

    void join(int a, int b) {
        a = root(a), b = root(b);
        if (a == b) return;
        if (lvl[a] < lvl[b]) swap(a, b);
        par[b] = a;
        if (lvl[a] == lvl[b]) ++lvl[a];
        --cnt;
    }
};

