        rootX = self.find(x)
        rootY = self.find(y)
        if rootX == rootY:
            return

        if self.size[rootX] < self.size[rootY]:
            rootX, rootY = rootY, rootX
        self.parent[rootY] = rootX
        self.size[rootX] += self.size[rootY]

def main():
    import sys
    input_data = sys.stdin.read().split()
    P = int(input_data[0])
    K = int(input_data[1])

    uf = UnionFind(P)

    for i in range(1, P):
        val = (K * i) % P
        if val == 0:
            val = P
        uf.merge(i, val)

    roots = set()
    for i in range(1, P + 1):
        roots.add(uf.find(i))

    MOD = 1000000007
    if K == 0:
        result = binpow(P, P - 1, MOD)
    elif K == 1:
        result = binpow(P, P, MOD)
    else:
        result = binpow(P, len(roots), MOD)

    print(result)

if __name__ == "__main__":
