        cout << modPow(p, p) << '\n';
        return 0;
    }

    vector<int> visited(p, 0);
    vector<int> cycleCount(p, 0);

    for (int start = 1; start < p; start++) {
        if (visited[start]) continue;

        int current = start;
        int cycleLen = 0;

        do {
            visited[current] = 1;
            current = (current * k) % p;
            cycleLen++;
        } while (!visited[current]);

        cycleCount[cycleLen]++;
