#include <iostream>
#include <cstring>

using namespace std;

const long long MOD = 1000000007;

long long fastPow(long long b, long long e) {
    long long res = 1;
    for (; e; e >>= 1, b = b * b % MOD)
        if (e & 1) res = res * b % MOD;
    return res;
}

int main() {
    int p, k;
    cin >> p >> k;

    if (k == 0) {
        cout << fastPow(p, p - 1) << endl;
        return 0;
    }
    if (k == 1) {
        cout << fastPow(p, p) << endl;
        return 0;
    }

    bool vis[1000111];
    memset(vis, 0, sizeof(vis));
    int cnt[1000111] = {0};

    for (int i = 1; i < p; ++i) {
        if (vis[i]) continue;
        int cur = i, len = 0;
        while (!vis[cur]) {
            vis[cur] = true;
            cur = (1LL * cur * k) % p;
            ++len;
        }
        cnt[len]++;
    }

    long long result = 1;
    for (int i = 1; i < p; ++i) {
        if (!cnt[i]) continue;
        long long base = (1LL * i * cnt[i] + 1) % MOD;
        result = (result * fastPow(base, cnt[i])) % MOD;
    }

    cout << result << endl;
    return 0;
}

