    vector<int> cycle_lengths(p, 0);

    for (int i = 1; i < p; ++i) {
        if (visited[i]) continue;
        int current = i;
        int length = 0;

        while (!visited[current]) {
            visited[current] = true;
            current = (current * 1LL * k) % p;
            ++length;
        }

        cycle_lengths[length]++;
    }

    ll answer = 1;
