        if (cycle_lengths[len] == 0) continue;
        ll base = (1LL * len * cycle_lengths[len] + 1) % MOD;
        answer = (answer * mod_exp(base, cycle_lengths[len])) % MOD;
    }

    cout << answer << '\n';

    return 0;
}

