*/

/* theprof, Dec 1, 2015 */

#include <iostream>
#include <cmath>

#define MOD 1000000007

using namespace std;

int main() {
  int p, k;
  long long i;
  long long num = 1;
  long long q;

  // read input parameters
  cin >> p >> k;

  if (k <= 1) {
    long long loop_limit = p - 1 + k;
    for (q = 0; q < loop_limit; ++q) {
      num = (num * p) % MOD;
    }
  } else {
    bool used[p];
    for (int idx = 0; idx < p; ++idx) {
      used[idx] = false;
    }

    for (i = 1; i < p; ++i) {
      if (!used[i]) {
        num = (num * p) % MOD;
        used[i] = true;
        q = (i * k) % p;
        do {
          used[q] = true;
          q = (q * k) % p;
        } while (q != i);
      }
    }
  }
  cout << num << endl;
}

