#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1000000007;

ll modPow(ll base, ll exp) {
    ll result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

ll multiplicativeOrder(ll k, ll p) {
    if (k % p == 0) return 0;
    ll at = k % p;
    ll length = 1;
    while (at != 1) {
        at = (at * k) % p;
        length++;
        if (length > p) return 0; // Safety bound
    }
    return length;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll p, k;
    cin >> p >> k;

    if (k == 0) {
        cout << modPow(p, p - 1) << '\n';
    } else if (k == 1) {
        cout << modPow(p, p) << '\n';
    } else {
        ll order = multiplicativeOrder(k, p);
        if (order == 0) {
            cout << 0 << '\n';
        } else {
            ll exponent = (p - 1) / order;
            cout << modPow(p, exponent) << '\n';
        }
    }

    return 0;
}

