        if exp & 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp >>= 1
    return result

def multiplicative_order(k, p):
    if k % p == 0:
        return 0
    at = k % p
    length = 1
    while at != 1:
        at = (at * k) % p
        length += 1
        if length > p:
            return 0  # Safety bound
    return length

