	if ( x == parent[x] ) return x;
	return parent[x] = find(parent[x]);
}

void merge(int a, int b) {
	a = find(a); b = find(b);
	if ( a == b ) return;
	nc --;
	parent[b] = a;
}

ll fmp(ll x, int e) {
	if ( e == 0 ) return 1;
	ll w = fmp(x, e/2);
	w = (w * w) % MOD;
	if ( e&1 ) w = (w * x) % MOD;
	return w;
}

int main() {

	cin.tie(0);
	ios_base::sync_with_stdio(0);

	ll p, k;

	cin >> p >> k;

	if ( k == 0 ) {
		cout << fmp(p, p - 1) << '\n';
		return 0;
	}

	nc = p - (k > 1);

	for ( ll i = 1; i < p; i ++ ) parent[i] = i;

	for ( ll i = 1; i < p; i ++ )
		merge ( i, (i * k) % p );

	cout << fmp ( p, nc ) << '\n';

	return 0;
}

