    if e == 0:
        return 1
    w = fmp(x, e//2, MOD)
    w = (w * w) % MOD
    if e & 1:
        w = (w * x) % MOD
    return w

def main():
    import sys
    input = sys.stdin.readline

    p, k = map(int, input().split())

    if k == 0:
        print(fmp(p, p - 1))
        return

