#include <cmath>

using namespace std;

const long long MOD = 1000000007;

long long mod_pow(long long b, long long e) {
    long long r = 1;
    b %= MOD;
    while (e > 0) {
        if (e & 1) r = (r * b) % MOD;
        b = (b * b) % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    long long p, k;
    cin >> p >> k;

    if (k == 0) {
        cout << mod_pow(p, p - 1) << '\n';
        return 0;
    }

    vector<int> parent(p);
    for (int i = 0; i < p; ++i) parent[i] = i;

    function<int(int)> find = [&](int x) -> int {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    };

    auto connect = [&](int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra != rb) {
            parent[rb] = ra;
        }
    };

    int num_components = p - (k > 1);

    for (long long i = 1; i < p; ++i) {
        connect(static_cast<int>(i), static_cast<int>((i * k) % p));
    }

    unordered_map<int, int> component_map;
    for (int i = 1; i < p; ++i) {
        component_map[find(i)]++;
    }

    cout << mod_pow(p, static_cast<long long>(component_map.size())) << '\n';

    return 0;
}

