        base = multiply_modulo(base, base)
        exponent //= 2
    return result

baby_step_table = [-1] * 1000001

def giant_step_baby_step(base, modulus):
    global baby_step_table
    baby_step_table = [-1] * 1000001
    block_size = int(math.isqrt(modulus))
    current_value = 1
    base_inverse = exponentiate(base, modulus - 2)

    for step in range(block_size + 1):
        if baby_step_table[current_value] == -1:
            baby_step_table[current_value] = step
        current_value = multiply_modulo(current_value, base_inverse)
        if current_value == 1:
            return step + 1

    giant_step_value = exponentiate(base, block_size)
    current_value = giant_step_value
    for j in range(1, block_size + 1):
        if baby_step_table[current_value] != -1:
            return block_size * j + baby_step_table[current_value]
        current_value = multiply_modulo(current_value, giant_step_value)

    return -1

