#include <algorithm>
using namespace std;

int solve(const vector<int>& a, int T) {
    int best = 0;
    for (size_t i = 0; i < a.size(); ++i) {
        int rem = T;
        int cnt = 0;
        for (size_t j = i; j < a.size(); ++j) {
            if (j == i) {
                cnt = 1;
            } else {
                int gap = a[j] - a[j-1];
                if (gap > rem) break;
                rem -= gap;
                cnt++;
            }
        }
        if (cnt > best) best = cnt;
    }
    return best;
}

