import sys
from collections import deque

def edmonds_karp(n, source, sink, cap, flow):
    INF = 0x3f3f3f3f
    pre = [-1] * n
    d = [0] * n
    que = [0] * n

    total_flow = 0
    while True:
        pre = [-1] * n
        d[source] = INF
        p = q = 0
        que[q] = source
        q += 1

        while p < q and pre[sink] < 0:
            t = que[p]
            p += 1
            for i in range(n):
                if pre[i] < 0 and (j := cap[t][i] - flow[t][i]) > 0:
                    pre[que[q]] = t
                    d[i] = min(d[t], j)
                    q += 1

        if pre[sink] < 0:
            break

        flow_val = d[sink]
        i = sink
        while i != source:
            flow[pre[i]][i] += flow_val
            flow[i][pre[i]] -= flow_val
            i = pre[i]

        total_flow += flow_val

    return total_flow

def main():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    n, t = map(int, input_data[0].split())
    a = []
    b = []

    for i in range(1, n+1):
        a.append(input_data[i])

    for i in range(n+1, 2*n+1):
        b.append(input_data[i])

    INF = 0x3f3f3f3f
    mat = [[INF] * (n*n) for _ in range(n*n)]

    bi, bj = -1, -1
    for i in range(n):
        for j in range(n):
            if a[i][j] == 'Z':
                bi, bj = i, j

    dir_moves = [[0,1],[0,-1],[1,0],[-1,0]]

    def solve(A, B, vis, check):
        que = deque()
        vis[A*n+B] = 0
        que.append((A, B))

        while que:
            now = que.popleft()
            p = now[0]*n + now[1]
            dis = vis[p]

            if check and (mat[bi*n+bj][p] <= dis or t <= dis):
                if mat[bi*n+bj][p] < dis or t < dis:
                    vis[p] = INF + 1
                continue

            for d in range(4):
                i = dir_moves[d][0] + now[0]
                j = dir_moves[d][1] + now[1]
                if i < 0 or j < 0 or i == n or j == n:
                    continue
                if not ('0' <= b[i][j] <= '9'):
                    continue
                q = i*n + j
                if vis[q] != INF:
                    continue
                vis[q] = dis + 1
                que.append((i, j))

    solve(bi, bj, mat[bi*n+bj], False)

    for i in range(n):
        for j in range(n):
            if '1' <= a[i][j] <= '9':
                solve(i, j, mat[i*n+j], True)

    ca = []
    cb = []

    cap = [[0] * (2 + n*n + n*n) for _ in range(2 + n*n + n*n)]

    for i in range(n):
        for j in range(n):
            if b[i][j] <= '0' or b[i][j] > '9':
                continue
            ca.append(i)
            cb.append(j)
            p = i*n + j
            cap[p + 2 + n*n][1] = ord(b[i][j]) - ord('0')

    for i in range(n):
        for j in range(n):
            if a[i][j] <= '0' or a[i][j] > '9':
                continue
            p = i*n + j
            cap[0][p + 2] = ord(a[i][j]) - ord('0')
            for k in range(len(ca)):
                ii = ca[k]
                jj = cb[k]
                q = ii*n + jj
                if mat[p][q] < INF:
                    cap[p + 2][q + 2 + n*n] = INF

    flow = [[0] * (2 + n*n + n*n) for _ in range(2 + n*n + n*n)]

