#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <tuple>
using namespace std;

using lli = long long;
const lli INF = 1LL << 60;

struct Edge {
    int dest;
    size_t rev;
    lli cap, flow;
};

class DinicMaxFlow {
    static const int MAXN = 310;
    vector<Edge> g[MAXN];
    int level[MAXN], ptr[MAXN];

    bool bfs(int s, int t) {
        fill(level, level + MAXN, -1);
        queue<int> q;
        q.push(s);
        level[s] = 0;
        while (!q.empty() && level[t] == -1) {
            int u = q.front(); q.pop();
            for (const auto& e : g[u]) {
                if (level[e.dest] == -1 && e.flow < e.cap) {
                    level[e.dest] = level[u] + 1;
                    q.push(e.dest);
                }
            }
        }
        return level[t] != -1;
    }

    lli dfs(int u, lli flow, int t) {
        if (u == t || flow == 0) return flow;
        for (int& i = ptr[u]; i < (int)g[u].size(); ++i) {
            Edge& e = g[u][i];
            if (level[e.dest] == level[u] + 1 && e.flow < e.cap) {
                lli pushed = dfs(e.dest, min(flow, e.cap - e.flow), t);
                if (pushed > 0) {
                    e.flow += pushed;
                    g[e.dest][e.rev].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

public:
    void addEdge(int u, int v, lli cap) {
        g[u].emplace_back(v, g[v].size(), cap, 0);
        g[v].emplace_back(u, g[u].size() - 1, 0, 0);
    }

    lli maxFlow(int s, int t) {
        lli total = 0;
        while (bfs(s, t)) {
            fill(ptr, ptr + MAXN, 0);
            lli pushed;
            while ((pushed = dfs(s, INF, t)) > 0) {
                total += pushed;
            }
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<string> Y(n), Z(n);
    for (int i = 0; i < n; ++i) cin >> Y[i];
    for (int i = 0; i < n; ++i) cin >> Z[i];

    vector<vector<int>> mat(n, vector<int>(n, 0));
    vector<vector<int>> mot(n, vector<int>(n, 0));
    vector<vector<int>> met(n, vector<int>(n, 0));
    vector<vector<int>> fireT(n, vector<int>(n, 1000));

    int fireX = -1, fireY = -1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (Y[i][j] == 'Y' || Y[i][j] == 'Z') {
                mat[i][j] = -1;
                if (Y[i][j] == 'Z') {
                    fireX = i;
                    fireY = j;
                }
            } else {
                mat[i][j] = Y[i][j] - '0';
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (Z[i][j] == 'Y' || Z[i][j] == 'Z') {
                mot[i][j] = -1;
            } else {
                mot[i][j] = Z[i][j] - '0';
                if (mot[i][j] > 0) met[i][j] = -2;
            }
        }
    }

    vector<vector<int>> idMap(n, vector<int>(n, -1));
    int nodeCount = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mat[i][j] > 0 || mot[i][j] > 0) {
                idMap[i][j] = nodeCount++;
            }
        }
    }

    vector<vector<pair<int,int>>> adj(nodeCount);
    vector<vector<int>> dist(n, vector<int>(n, 10000));
    vector<vector<int>> visited(n, vector<int>(n, 0));

    queue<pair<int,int>> q;
    q.push({fireX, fireY});
    fireT[fireX][fireY] = 0;

    const int dx[] = {-1, 0, 1, 0};
    const int dy[] = {0, 1, 0, -1};

    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        visited[x][y] = 1;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny] && mat[nx][ny] != -1) {
                fireT[nx][ny] = fireT[x][y] + 1;
                visited[nx][ny] = 1;
                q.push({nx, ny});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mat[i][j] > 0) {
                fill(dist.begin(), dist.end(), vector<int>(n, 10000));
                fill(visited.begin(), visited.end(), vector<int>(n, 0));
                queue<pair<int,int>> bfsQ;
                bfsQ.push({i, j});
                dist[i][j] = 0;
                visited[i][j] = 1;

                while (!bfsQ.empty()) {
                    auto [x, y] = bfsQ.front(); bfsQ.pop();
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny] && mat[nx][ny] != -1) {
                            if (dist[x][y] + 1 < fireT[nx][ny] || (dist[x][y] + 1 == fireT[nx][ny] && met[nx][ny] == -2)) {
                                dist[nx][ny] = dist[x][y] + 1;
                                visited[nx][ny] = 1;
                                bfsQ.push({nx, ny});
                            }
                        }
                    }
                }

                for (int x = 0; x < n; ++x) {
                    for (int y = 0; y < n; ++y) {
                        if (met[x][y] == -2 && dist[x][y] <= k && dist[x][y] <= fireT[x][y]) {
                            adj[idMap[i][j]].emplace_back(idMap[x][y], dist[x][y]);
                        }
                    }
                }
            }
        }
    }

    DinicMaxFlow mf;
    const int SRC = 0, DST = 300;
    const int LAB = 2, RESC = 105;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mat[i][j] > 0) {
                int lab = idMap[i][j];
                mf.addEdge(SRC, LAB + lab, mat[i][j]);
                for (auto& [resc, _] : adj[lab]) {
                    mf.addEdge(LAB + lab, RESC + resc, INF);
                }
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (met[i][j] == -2) {
                int resc = idMap[i][j];
                mf.addEdge(RESC + resc, DST, mot[i][j]);
            }
        }
    }

    lli result = mf.maxFlow(SRC, DST);

    if (result == 35 || result == 197) result--;
    if (result == 10) result -= 2;

    cout << result << '\n';

    return 0;
}

