import sys
from collections import deque

def main():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    n, t = map(int, input_data[0].split())
    grid_index = 1

    # Read first grid
    source_grid = []
    for i in range(n):
        source_grid.append(input_data[grid_index])
        grid_index += 1

    # Read second grid
    sink_grid = []
    for i in range(n):
        sink_grid.append(input_data[grid_index])
        grid_index += 1

    # Initialize arrays
    plant = [[[0 for _ in range(61)] for _ in range(n)] for _ in range(n)]
    source_cap = [[0 for _ in range(n)] for _ in range(n)]
    sink_cap = [[0 for _ in range(n)] for _ in range(n)]
    source_num = [[-1 for _ in range(n)] for _ in range(n)]
    sink_num = [[-1 for _ in range(n)] for _ in range(n)]

    # Process source grid
    for i in range(n):
        for j in range(n):
            ch = source_grid[i][j]
            if ch == 'Y' or ch == 'Z':
                plant[i][j][0] = ord(ch) - ord('X')
                source_cap[i][j] = 0
            else:
                plant[i][j][0] = 0
                source_cap[i][j] = int(ch)

    # Process sink grid
    for i in range(n):
        for j in range(n):
            ch = sink_grid[i][j]
            if ch == 'Y' or ch == 'Z':
                plant[i][j][0] = ord(ch) - ord('X')
                sink_cap[i][j] = 0
            else:
                plant[i][j][0] = 0
                sink_cap[i][j] = int(ch)

    # Simulate plant spread over time
    dr = [0, 0, -1, 1]
    dc = [-1, 1, 0, 0]

    for curr_time in range(1, t + 1):
        for i in range(n):
            for j in range(n):
                plant[i][j][curr_time] = plant[i][j][curr_time - 1]

        for i in range(n):
            for j in range(n):
                if plant[i][j][curr_time - 1] == 2:
                    for k in range(4):
                        ni, nj = i + dr[k], j + dc[k]
                        if 0 <= ni < n and 0 <= nj < n:
                            if plant[ni][nj][curr_time - 1] == 0:
                                plant[ni][nj][curr_time] = 2

    # Assign node numbers
    counter = 1
    for i in range(n):
        for j in range(n):
            if source_cap[i][j] != 0:
                source_num[i][j] = counter
                counter += 1
            else:
                source_num[i][j] = -1

    for i in range(n):
        for j in range(n):
            if sink_cap[i][j] != 0:
                sink_num[i][j] = counter
                counter += 1
            else:
                sink_num[i][j] = -1

    # Initialize flow matrix
    flo = [[0 for _ in range(counter + 1)] for _ in range(counter + 1)]

    # BFS for each source
    for i in range(n):
        for j in range(n):
            if source_cap[i][j] == 0:
                continue
            bfs = deque()
            bfs.append((0, i, j))
            source = source_num[i][j]
            vis = [[False for _ in range(n)] for _ in range(n)]
            vis[i][j] = True

            while bfs:
                curr_time, r, c = bfs.popleft()

                if sink_cap[r][c] != 0:
                    flo[source][sink_num[r][c]] = 10000

                if curr_time == t:
                    continue

                if plant[r][c][curr_time] != 0:
                    continue

                for k in range(4):
                    ni, nj = r + dr[k], c + dc[k]
                    if 0 <= ni < n and 0 <= nj < n:
                        if plant[ni][nj][curr_time] == 0 and not vis[ni][nj]:
                            bfs.append((curr_time + 1, ni, nj))
                            vis[ni][nj] = True

    # Set up source and sink connections
    for i in range(n):
        for j in range(n):
            if source_cap[i][j] != 0:
                flo[0][source_num[i][j]] = source_cap[i][j]
            if sink_cap[i][j] != 0:
                flo[sink_num[i][j]][counter] = sink_cap[i][j]

    # Ford-Fulkerson algorithm
    def get_path():
        parent = [-1] * (counter + 1)
        parent[0] = 0
        stack = [0]

        while stack:
            top = stack.pop()
            if top == counter:
                break
            for i in range(counter + 1):
                if flo[top][i] > 0 and parent[i] == -1:
                    parent[i] = top
                    stack.append(i)

        if parent[counter] == -1:
            return 0

        ans = 10000
        pos = counter
        while pos != 0:
            ans = min(ans, flo[parent[pos]][pos])
            pos = parent[pos]

        pos = counter
        while pos != 0:
            flo[parent[pos]][pos] -= ans
            flo[pos][parent[pos]] += ans
            pos = parent[pos]

        return ans

    ans = 0
    while True:
        temp = get_path()
        if temp == 0:
            break
        ans += temp

    print(ans)

if __name__ == "__main__":
    main()

