            ll tr = dfs(u, min(pushed, edges[viz].cap - edges[viz].flow));
            if(tr == 0) continue; 

            edges[viz].flow += tr;
            edges[viz ^ 1].flow -= tr; 
            return tr;
        }
        return 0;
    }

    ll flow() {
        ll f = 0;
        while(true) {
            fill(all(level), -1);
            level[s] = 0;
            q.push(s);
            if(!bfs()) break; 
            fill(all(ptr), 0);
            while(ll pushed = dfs(s, flow_inf))
