            int v = q.front(); q.pop();
            for (int id : adj[v]) {
                auto& e = edges[id];
                if (e.cap - e.flow <= 0 || level[e.u] != -1) continue;
                level[e.u] = level[v] + 1;
                q.push(e.u);
            }
        }
        return level[t] != -1;
    }

    ll dfs(int v, ll pushed) {
        if (pushed == 0) return 0;
