using namespace std;

using i64 = long long;
using pii = pair<int, int>;

constexpr int DX[] = {0, 0, -1, 1};
constexpr int DY[] = {-1, 1, 0, 0};

struct edge {
    int from;
    int to;
    i64 cap;
    i64 flow;
    edge(int f, int t, i64 c) : from(f), to(t), cap(c), flow(0) {}
};

struct dinic {
    const i64 INF = 1e18;
    int n;
    int src;
    int dst;
    vector<edge> e;
    vector<vector<int>> g;
    vector<int> lvl;
    vector<int> ptr;
    queue<int> q;

    dinic(int nodes, int s, int t)
        : n(nodes), src(s), dst(t) {
        g.resize(n);
        lvl.resize(n);
        ptr.resize(n);
    }

    void link(int u, int v, i64 c) {
        e.emplace_back(u, v, c);
        e.emplace_back(v, u, 0);
        g[u].push_back((int)e.size() - 2);
        g[v].push_back((int)e.size() - 1);
    }

    bool bfs_layer() {
        fill(lvl.begin(), lvl.end(), -1);
        lvl[src] = 0;
        q.push(src);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int id : g[u]) {
                auto& ed = e[id];
                if (ed.cap - ed.flow > 0 && lvl[ed.to] == -1) {
                    lvl[ed.to] = lvl[u] + 1;
                    q.push(ed.to);
                }
            }
        }
        return lvl[dst] != -1;
    }

    i64 dfs_push(int u, i64 flow) {
        if (u == dst) return flow;
        for (int& i = ptr[u]; i < (int)g[u].size(); ++i) {
            int id = g[u][i];
            auto& ed = e[id];
            if (lvl[ed.to] == lvl[u] + 1 && ed.cap - ed.flow > 0) {
                i64 pushed = dfs_push(ed.to, min(flow, ed.cap - ed.flow));
                if (pushed > 0) {
                    ed.flow += pushed;
                    e[id ^ 1].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    i64 ford_fulkerson() {
        i64 total = 0;
        while (bfs_layer()) {
            fill(ptr.begin(), ptr.end(), 0);
            i64 pushed;
            while ((pushed = dfs_push(src, INF)) > 0)
                total += pushed;
        }
        return total;
    }
};

int n, T;
