    gridA = []
    gridB = []
    for i in range(1, N + 1):
        gridA.append(data[i])
    for i in range(N + 1, 2 * N + 1):
        gridB.append(data[i])

    def in_bounds(x, y):
        return 0 <= x < N and 0 <= y < N and gridA[x][y] != 'Y' and gridA[x][y] != 'Z'

    def multi_source_bfs(sx, sy):
        dist = [[-1] * N for _ in range(N)]
        qu = deque()
        qu.append((sx, sy))
        dist[sx][sy] = 0
        while qu:
            x, y = qu.popleft()
            for k in range(4):
                nx, ny = x + DX[k], y + DY[k]
                if in_bounds(nx, ny) and dist[nx][ny] == -1:
                    dist[nx][ny] = dist[x][y] + 1
                    qu.append((nx, ny))
        for i in range(N):
            for j in range(N):
                if dist[i][j] == -1:
                    dist[i][j] = 1000000000
        return dist

    # Find 'Z' position
    found_z = False
    z_x, z_y = -1, -1
    for i in range(N):
        for j in range(N):
            if gridA[i][j] == 'Z':
                z_x, z_y = i, j
                found_z = True
                break
        if found_z:
            break

    dist = multi_source_bfs(z_x, z_y)

    # Memoization for can_reach
    memo_dp = {}
    memo_set = set()

    def can_reach(t, x0, y0, x1, y1):
        if dist[x0][y0] < t:
            return False
        if x0 == x1 and y0 == y1:
            return True
        if t >= T:
            return False
        if dist[x0][y0] <= t:
            return False

        key = (t, x0, y0, x1, y1)
        if key in memo_set:
            return memo_dp[key]

        memo_set.add(key)
        for d in range(4):
            nx, ny = x0 + DX[d], y0 + DY[d]
            if 0 <= nx < N and 0 <= ny < N:
                if gridA[nx][ny] == 'Y' or gridA[nx][ny] == 'Z':
                    continue
                if can_reach(t + 1, nx, ny, x1, y1):
                    memo_dp[key] = 1
                    memo_set.add(key)
                    return True

        memo_dp[key] = 0
        return False

    # Collect sources and destinations
    src = []
    dst = []
    for i in range(N):
        for j in range(N):
            if gridA[i][j] != 'Z' and gridA[i][j] != 'Y' and gridA[i][j] != '0':
                src.append((i, j))
    for i in range(N):
        for j in range(N):
            if gridB[i][j] != 'Z' and gridB[i][j] != 'Y' and gridB[i][j] != '0':
                dst.append((i, j))

    V = len(src) + len(dst) + 2
    mf = MaxFlow(V, 0, V - 1)

    # Add edges from source
    for i in range(len(src)):
        c = int(gridA[src[i][0]][src[i][1]])
        mf.add_edge(0, i + 1, c)

    # Add edges to sink
    for i in range(len(dst)):
        c = int(gridB[dst[i][0]][dst[i][1]])
        mf.add_edge(len(src) + 1 + i, V - 1, c)

    # Add edges between sources and destinations
    for i in range(len(src)):
        for j in range(len(dst)):
            if can_reach(0, src[i][0], src[i][1], dst[j][0], dst[j][1]):
