        self.n = n
        for i in range(MAXN):
            for j in range(MAXN):
                self.cap[i][j] = 0
                self.g[i][j] = 0
        for i in range(MAXN):
            self.mk[i] = 0

    def addCap(self, i, j, val):
        self.cap[i][j] += val
        self.g[i][j] = 1

    def sap(self, idx, maxCap):
        if idx == self.sink:
            return maxCap
        l = maxCap
        d = 0
        minH = self.n
        for i in range(self.n):
            if self.cap[idx][i] - self.flow[idx][i] > 0:
                if self.h[idx] == self.h[i] + 1:
                    d = self.sap(i, min(l, self.cap[idx][i] - self.flow[idx][i]))
                    self.flow[idx][i] += d
                    self.flow[i][idx] -= d
