    def __init__(self):
        self.cnt = 0
        self.pos = [-1] * self.SIZE
        self.rev = [-1] * self.SIZE
        self.v = [0] * self.SIZE

    def match(self, x, e):
        for y in e[x]:
            if not self.v[y]:
                self.v[y] = 1
            else:
                continue
            if self.rev[y] < 0 or self.match(self.rev[y], e):
                self.pos[x] = y
                self.rev[y] = x
                return True
        return False

    def gao(self, n, e):
        self.cnt = 0
        self.pos = [-1] * self.SIZE
        self.rev = [-1] * self.SIZE
        for i in range(n):
            self.v = [0] * self.SIZE
            if self.match(i, e):
                self.cnt += 1
        return self.cnt

