                pushed = dfs(v, min(flow, cap))
                if pushed > 0:
                    graph[i][1] -= pushed
                    graph[i^1][1] += pushed
                    return pushed
            i = graph[i][2]
        return 0

    max_flow = 0
    while bfs():
        while True:
            pushed = dfs(source_node, INF)
            if pushed == 0:
                break
            max_flow += pushed

    print(max_flow)

