struct Pos {
   int row, col;
   Pos(int _row=0, int _col=0) : row(_row), col(_col) {}
};

int dr[] = {-1, 0, 0, 1};
int dc[] = {0, -1, 1, 0};

int N, T;
char B[12][12];
char B1[12][12];
char B2[12][12];

int D1[12][12];
void bfs1(const Pos& src) {
   memset(D1, -1, sizeof(D1));
   D1[src.row][src.col] = 0;
   queue<Pos> q;
   q.push(src);
   while (!q.empty()) {
      Pos cur = q.front();
      q.pop();
      for (int k = 0; k < 4; ++k) {
         Pos nxt(cur.row + dr[k], cur.col + dc[k]);
         if (B[nxt.row][nxt.col] != '.') continue;
         if (D1[nxt.row][nxt.col] < 0) {
            D1[nxt.row][nxt.col] = D1[cur.row][cur.col] + 1;
            q.push(nxt);
         }
      }
   }
}

int D2[12][12];
void bfs2(const Pos& src) {
   memset(D2, -1, sizeof(D2));
   D2[src.row][src.col] = 0;
   queue<Pos> q;
   q.push(src);
   while (!q.empty()) {
      Pos cur = q.front();
      q.pop();
      if (D1[cur.row][cur.col] >= 0 && D2[cur.row][cur.col] >= D1[cur.row][cur.col])
         continue;
      for (int k = 0; k < 4; ++k) {
         Pos nxt(cur.row + dr[k], cur.col + dc[k]);
         if (B[nxt.row][nxt.col] != '.') continue;
         if (D2[nxt.row][nxt.col] < 0) {
            if (D1[nxt.row][nxt.col] >= 0 && D1[nxt.row][nxt.col] < D2[cur.row][cur.col] + 1)
               continue;
            D2[nxt.row][nxt.col] = D2[cur.row][cur.col] + 1;
