        for c in range(1, N+1):
            B1[r][c] = line[c-1]
        B1[r][N+1] = '#'

    for r in range(1, N+1):
        line = data[N + r]
        for c in range(1, N+1):
            B2[r][c] = line[c-1]
        B2[r][N+1] = '#'

    scientists = []
    capsules = []
    z = None

    for r in range(1, N+1):
        for c in range(1, N+1):
            if B1[r][c].isdigit():
                if B1[r][c] > '0':
                    scientists.append((r, c))
                B[r][c] = '.'
            elif B1[r][c] == 'Z':
                z = (r, c)
                B[r][c] = '.'
            if B2[r][c].isdigit() and B2[r][c] > '0':
                capsules.append((r, c))

