            self.cap = [[0] * n for _ in range(n)]
            self.flow = [[0] * n for _ in range(n)]

        def add_edge(self, u, v, _cap):
            self.cap[u][v] += _cap

        def dinic(self, s, t):
            # BFS for level graph
            def bfs():
                level = [-1] * self.N
                q = deque()
                q.append(s)
                level[s] = 0
                while q:
                    cur = q.popleft()
                    for v in range(self.N):
                        if level[v] < 0 and self.cap[cur][v] - self.flow[cur][v] > 0:
                            level[v] = level[cur] + 1
                            q.append(v)
                return level

            # DFS to find blocking flow
