                        pushed = dfs(v, t, min(flow_val, self.cap[u][v] - self.flow[u][v]), level, ptr)
                        if pushed > 0:
                            self.flow[u][v] += pushed
                            self.flow[v][u] -= pushed
                            return pushed
                    ptr[u] += 1
                return 0

            max_flow = 0
            while True:
                level = bfs()
                if level[t] < 0:
                    break
                ptr = [0] * self.N
                while True:
                    pushed = dfs(s, t, float('inf'), level, ptr)
                    if pushed == 0:
                        break
                    max_flow += pushed
            return max_flow

