import sys
from collections import deque

class FlowNetwork:
    class Edge:
        __slots__ = ('to', 'rev', 'cap')

        def __init__(self, to, rev, cap):
            self.to = to
            self.rev = rev
            self.cap = cap

    def __init__(self, nodes, s, t):
        self.V = nodes
        self.adj = [[] for _ in range(nodes)]
        self.level = [-1] * nodes
        self.ptr = [0] * nodes
        self.source = s
        self.sink = t

    def addEdge(self, u, v, c):
        self.adj[u].append(self.Edge(v, len(self.adj[v]), c))
        self.adj[v].append(self.Edge(u, len(self.adj[u]) - 1, 0))

    def bfs(self):
        self.level = [-1] * self.V
        q = deque()
        q.append(self.source)
        self.level[self.source] = 0
        while q:
            u = q.popleft()
            for e in self.adj[u]:
                if e.cap > 0 and self.level[e.to] == -1:
                    self.level[e.to] = self.level[u] + 1
                    q.append(e.to)
        return self.level[self.sink] != -1

    def dfs(self, u, f):
        if u == self.sink:
            return f
        while self.ptr[u] < len(self.adj[u]):
            e = self.adj[u][self.ptr[u]]
            if e.cap > 0 and self.level[e.to] == self.level[u] + 1:
                pushed = self.dfs(e.to, min(f, e.cap))
                if pushed > 0:
                    e.cap -= pushed
                    self.adj[e.to][e.rev].cap += pushed
                    return pushed
            self.ptr[u] += 1
        return 0

