    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (!safe(i, j, A)) continue;
            auto dist_src = distance_field(i, j, A);

            for (int x = 0; x < N; ++x) {
                for (int y = 0; y < N; ++y) {
                    if (!safe(x, y, A)) continue;
                    if (dist_src[x][y] > T) continue;
                    if (dist_src[x][y] > dist_react[x][y]) continue;

                    bool critical = (dist_src[x][y] == dist_react[x][y]);
