    def bfs2(sx, sy):
        for i in range(30):
            for j in range(30):
                D2[i][j] = float('inf')
        q = deque()
        q.append((sx, sy))
        D2[sx][sy] = 0
        dx = [0, 0, -1, 1]
        dy = [1, -1, 0, 0]
        while q:
            x, y = q.popleft()
            if D2[x][y] >= D1[x][y]:
                continue
            for k in range(4):
                nx, ny = x + dx[k], y + dy[k]
                if 0 <= nx < N and 0 <= ny < N and D2[nx][ny] == float('inf') and G1[nx][ny] != 'Y' and D2[x][y] + 1 <= D1[nx][ny]:
                    D2[nx][ny] = D2[x][y] + 1
                    q.append((nx, ny))

    bfs1(zx, zy)

    # Build graph for max flow
    V = 2 * N * N + 2
    adj = [[] for _ in range(V)]
    E = []

    def add_edge(src, dst, cap):
        E.append({'src': src, 'dst': dst, 'cap': cap, 'flow': 0})
        adj[src].append(len(E) - 1)
        E.append({'src': dst, 'dst': src, 'cap': 0, 'flow': 0})
        adj[dst].append(len(E) - 1)

    for i in range(N):
        for j in range(N):
            if G1[i][j] == 'Y':
                continue
            u = i * N + j + 1
            v = N * N + u
            c1 = int(G1[i][j])
            c2 = int(G2[i][j])

            add_edge(0, u, c1)
            add_edge(v, V-1, c2)

            bfs2(i, j)
            for x in range(N):
                for y in range(N):
                    if G2[x][y] == 'Y' or D2[x][y] > LIMIT:
                        continue
                    w = N * N + x * N + y + 1
                    add_edge(u, w, c1)

    # Dinic's algorithm
    def bfs_level():
        lvl = [-1] * V
        q = deque()
        q.append(0)
        lvl[0] = 0
        while q and lvl[V-1] == -1:
            u = q.popleft()
            for id in adj[u]:
                e = E[id]
                if lvl[e['dst']] == -1 and e['flow'] < e['cap']:
                    lvl[e['dst']] = lvl[u] + 1
                    q.append(e['dst'])
        return lvl[V-1] != -1

    def dfs(u, f, lvl, ptr):
        if not f or u == V-1:
            return f
        while ptr[u] < len(adj[u]):
            id = adj[u][ptr[u]]
            e = E[id]
            if lvl[e['dst']] == lvl[u] + 1 and e['flow'] < e['cap']:
                sent = dfs(e['dst'], min(f, e['cap'] - e['flow']), lvl, ptr)
                if sent:
                    E[id]['flow'] += sent
                    E[id ^ 1]['flow'] -= sent
                    return sent
            ptr[u] += 1
        return 0

    result = 0
    while bfs_level():
        ptr = [0] * V
        while True:
            sent = dfs(0, float('inf'), lvl, ptr)
            if not sent:
                break
            result += sent

    print(result)

