INF = 1000000000

class FlowGraph:
    def __init__(self, size):
        self.n = size
        self.cap = [[0] * size for _ in range(size)]
        self.adj = [[] for _ in range(size)]
        self.level = [0] * size
        self.iter = [0] * size

    def connect(self, u, v, c):
        self.cap[u][v] = c
        self.adj[u].append(v)
        self.adj[v].append(u)

    def levelize(self, s, t):
        self.level = [-1] * self.n
        q = deque()
        q.append(s)
        self.level[s] = 0
        while q:
            u = q.popleft()
            for v in self.adj[u]:
                if self.level[v] == -1 and self.cap[u][v] > 0:
                    self.level[v] = self.level[u] + 1
                    q.append(v)
        return self.level[t] != -1

    def augment(self, u, t, flow):
        if u == t:
            return flow
        for i in range(self.iter[u], len(self.adj[u])):
            self.iter[u] = i
            v = self.adj[u][i]
            if self.level[v] == self.level[u] + 1 and self.cap[u][v] > 0:
