        q1r, q1c = deque(), deque()
        q2r, q2c = deque(), deque()
        q1r.append(r); q1c.append(c)
        q2r.append(zero_r); q2c.append(zero_c)

        d1 = [[-1] * n for _ in range(n)]
        d2 = [[-1] * n for _ in range(n)]
        d1[r][c] = 0
        d2[zero_r][zero_c] = 0

        while q1r:
            sz = len(q1r)
            for _ in range(sz):
                ur, uc = q1r.popleft(), q1c.popleft()
                if d2[ur][uc] >= 0:
                    continue
                for k in range(4):
                    nr, nc = ur + dr[k], uc + dc[k]
                    if valid(nr, nc) and d1[nr][nc] == -1:
                        d1[nr][nc] = d1[ur][uc] + 1
                        if d1[nr][nc] > T:
                            break
                        if d2[nr][nc] >= 0:
                            continue
                        q1r.append(nr)
                        q1c.append(nc)
                        if board2[nr][nc] != '0':
                            connect(node_id[sr][sc], node_id[nr][nc] + node_cnt, 10)

            sz = len(q2r)
            for _ in range(sz):
                ur, uc = q2r.popleft(), q2c.popleft()
                for k in range(4):
                    nr, nc = ur + dr[k], uc + dc[k]
                    if valid(nr, nc) and d2[nr][nc] == -1:
                        d2[nr][nc] = d2[ur][uc] + 1
                        q2r.append(nr)
                        q2c.append(nc)

    def bfs_level():
        lvl = [-1] * (2 * node_cnt + 2)
        q = deque()
        q.append(0)
        lvl[0] = 0
        while q:
            u = q.popleft()
            for e in adj[u]:
                if e[1] > 0 and lvl[e[0]] == -1:
                    lvl[e[0]] = lvl[u] + 1
                    q.append(e[0])
        return lvl[2 * node_cnt + 1] != -1

    def dfs_flow(u, flow, ptr):
        if u == 2 * node_cnt + 1:
            return flow
        for i in range(ptr[u], len(adj[u])):
            ptr[u] = i
            e = adj[u][i]
            if e[1] > 0 and lvl[e[0]] == lvl[u] + 1:
                pushed = dfs_flow(e[0], min(flow, e[1]), ptr)
                if pushed > 0:
                    e[1] -= pushed
                    adj[e[0]][e[2]][1] += pushed
                    return pushed
        return 0

    def dinic_max_flow():
        total = 0
        while bfs_level():
            ptr = [0] * (2 * node_cnt + 2)
            pushed = dfs_flow(0, float('inf'), ptr)
            while pushed > 0:
                total += pushed
                pushed = dfs_flow(0, float('inf'), ptr)
        return total

    # Initialize node_id and node_cnt
    for i in range(n):
        for j in range(n):
            if board1[i][j] == 'Z':
                zero_r, zero_c = i, j
            elif valid(i, j):
                node_id[i][j] = node_cnt + 1
                node_cnt += 1

    # Expand connections
    for i in range(n):
        for j in range(n):
            if valid(i, j):
                expand(i, j)

    print(dinic_max_flow())

if __name__ == "__main__":
    main()

