using namespace std;

int compute_gcd(int a, int b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int main() {
    int x, y, limit;
    scanf("%d%d%d", &x, &y, &limit);

    double target = (double)x / y;
    int best_num = 0, best_den = 1;
    double min_diff = 1e10;

    for (int denom = 1; denom <= limit; ++denom) {
        int approx = (int)(((long long)x * denom) / y);

        for (int offset = -1; offset <= 1; ++offset) {
            int num = approx + offset;
            if (num < 0) continue;

            double value = (double)num / denom;
            double diff = fabs(target - value);

            if (diff < min_diff || (diff == min_diff && num * best_den < best_num * denom)) {
                min_diff = diff;
                best_num = num;
                best_den = denom;
            }
        }
    }

    if (fabs(1.0 - target) <= min_diff + 1e-9) {
        best_num = 1;
        best_den = 1;
    }

    int g = compute_gcd(best_num, best_den);
    printf("%d/%d\n", best_num / g, best_den / g);

    return 0;
}

