import math
from fractions import Fraction as PyFraction

def geta(x, y, b):
    lower = (b * x) // y
    upper = ((b * x) + (y - 1)) // y
    return (lower, upper)

def solve(x, y, n):
    cands = []
    for b in range(1, n + 1):
        ap = geta(x, y, b)
        cands.append((ap[0], b))
        cands.append((ap[1], b))

    def comp(fa):
        a1, b1 = fa
        # Create a key for sorting
        # We want to sort by:
        # 1. Absolute difference |x/b - a/b| = |x*b - a*y| / (b*y)
        # Since denominator is positive, we can compare numerators: |x*b - a*y|
        # But the original code uses |x*b1*b2 - a1*b2*y| vs |x*b1*b2 - a2*b1*y|
        # This is equivalent to comparing |x/b - a1/y| vs |x/b - a2/y| scaled by b1*b2*y
        # For sorting, we can use the absolute difference |x*b - a*y| as primary key
        # Then b as secondary, then a as tertiary
        diff = abs(x * b1 - a1 * y)
        return (diff, b1, a1)

    # Sort using the comparison logic from the original code
    # The original comp function compares two fractions fa and fb
    # We'll use a custom comparator
    def compare(fa, fb):
        a1, b1 = fa
        a2, b2 = fb

        # Calculate the absolute differences scaled by b1*b2
        left = abs(x * b1 * b2 - a1 * b2 * y)
        right = abs(x * b1 * b2 - a2 * b1 * y)

        if left < right:
            return -1
        elif left > right:
            return 1
        else:
            if b1 < b2:
                return -1
            elif b1 > b2:
                return 1
            else:
                if a1 < a2:
                    return -1
                elif a1 > a2:
                    return 1
                else:
                    return 0

    from functools import cmp_to_key
    cands.sort(key=cmp_to_key(compare))

    result = cands[0]
    print(f"{result[0]}/{result[1]}")

if __name__ == "__main__":
    x, y, n = map(int, input().split())
    solve(x, y, n)

