    #ifndef ONLINE_JUDGE
        freopen("a.in", "r", stdin);
    #endif

    cin >> a >> b >> n;

    for (long long y = 1; y <= n; ++y) {
        long long x = (a * y) / b;

        if (bestNum == -1) {
            bestNum = x;
            bestDen = y;
        }

        // Compare |a*y - b*x| / y with |a*bestDen - b*bestNum| / bestDen
        long long diff1 = abs(a * y - b * x);
        long long diff2 = abs(a * bestDen - b * bestNum);

        if (diff1 * bestDen < diff2 * y) {
            bestNum = x;
            bestDen = y;
        }

        x++;
        diff1 = abs(a * y - b * x);
        if (diff1 * bestDen < diff2 * y) {
            bestNum = x;
            bestDen = y;
        }
    }

    cout << bestNum << "/" << bestDen << endl;
    return 0;
}

