        if (numerator == 0 && denominator == 0) {
            if (err1 * y <= err2 * y) {
                numerator = x1;
                denominator = y;
            } else {
                numerator = x2;
                denominator = y;
            }
        } else {
            long long curr_err1 = err1 * denominator;
            long long curr_err2 = err2 * denominator;
            long long best_err = abs_val(A * denominator - B * numerator) * y;

            if (curr_err1 < best_err) {
                numerator = x1;
                denominator = y;
            } else if (curr_err2 < best_err) {
                numerator = x2;
                denominator = y;
            }
        }
    }

    cout << numerator << "/" << denominator << endl;
    return 0;
}

