#include <iostream>
#include <algorithm>
#include <vector>
#include <string>
using namespace std;

long long int fn = 100000, fd = 1;
long long int ra, rb;

long long int gcd(long long int a, long long int b) {
    while (b != 0) {
        long long int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

void function(long long int x, long long int y, long long int b, long long int a) {
    if (a < 0) {
        return;
    }
    long long int g = gcd(a, b);
    a /= g;
    b /= g;

    long long int numerator = llabs(b * x - a * y);
    long long int denominator = b * y;
    g = gcd(numerator, denominator);
    numerator /= g;
    denominator /= g;

    if (numerator * fd < fn * denominator) {
        fn = numerator;
        fd = denominator;
        ra = a;
        rb = b;
    } else if (numerator * fd == fn * denominator) {
        if (b < rb) {
            ra = a;
            rb = b;
        } else if (b == rb && a < ra) {
            ra = a;
            rb = b;
        }
    }
}

int main() {
    long long int x, y, n;
    cin >> x >> y >> n;

    for (long long int i = 1; i <= n; i++) {
        function(x, y, i, (i * x) / y);
        function(x, y, i, (i * x) / y + 1);
        function(x, y, i, (i * x) / y - 1);
    }

    cout << ra << "/" << rb << endl;
    return 0;
}

