using namespace std;

struct Fraction {
    long long num, den;
};

Fraction best = {100000, 1};
Fraction result = {0, 0};

long long gcd(long long a, long long b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

void update(long long x, long long y, long long b, long long a) {
    if (a < 0) return;

    long long g = gcd(a, b);
    a /= g;
    b /= g;

    long long num = llabs(b * x - a * y);
    long long den = b * y;
    g = gcd(num, den);
    num /= g;
    den /= g;

    if (num * best.den < best.num * den) {
        best = {num, den};
        result = {a, b};
    } else if (num * best.den == best.num * den) {
        if (b < result.den || (b == result.den && a < result.num)) {
            result = {a, b};
        }
    }
}

int main() {
    long long x, y, n;
    cin >> x >> y >> n;

    for (long long i = 1; i <= n; ++i) {
        update(x, y, i, (i * x) / y);
        update(x, y, i, (i * x) / y + 1);
        update(x, y, i, (i * x) / y - 1);
    }

    cout << result.num << "/" << result.den << endl;
    return 0;
}

