        for (lli num = base - 1; num <= base + 1; ++num) {
            if (num < 0) continue;
            long double error = fabsl((long double)num / d - (long double)a / b);
            if (error < smallest_error) {
                smallest_error = error;
                best_num = num;
                best_den = d;
            }
        }
    }

