using namespace std;

using i64 = long long;

#define len(c) static_cast<int>((c).size())

i64 compute_gcd(i64 u, i64 v) {
    while (v != 0) {
        u %= v;
        swap(u, v);
    }
    return u;
}

int main() {
    i64 numerator, denominator, limit;
    cin >> numerator >> denominator >> limit;

    i64 best_num = 0, best_den = 1;
    double min_diff = 1e18;

    for (i64 d = 1; d <= limit; ++d) {
        i64 num1 = 0;
        i64 lo = 0, hi = 100000;
        while (lo <= hi) {
            i64 mid = (lo + hi) / 2;
            if (mid * denominator <= numerator * d) {
                num1 = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        i64 num2 = 0;
        lo = 0, hi = 100000;
        while (lo <= hi) {
            i64 mid = (lo + hi) / 2;
            if (mid * denominator < numerator * d) {
                lo = mid + 1;
            } else {
                num2 = mid;
                hi = mid - 1;
            }
        }

        double diff1 = fabs(static_cast<double>(num1) / d - static_cast<double>(numerator) / denominator);
        double diff2 = fabs(static_cast<double>(num2) / d - static_cast<double>(numerator) / denominator);

        i64 candidate_num = num1;
        i64 candidate_den = d;
        double current_diff = diff1;

        if (diff2 + 1e-9 < current_diff) {
            candidate_num = num2;
            candidate_den = d;
            current_diff = diff2;
        }

        i64 g = compute_gcd(candidate_num, candidate_den);
        candidate_num /= g;
        candidate_den /= g;

        if (current_diff < min_diff) {
            best_num = candidate_num;
            best_den = candidate_den;
            min_diff = current_diff;
        }
    }

    cout << best_num << "/" << best_den << endl;
    return 0;
}

#include <iostream>
#include <cmath>
#include <algorithm>
#include <limits>
using namespace std;

using int64 = long long;

int64 gcd(int64 a, int64 b) {
    for (; b != 0; ) {
        a %= b;
        swap(a, b);
    }
    return a;
}

int main() {
    int64 x, y, n;
    cin >> x >> y >> n;

    int64 best_num = 0, best_den = 1;
    double smallest_error = numeric_limits<double>::max();

    for (int64 denom = 1; denom <= n; ++denom) {
        int64 num_floor = 0;
        int64 left = 0, right = 100000;
        while (left <= right) {
            int64 mid = (left + right) >> 1;
            if (mid * y <= x * denom) {
                num_floor = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        int64 num_ceil = 0;
        left = 0, right = 100000;
        while (left <= right) {
            int64 mid = (left + right) >> 1;
            if (mid * y < x * denom) {
                left = mid + 1;
            } else {
                num_ceil = mid;
                right = mid - 1;
            }
        }

        double err_floor = fabs(static_cast<double>(num_floor) / denom - static_cast<double>(x) / y);
        double err_ceil = fabs(static_cast<double>(num_ceil) / denom - static_cast<double>(x) / y);

        int64 chosen_num = num_floor;
        int64 chosen_den = denom;
        double chosen_err = err_floor;

        if (err_ceil < err_floor - 1e-9) {
            chosen_num = num_ceil;
            chosen_den = denom;
            chosen_err = err_ceil;
        }

        int64 g = gcd(chosen_num, chosen_den);
        chosen_num /= g;
        chosen_den /= g;

        if (chosen_err < smallest_error) {
            best_num = chosen_num;
            best_den = chosen_den;
            smallest_error = chosen_err;
        }
    }

    cout << best_num << "/" << best_den << endl;
    return 0;
}

