#include <iostream>
#include <cmath>
#include <algorithm>
#include <limits>
#include <type_traits>
using namespace std;

using lint = long long;

lint gcd(lint a, lint b) {
    if (!a || !b) return a | b;
    int shift = __builtin_ctzll(a | b);
    a >>= __builtin_ctzll(a);
    do {
        b >>= __builtin_ctzll(b);
        if (a > b) swap(a, b);
        b -= a;
    } while (b);
    return a << shift;
}

int main() {
    lint x, y, n;
    cin >> x >> y >> n;

    lint best_num = 0, best_den = 1;
    double min_error = numeric_limits<double>::max();

    for (lint d = 1; d <= n; ++d) {
        lint num1 = 0;
        lint left = 0, right = 100000;
        while (left <= right) {
            lint mid = left + (right - left) / 2;
