                num1 = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        lint num2 = 0;
        left = 0, right = 100000;
        while (left <= right) {
            lint mid = left + (right - left) / 2;
            if (mid * y < x * d) {
                left = mid + 1;
            } else {
                num2 = mid;
                right = mid - 1;
            }
