#include <bits/stdc++.h>

using namespace std;

using ll      =         long long;
using ldbl    =       long double;
using ratio_t =       pair<ll,ll>;
using ratios  = multiset<ratio_t>;

ll b, c, g, n, q, r, t, u, x, y, z; map<ldbl,ratios> result;

int main()
{
    ios_base::sync_with_stdio(false), cin.tie(nullptr), cout.tie(nullptr);

    cin >> x >> y >> n, g = gcd(x,y), x /= g, y /= g, q = x/y, r = x%y;

    const auto save_ratio = [](ll a)
    {
        g = gcd(a,b), result[ldbl(abs(u-a*z))/t].emplace(b/g,a/g);
    };

    for (b = 1; b <= n; ++b)
    {
        g = gcd(y,b), c = b/g, z = y/g, t = b*z, u = q*t+r*c, save_ratio(u/z);

        if (u%z)
            save_ratio((u+z-1)/z);
    }

    auto p = result.cbegin()->second.cbegin();

    cout << p->second << '/' << p->first;
}

#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using ld = long double;
using rat = pair<ll, ll>;
using ratset = multiset<rat>;

ll b, c, g, n, q, r, t, u, x, y, z;
map<ld, ratset> result;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    cin >> x >> y >> n;
    g = gcd(x, y);
    x /= g;
    y /= g;
    q = x / y;
    r = x % y;

    auto save_ratio = [&](ll a) {
        g = gcd(a, b);
        ll num = b / g;
        ll den = a / g;
        ld key = ld(abs(u - a * z)) / t;
        result[key].emplace(num, den);
    };

    for (b = 1; b <= n; ++b) {
        g = gcd(y, b);
        c = b / g;
        z = y / g;
        t = b * z;
        u = q * t + r * c;
        save_ratio(u / z);

        if (u % z) {
            save_ratio((u + z - 1) / z);
        }
    }

    auto first_group = result.begin()->second;
    auto first_ratio = first_group.begin();

    cout << first_ratio->second << '/' << first_ratio->first;
}

