float Tabs(double n){
    if(n>=0) return n;
    return -n;
}

int solve_it(int x,int y,int b){
    double target = (double)x/y;
    int lb=0,ub=1000000;
    for(int i=0; i<25; i++){
        int a = (lb+ub)/2;
        if((double)a/b < target) lb = a;
        else ub = a;
    }
    int res;
    double diff=DBL_MAX;
    for(int a=lb-10; a<=ub+10; a++){
