                    ans=tmp1;
                    ansx=ll;
                    ansy=i;
                }
            }
        }
    }

    long long a=gcd(ansx,ansy);
    ansx/=a;ansy/=a;
    cout << ansx << "/" << ansy;

    return 0;

}

#include <iostream>
