            i64 lhs = error * best_b;
            i64 rhs = min_error * b;

            if (lhs < rhs) {
                min_error = error;
                best_a = a;
                best_b = b;
            } else if (lhs == rhs) {
                if (b < best_b || (b == best_b && a < best_a)) {
                    best_a = a;
                    best_b = b;
                }
            }
        }
    }

    cout << best_a << "/" << best_b << endl;
    return 0;
}

