inline int subtract_with_mod(int x, int y, lint mod) {
    return (x - y < 0) ? (x - y + static_cast<int>(mod)) : (x - y);
}

inline int sum_with_mod(int x, int y, lint mod) {
    return (x + y >= static_cast<int>(mod)) ? (x + y - static_cast<int>(mod)) : (x + y);
}

void construct_sequence(int position, int current_value) {
    if (current_value <= n_val) {
        ++total_count;
        int element_value = subtract_with_mod(total_count, current_value, MOD1);
        sequence[position - 1].push_back(element_value);
        prefix_sum[position - 1] = sum_with_mod(prefix_sum[position - 1], element_value, MOD2);
    }
    if (position > 6) return;
    for (int digit = 0; digit <= 9; ++digit) {
        construct_sequence(position + 1, current_value * 10 + digit);
    }
}

void calculate_answer(int pos, lint current_number) {
    if (current_number > n_val) return;
    if (pos > 1) {
        if (10LL * current_number * MAX_X_LIMIT > n_val &&
            1LL * (current_number + 1) * MAX_X_LIMIT - 1 <= n_val) {
            for (int idx = 0; idx < 7; ++idx) {
                lint temp = (c_val - current_number * power_of_ten[idx]) % MOD1;
                if (temp < 0) temp += MOD1;
                int val = static_cast<int>(temp);
                auto it = lower_bound(sequence[idx].begin(), sequence[idx].end(), MOD1 - val);
                int index = it - sequence[idx].begin();
                int term1 = static_cast<int>(1LL * val * sequence[idx].size() % MOD2);
                int term2 = prefix_sum[idx];
                int term3 = sum_with_mod(term1, term2, MOD2);
                final_result = sum_with_mod(final_result, term3, MOD2);
                int term4 = static_cast<int>(1LL * MOD1 * (sequence[idx].size() - index) % MOD2);
                final_result = subtract_with_mod(final_result, term4, MOD2);
            }
            c_val += total_count;
            return;
        }
        ++c_val;
        lint diff = c_val - current_number;
        int diff_mod = static_cast<int>((diff % MOD1 + MOD1) % MOD1);
        final_result = sum_with_mod(final_result, diff_mod, MOD2);
    }
    int start_digit = (pos == 1) ? 1 : 0;
    for (int digit = start_digit; digit <= 9; ++digit) {
        calculate_answer(pos + 1, current_number * 10 + digit);
    }
}

