}

void traverse(int depth, int current) {
    if (current <= N_val) {
        ++node_count;
        int val = difference_mod(node_count, current, MOD_A);
        container[depth - 1].emplace_back(val);
        arr_sum[depth - 1] = union_mod(arr_sum[depth - 1], val, MOD_B);
    }
