#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll MOD = 1000000007LL;

class Modular {
public:
    ll val;
    Modular(ll v = 0) : val(v % MOD) { if (val < 0) val += MOD; }
    ll value() const { return val; }
};

Modular operator+(const Modular& a, const Modular& b) {
    ll s = a.val + b.val;
    return s >= MOD ? s - MOD : s;
}

Modular operator-(const Modular& a, const Modular& b) {
    ll d = a.val - b.val;
    return d < 0 ? d + MOD : d;
}

Modular operator*(const Modular& a, const Modular& b) {
    return (a.val * b.val) % MOD;
}

Modular power(Modular base, int exp) {
    Modular res(1);
    while (exp) {
        if (exp & 1) res = res * base;
        base = base * base;
        exp >>= 1;
    }
    return res;
}

const ll MOD2 = 998244353LL;
const ll BASE_WIDTH = 1000000LL;
const int MAX_DIM = 6;

ll input_N;
ll current_pos;
int global_suf_size;
Modular global_sums[MAX_DIM + 2];
vector<ll> suffix_data[MAX_DIM + 2];

void generate_recursive(int level, ll val) {
    ll num = ((current_pos++ - val) % MOD2 + MOD2) % MOD2;
    global_sums[level] = global_sums[level] + Modular(num);
    suffix_data[level].push_back(num);
    if (level == MAX_DIM) return;
    for (int dig = 0; dig < 10; ++dig) {
        generate_recursive(level + 1, val * 10 + dig);
    }
}

void process_recursive(ll val) {
    if (val >= input_N) return;
    if ((val + 1) * BASE_WIDTH <= input_N && val * BASE_WIDTH * 10 >= input_N) {
        ll scale = 1;
        for (int lvl = 0; lvl <= MAX_DIM; ++lvl) {
            ll len = suffix_data[lvl].size();
