const ll MOD_B = 1000000007;
const ll BASE_VAL = 1000000;

int N;
ll totalCount;
ll finalResult;
ll prefixSums[8];
vector<ll> buckets[8];

void traverse(int depth, ll currentVal);
void processNode(ll curVal);

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    cin >> N;
    traverse(0, 0);
    for (int i = 0; i <= 7; i++) {
        sort(buckets[i].begin(), buckets[i].end());
    }
    totalCount = 0;
    for (int d = 1; d <= 9; d++) {
        processNode(d);
    }
    cout << finalResult % MOD_B << endl;
    return 0;
}

void traverse(int depth, ll currentVal) {
    if (depth == 7) return;

    totalCount++;
    ll value = ((totalCount - currentVal) % MOD_A + MOD_A) % MOD_A;
    buckets[depth].push_back(value);
    prefixSums[depth] = (prefixSums[depth] + value) % MOD_B;

    for (int digit = 0; digit <= 9; digit++) {
        traverse(depth + 1, currentVal * 10 + digit);
    }
}

void processNode(ll curVal) {
    if (curVal > N) return;

    if (curVal * BASE_VAL + BASE_VAL - 1 <= N && curVal * BASE_VAL * 10 > N) {
        ll localCount = totalCount;
        for (int idx = 0, multiplier = 1; idx <= 6; idx++, multiplier *= 10) {
            ll bucketSize = buckets[idx].size();
            ll diff = ((localCount - curVal * multiplier) % MOD_A + MOD_A) % MOD_A;
            ll position = lower_bound(buckets[idx].begin(), buckets[idx].end(), MOD_A - diff) - buckets[idx].begin();
            finalResult = (finalResult + diff * bucketSize + prefixSums[idx]) % MOD_B;
            finalResult = (finalResult - MOD_A * (bucketSize - position) % MOD_B + MOD_B) % MOD_B;
            totalCount += bucketSize;
        }
        return;
    }

    totalCount++;
    ll contribution = ((totalCount - curVal) % MOD_A + MOD_A) % MOD_A;
    finalResult = (finalResult + contribution) % MOD_B;

    for (int digit = 0; digit <= 9; digit++) {
        processNode(curVal * 10 + digit);
    }
}

