typedef long long ll;
const ll MOD_A = 998244353;
const ll MOD_B = 1000000007;
const ll BASE = 1000000;

int N;
ll global_counter = 0;
ll answer = 0;
ll partial_sums[8];
vector<ll> digit_groups[8];

void build_data(int depth, ll num);
void handle_number(ll start_val);

int main() {
    cin >> N;
    build_data(0, 0);
    for (int i = 0; i <= 7; ++i) {
        sort(digit_groups[i].begin(), digit_groups[i].end());
    }
    global_counter = 0;
    for (int d = 1; d <= 9; ++d) {
        handle_number(d);
    }
    cout << answer % MOD_B << '\n';
    return 0;
}

void build_data(int depth, ll num) {
    if (depth == 7) return;
    global_counter++;
    ll computed = ((global_counter - num) % MOD_A + MOD_A) % MOD_A;
    digit_groups[depth].push_back(computed);
    partial_sums[depth] = (partial_sums[depth] + computed) % MOD_B;
    for (int digit = 0; digit <= 9; ++digit) {
        build_data(depth + 1, num * 10 + digit);
    }
}

void handle_number(ll start_val) {
    if (start_val > N) return;
    if (start_val * BASE + BASE - 1 <= N && start_val * BASE * 10 > N) {
        ll current_total = global_counter;
        for (int i = 0, multiplier = 1; i <= 6; ++i, multiplier *= 10) {
            ll size = digit_groups[i].size();
            ll diff = ((current_total - start_val * multiplier) % MOD_A + MOD_A) % MOD_A;
            ll index = lower_bound(digit_groups[i].begin(), digit_groups[i].end(), MOD_A - diff) - digit_groups[i].begin();
