inline LL read() {
    LL x = 0, f = 1;
    char ch = getchar();
    while (ch < '0' || ch > '9') { if (ch == '-') f = -1; ch = getchar(); }
    while (ch >= '0' && ch <= '9') { x = x * 10 + (ch - '0'); ch = getchar(); }
    return x * f;
}

LL mod_pow(LL base, LL exp, LL mod) {
    LL result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

LL N;
LL counter1 = 0;
LL first_sum[7];
vector<LL> first_digits[7];

void generate_first(LL depth, LL current) {
    if (depth > 6) return;
    first_digits[depth].push_back((counter1 - current + MOD1) % MOD1);
    first_sum[depth] = (first_sum[depth] + (counter1 - current + MOD1) % MOD1) % MOD1;
    counter1++;
    for (LL digit = 0; digit <= 9; ++digit) {
        generate_first(depth + 1, current * 10 + digit);
    }
}

LL counter2 = -1;
