    x %= MOD_P;
    if (x < 0) x += MOD_P;
    return x;
}

i64 N, counter;
i64 cumsum[7];
int answer;
vector<int> bucket[7];

void generate(int depth, i64 val) {
    counter++;
    bucket[depth].emplace_back((int)normalize(counter - val));
