                counter += bucket[k].size();
            }
            return;
        }
        answer = (answer + (int)normalize(++counter - val)) % (int)MOD_Q;
    }
    int start = (depth == 0) ? 1 : 0;
    for (int dig = start; dig <= 9; ++dig) {
        search(depth + 1, val * 10 + dig);
    }
}

