def solve(n, memo={}):
    if n == 0:
        return 0

    if n in memo:
        return memo[n]

    # Precompute a array (1, 11, 111, ..., up to 16 digits)
    a = [0] * 17
    for i in range(1, 17):
        a[i] = a[i-1] * 10 + 1

    ind = 1
    while ind <= 16 and a[ind] <= n:
        ind += 1

    res1 = float('inf')
    res2 = float('inf')

    res1 = (n // a[ind-1]) * (ind-1) + solve(n % a[ind-1], memo)

    if a[ind] - n < n:
        res2 = ind + solve(a[ind] - n, memo)

    result = res1 if res1 < res2 else res2
