    i64 base = res;
    int base_cnt = cnt;
    while (res + base <= n) {
        res += base;
        cnt += base_cnt;
    }
    return {res, cnt};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    i64 n;
    cin >> n;

    priority_queue<Node> pq;
    pq.push({n, 0});

    while (!pq.empty()) {
        Node cur = pq.top();
        pq.pop();

        if (cur.value == 0) {
            cout << cur.cost << '\n';
            return 0;
        }

        if (check_visited(cur.value)) continue;
        visited.insert(cur.value);

        vector<Node> candidates;
        candidates.push_back(compute_lower(cur.value));
        candidates.push_back(compute_upper(cur.value));
        candidates.push_back(compute_uupper(cur.value));

        for (auto& cand : candidates) {
            cand.cost += cur.cost;
            cand.value = std::abs(cur.value - cand.value);
            pq.push(cand);
        }
    }

    cout << 0 << '\n';
    return 0;
}

