        long long q1 = val / cand[idx];
        long long q2 = q1 + 1;
        long long res1 = q1 * (idx + 1) + rec(idx - 1, val - q1 * cand[idx]);
        long long res2 = q2 * (idx + 1) + rec(idx - 1, val - q2 * cand[idx]);
        long long ans = min(res1, res2);
        if (val <= v) memo[idx][val] = ans;
        return ans;
    };

    cout << rec(16, v) << '\n';
    return 0;
}

