    vector<int> digits;
    bool neg = x < 0;
    if (neg) x = -x;
    while (x > 0) {
        int d = x % 10;
        digits.push_back(d - (neg ? -1 : 1));
        x /= 10;
    }
    i64 res = 0;
    for (int i = digits.size() - 1; i >= 0; --i) {
        res = res * 10 + digits[i];
    }
    return neg ? -res : res;
}

