    bool neg = x < 0;
    if (neg) x = -x;
    i64 c = 0;
    i64 cx = x;
    while (x > 0) {
        c = c * 10 + (neg ? -1 : 1);
        x /= 10;
    }
    c = c * 10 + 1;
    return neg ? cx + c : cx - c;
}

