void initialize() {
    power10[0] = 1;
    for (int i = 1; i <= 17; ++i) {
        power10[i] = power10[i-1] * 10;
    }
    repunit[0] = 0;
    for (int i = 1; i <= 17; ++i) {
        repunit[i] = repunit[i-1] * 10 + 1;
    }
