    if (value == 0) {
        return multiples * position;
    }
    llu alternative1 = position + recursive_compute(sequence[position] - value, position - 1);
    llu alternative2 = recursive_compute(value, position - 1);
    return multiples * position + min(alternative1, alternative2);
}

