const i64 MOD = 1000000007LL;
i64 dp[17];

i64 solve(i64 n, int t) {
    if (t == 0) {
        return (n == 0) ? 0 : MOD;
    }
    i64 coin = dp[t];
    i64 cnt = n / coin;
    if (n % coin == 0) return cnt * t;
    i64 option1 = solve(n - coin * cnt, t - 1) + cnt * t;
    i64 option2 = solve(coin * (cnt + 1) - n, t - 1) + (cnt + 1) * t;
    return min(option1, option2);
}

