    return cnt

def repunit(n):
    d = countDigits(n)
    res = 0
    for _ in range(d):
        res = res * 10 + 1
    return res if res <= n else res // 10

def compute(n):
    if n <= 6:
        return n
    if n <= 11:
        return 13 - n

    r = repunit(n)
    rNext = r * 10 + 1

    if n % r == 0:
        if n <= rNext // 2 + r:
            return countDigits(r) * n // r
        return countDigits(rNext) + compute(rNext - n)
    else:
        base = (n // r) * r
        val1 = compute(base) + compute(n - base)
        val2 = countDigits(rNext) + compute(rNext - n)
        if n > rNext // 2:
            return val1 if val1 < val2 else val2
        return val1

if __name__ == "__main__":
    n = int(input())
