    // First replacement: "at" -> "@" (skip first character)
    for (size_t i = 1; i + 2 <= input.size(); ++i) {
        if (input[i] == 'a' && input[i+1] == 't') {
            input.replace(i, 2, "@");
            break;
        }
    }

    // Second replacement: "dot" -> "." (skip first character)
    for (size_t i = 1; i + 3 <= input.size(); ++i) {
        while (i + 3 <= input.size() && input[i] == 'd' && input[i+1] == 'o' && input[i+2] == 't') {
            if (i + 3 < input.size()) {
                input.replace(i, 3, ".");
            } else {
                break;
            }
            i += 1; // adjust position after replacement
        }
    }

    cout << input;
    return 0;
}

