inline bool startsAt(const string& s, size_t i) {
    return i + 1 < s.size() && s[i] == 'a' && s[i+1] == 't';
}

inline bool startsDot(const string& s, size_t i) {
    return i + 2 < s.size() && s[i] == 'd' && s[i+1] == 'o' && s[i+2] == 't';
}

string process(const string& s) {
    if (s.empty()) return "";
    string r;
    r.reserve(s.length());
    r.push_back(s.front());
    bool atUsed = false;
    size_t i = 1;
    while (i < s.size()) {
        if (startsAt(s, i)) {
            if (i + 1 == s.size() - 1) {
                r.push_back(s[i]);
                r.push_back(s[i+1]);
                i += 2;
            } else {
                if (!atUsed) {
                    i += 2;
                    r.push_back('@');
                    atUsed = true;
                } else {
                    r.push_back(s[i]);
                    r.push_back(s[i+1]);
                    i += 2;
                }
            }
        } else if (startsDot(s, i)) {
            if (i + 2 == s.size() - 1) {
                r.push_back(s[i]);
                r.push_back(s[i+1]);
                r.push_back(s[i+2]);
                i += 3;
            } else {
                i += 3;
                r.push_back('.');
            }
        } else {
            r.push_back(s[i]);
            ++i;
        }
    }
    return r;
}

