using namespace std;

int main() {
    string input;
    cin >> input;

    string result = input;

    // Replace "at" with '@' at first occurrence (not at start or end)
    for (size_t i = 1; i + 1 < result.length(); ++i) {
        if (result[i] == 'a' && result[i+1] == 't') {
            result[i] = '@';
            result.erase(i+1, 1);
            break;
        }
    }

    // Replace "dot" with '.' at first occurrence (not at start or end)
    for (size_t i = 1; i + 2 < result.length(); ++i) {
        if (result[i] == 'd' && result[i+1] == 'o' && result[i+2] == 't') {
            result[i] = '.';
            result.erase(i+1, 2);
            break;
        }
    }

    // Output the result, skipping characters after '@' and '.' as per original logic
    for (size_t i = 0; i < result.length(); ++i) {
        if (result[i] == '@') {
            cout << '@';
            ++i;
            continue;
        }
        if (result[i] == '.') {
            cout << '.';
            i += 2;
            continue;
        }
        cout << result[i];
    }
    cout << '\n';

    return 0;
}

