int main() {
    string input;
    cin >> input;

    vector<string> results;
    string current = string(1, input[0]);
    results.push_back(current);

    int atCount = 0;

    for (size_t i = 1; i < input.length() - 1; ++i) {
        string threeChar = "";
        string twoChar = "";

        if (i + 2 < input.length() - 1) {
            threeChar = input.substr(i, 3);
        }
        if (i + 1 < input.length() - 1) {
            twoChar = input.substr(i, 2);
        }

        if (threeChar == "dot") {
            current += '.';
            for (auto& s : results) s += '.';
            i += 2;
        } else if (twoChar == "at") {
            atCount++;
            for (int j = 0; j < atCount - 1; ++j) results[j] += "at";
            for (int j = atCount - 1; j < (int)results.size(); ++j) results[j] += '@';
            current += input[i];
            current += input[i+1];
            results.push_back(current);
            i += 1;
        } else {
            current += input[i];
            for (auto& s : results) s += input[i];
        }
    }

    for (auto& s : results) s += input.back();

    sort(results.begin(), results.end());
    cout << results[0];

    return 0;
}

