        x = x * x % mod
        n >>= 1
    return res

def main():
    input = sys.stdin.read
    data = input().split()
    idx = 0
    n = int(data[idx])
    idx += 1

    a = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            a[i][j] = int(data[idx])
            idx += 1
            a[i][j] = a[i][j] * modpow(100, mod - 2) % mod
            a[i][j] = (a[i][j] % mod + mod) % mod

    if n == 1:
        print(a[0][0])
        return

    m = n // 2

    # Initialize cnt and cnt2 arrays
    max_size = (1 << 20)
    cnt = [0] * max_size
    cnt2 = [0] * max_size

