        if cur == m:
            nxt = 0
            id_val = 0
            for j in range(1 << n):
                if bin(j).count('1') != m:
                    continue
                vi = [i for i in range(n) if (j >> i) & 1]
                ok = 0
                for perm in permutations(vi):
