            if ((j >> i) & 1):
                cnt[j] = (cnt[j] + cnt[j ^ (1 << i)]) % mod

    all_val = cnt[(1 << 20) - 1]

    dfs2(m, [], 1)
    for i in range(max_size):
        cnt2[i] %= mod

    rev = [-1] * (1 << n)
    nd = 0
    for i in range(1 << n):
