        cin >> N;
        vector<vector<int>> P(N, vector<int>(N));
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                cin >> P[i][j];
            }
        }

        map<bitset<S>, FieldMod> G;
        G[1] = 1;

        for (int i = 0; i < N; ++i) {
            map<vector<int>, FieldMod> H;
            for (auto& g : G) {
                vector<int> S;
                for (int m = 0; m < (1 << N); ++m) {
                    if (g.first[m]) {
