    # Bitset simulation using integers (since Python has arbitrary precision integers)
    # We'll use integers to represent bitsets up to 128 bits

    init = 1  # bit 0 set

    # State hashing
    state_index = {}
    index_state = []
    bfs_queue = deque()

    state_index[init] = 0
    index_state.append(init)
    bfs_queue.append((init, 0))

    while bfs_queue:
        cur, state_id = bfs_queue.popleft()
        if state_id != state_index[cur]:
            continue

        # Precompute derived states
        derived = [0] * N
        for i in range(N):
            for j in range(1 << N):
                if not ((j >> i) & 1):
                    new_j = j | (1 << i)
                    derived[i] |= (cur >> j) & 1 << new_j

        for mask in range(1 << N):
            next_state = cur
            for bit in range(N):
                if (mask >> bit) & 1:
                    next_state |= derived[bit]

            if next_state not in state_index:
                new_id = len(state_index)
                state_index[next_state] = new_id
                index_state.append(next_state)
                bfs_queue.append((next_state, new_id))

    total_states = len(state_index)
    trans = [[0] * (1 << N) for _ in range(total_states)]

    for i in range(total_states):
        cur = index_state[i]
