            for k in range(1 << N):
                if not ((k >> j) & 1):
                    new_k = k | (1 << j)
                    derived[j] |= (cur >> k) & 1 << new_k

        for mask in range(1 << N):
            next_state = cur
            for bit in range(N):
                if (mask >> bit) & 1:
                    next_state |= derived[bit]
            trans[i][mask] = state_index[next_state]

    # Compute modular inverse of 100
    inv100 = pow(100, MOD-2, MOD)

    # DP initialization
    dp = [defaultdict(int), defaultdict(int)]
    start_state = init
    dp[0][state_index[start_state]] = 1
    cur_layer = 0

    for round_num in range(N):
        probs = [0] * (1 << N)
