                    coefficient = P[round_num][k]
                else:
                    coefficient = 100 - P[round_num][k]
                prob = (prob * inv100) % MOD
                prob = (prob * coefficient) % MOD
            probs[mask] = prob

        # Reset next layer
        dp[cur_layer ^ 1].clear()

        for s, val in dp[cur_layer].items():
            if val == 0:
                continue
            for mask in range(1 << N):
                next_s = trans[s][mask]
