import sys
from collections import defaultdict

MOD = 1000000007

def mod_inv(a, mod=MOD):
    """Extended Euclidean Algorithm to find modular inverse"""
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    a = a % mod
    if a < 0:
        a += mod
    gcd, x, _ = extended_gcd(a, mod)
    if gcd != 1:
        return -1  # Modular inverse doesn't exist
    return (x % mod + mod) % mod

class Modular:
    def __init__(self, val=0):
        self.val = val % MOD
        if self.val < 0:
            self.val += MOD

    def __add__(self, other):
        if isinstance(other, Modular):
            return Modular((self.val + other.val) % MOD)
        return Modular((self.val + other) % MOD)

    def __sub__(self, other):
        if isinstance(other, Modular):
            return Modular((self.val - other.val) % MOD)
        return Modular((self.val - other) % MOD)

    def __mul__(self, other):
        if isinstance(other, Modular):
            return Modular((self.val * other.val) % MOD)
        return Modular((self.val * other) % MOD)

    def __truediv__(self, other):
        if isinstance(other, Modular):
            inv = mod_inv(other.val)
            if inv == -1:
                raise ValueError("Cannot divide by zero in modular arithmetic")
            return Modular((self.val * inv) % MOD)
        inv = mod_inv(other)
        if inv == -1:
            raise ValueError("Cannot divide by zero in modular arithmetic")
        return Modular((self.val * inv) % MOD)

    def __eq__(self, other):
        if isinstance(other, Modular):
            return self.val == other.val
        return self.val == other

    def __repr__(self):
        return str(self.val)

