    idx += 1

    tab = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            tab[i][j] = int(data[idx])
            idx += 1

    # Precompute maska for all combinations of 3 elements from 1..6
    maska = {}
    xd = 0
    for i in range(1, 7):
        for j in range(i + 1, 7):
            for k in range(j + 1, 7):
                maska[(1 << i) ^ (1 << j) ^ (1 << k)] = (1 << xd)
                xd += 1

    # Extend tab for indices up to 6
    for i in range(n + 1, 7):
        tab[i][i] = 100

    # Create kraw list (all pairs (i,j) for i,j in 1..6)
    kraw = []
    for i in range(1, 7):
        for j in range(1, 7):
            kraw.append((i, j))

    # Constants
    MOD = 10**9 + 7

    # Modular exponentiation
    def pot(a, w):
        if w == 0:
            return 1
        b = pot(a, w // 2)
        b = (b * b) % MOD
        if w & 1:
            b = (b * a) % MOD
        return b

