                        for k1 in range(j1 + 1, 7):
                            if elo[i1][s[0] + k * 3] and elo[j1][s[1] + k * 3] and elo[k1][s[2] + k * 3]:
                                base = 126 if k else 0
                                mask |= maska.get((base ^ ((1 << i1) + (1 << j1) + (1 << k1))), 0)

