    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int x;
            cin >> x;
            //x = 1;
            mat[i][j] = Mint(x) / Mint(100);
        }
    }

    using ST = pair<V<int>, Mint>;
    V<ST> sts;
    sts.push_back(ST({0}, Mint(1)));

    for (int ph = 0; ph < n; ph++) {
        V<ST> nsts;
        for (int f = 1; f < (1 << n); f++) {
            Mint freq = 1;
            for (int i = 0; i < n; i++) {
                if ((f >> i) & 1) {
