class ModInt:
    def __init__(self, v=0):
        self.v = v % MOD
        if self.v < 0:
            self.v += MOD

    def set_v(self, _v):
        self.v = _v if _v < MOD else _v - MOD
        return self

    def __bool__(self):
        return self.v != 0

    def __neg__(self):
        return ModInt(0) - self

    def __add__(self, r):
        return ModInt().set_v(self.v + r.v)

    def __sub__(self, r):
        return ModInt().set_v(self.v + MOD - r.v)

    def __mul__(self, r):
        return ModInt().set_v((self.v * r.v) % MOD)

    def __truediv__(self, r):
        return self * r.inv()

    def __iadd__(self, r):
        self = self + r
        return self

    def __isub__(self, r):
        self = self - r
        return self

    def __imul__(self, r):
        self = self * r
        return self

    def __itruediv__(self, r):
        self = self / r
        return self

    def __eq__(self, r):
        return self.v == r.v

    def pow(self, n):
        x = ModInt(self.v)
        r = ModInt(1)
        while n:
            if n & 1:
                r *= x
            x *= x
            n >>= 1
        return r

    def inv(self):
        return self.pow(MOD - 2)

    def __repr__(self):
        return str(self.v)

def main():
