    for i in range(n):
        for j in range(n):
            x = int(data[idx])
            idx += 1
            mat[i][j] = ModInt(x) / ModInt(100)

    # sts is a list of (list_of_states, probability)
    sts = [([0], ModInt(1))]

    for ph in range(n):
        nsts = []
        for f in range(1, 1 << n):
            freq = ModInt(1)
            for i in range(n):
                if (f >> i) & 1:
                    freq *= mat[ph][i]
                else:
                    freq -= mat[ph][i]  # freq *= (1 - mat[ph][i])

            for st_states, st_prob in sts:
                nst = []
                for d in st_states:
