                            continue
                        if not ((f >> i) & 1):
                            continue
                        nst.append(d ^ (1 << i))

                if not nst:
                    continue

                nst.sort()
                # Remove duplicates
                unique_nst = []
                for x in nst:
                    if not unique_nst or unique_nst[-1] != x:
                        unique_nst.append(x)
                nst = unique_nst

                nsts.append((nst, st_prob * freq))

        # Sort by state list
        nsts.sort(key=lambda x: x[0])

        # Merge same states
        sts = []
        for st in nsts:
            if sts and sts[-1][0] == st[0]:
                new_prob = sts[-1][1] + st[1]
                sts[-1] = (sts[-1][0], new_prob)
            else:
                sts.append(st)

    ans = ModInt(0)
    if sts:
        ans = sts[0][1]

    print(ans.v)

if __name__ == "__main__":
    main()

