int mod_exp(int base, int exp) {
    int res = 1;
    while (exp) {
        if (exp & 1) res = (i64)res * base % MOD;
        base = (i64)base * base % MOD;
        exp >>= 1;
    }
    return res;
}

void init() {
    bin[0] = 1;
    for (int i = 1; i <= 20; ++i) bin[i] = bin[i-1] << 1;
    scanf("%d", &n);
    int inv = mod_exp(100, MOD - 2);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j) {
            scanf("%d", &p[i][j]);
            p[i][j] = (i64)p[i][j] * inv % MOD;
        }
    while (n < 6) {
        p[++n][n] = 1;
    }
}

bool bipartite_match(int depth) {
    if (depth > 3) return true;
    for (int i = 1; i <= 3; ++i) {
        if (!vis[i] && ma[a[depth]][b[i]]) {
            vis[i] = true;
            if (bipartite_match(depth + 1)) {
                vis[i] = false;
                return true;
            }
            vis[i] = false;
        }
    }
    return false;
}

void dfs2(int r, int c, int prob_val) {
    if (r > 3) {
        int mask = 0;
        for (int i = 1; i <= tot; ++i) {
            for (int k = 1; k <= 3; ++k) b[k] = pts[i][k];
            if (bipartite_match(1)) mask |= bin[i-1];
        }
        f[mask] = (f[mask] + prob_val) % MOD;
        return;
    }
    ma[a[r]][c] = 0;
    if (c == n) dfs2(r+1, 1, (i64)prob_val * (1 - p[a[r]][c] + MOD) % MOD);
    else dfs2(r, c+1, (i64)prob_val * (1 - p[a[r]][c] + MOD) % MOD);
    ma[a[r]][c] = 1;
    if (c == n) dfs2(r+1, 1, (i64)prob_val * p[a[r]][c] % MOD);
    else dfs2(r, c+1, (i64)prob_val * p[a[r]][c] % MOD);
