#include<bits/stdc++.h>
using namespace std;
const int N=1e5+10;
const int mod=1e9+7;
typedef unsigned long long ull;

int n,m,tt=0,ch[N][64],p[10][10],q[10][64],f[10][N];
map<ull,int> id;

int qpow(int a,int b) {
	int ret=1;
	while(b) {
		if(b&1) ret=1ll*ret*a%mod;
		a=1ll*a*a%mod,b>>=1;
	}
	return ret;
}

int dfs(ull s) {
	if(id[s]) return id[s];
	id[s]=++tt;
	for(int i=0;i<(1<<n);i++) {
		ull t=s;
		for(int j=0;j<(1<<n);j++)
			for(int k=0;k<n;k++)
				if((j>>k&1)&&(i>>k&1)&&(s>>(j^(1<<k))&1)) t|=1llu<<j;
		ch[id[s]][i]=dfs(t);
	}
	return id[s];
}

