#include <iostream>
#include <vector>
#include <unordered_map>
#include <functional>
using namespace std;

using ull = unsigned long long;
const int MOD = 1000000007;

int mod_pow(int base, int exp) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = (1LL * result * base) % MOD;
        base = (1LL * base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    const int MAX_STATE = 100010;
    const int MAX_MASK = 64;

    vector<vector<int>> child(MAX_STATE, vector<int>(MAX_MASK));
    vector<vector<int>> P(N, vector<int>(N));
    vector<vector<int>> Q(N, vector<int>(1 << N, 1));
    vector<vector<int>> F(N + 1, vector<int>(MAX_STATE));
    unordered_map<ull, int> state_to_index;
    int timer = 0;

    function<int(ull)> traverse = [&](ull state) -> int {
        auto it = state_to_index.find(state);
        if (it != state_to_index.end()) return it->second;
        state_to_index[state] = ++timer;
        for (int mask = 0; mask < (1 << N); ++mask) {
            ull next_state = state;
            for (int j = 0; j < (1 << N); ++j) {
                for (int k = 0; k < N; ++k) {
                    if (((j >> k) & 1) && ((mask >> k) & 1) && ((state >> (j ^ (1 << k))) & 1)) {
                        next_state |= (1ULL << j);
                    }
                }
            }
            child[state_to_index[state]][mask] = traverse(next_state);
        }
        return state_to_index[state];
    };

    traverse(1ULL);

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cin >> P[i][j];
            P[i][j] = (1LL * P[i][j] * mod_pow(100, MOD - 2)) % MOD;
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < (1 << N); ++j) {
            Q[i][j] = 1;
            for (int k = 0; k < N; ++k) {
                if (j >> k & 1) {
                    Q[i][j] = (1LL * Q[i][j] * P[k][i]) % MOD;
                } else {
                    Q[i][j] = (1LL * Q[i][j] * ((MOD + 1 - P[k][i]) % MOD)) % MOD;
                }
            }
        }
    }

    F[0][1] = 1;
    for (int step = 0; step < N; ++step) {
        for (int sid = 1; sid <= timer; ++sid) {
            for (int mask = 0; mask < (1 << N); ++mask) {
                F[step + 1][child[sid][mask]] = (F[step + 1][child[sid][mask]] + 1LL * F[step][sid] * Q[step][mask]) % MOD;
