#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int MAX_N = 10, MAX_M = 1000007, MAX_K = 200, MOD = 1000000007;
using Bitset = bitset<40>;

int n;
int popcount_table[1 << 10];
int edge_count[11];
int weight_func[1 << 10];
int state_queue[11][200];
int prob_matrix[11][11];
ll dp[11][1000007];
Bitset bit_state[11][1000007];
unordered_map<Bitset, int> state_map[11];

inline int fast_read() {
    int x = 0;
    char c = getchar();
    while (c < '0' || c > '9') c = getchar();
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    return x;
}

inline ll mod_pow(ll base, int exp) {
    ll result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

inline void process_state(int level) {
    state_queue[level][0] = 0;
    int new_state_count = 0;

    for (int mask = 0; mask < (1 << n); ++mask) {
        if (popcount_table[mask] == level) {
            state_queue[level][++state_queue[level][0]] = mask;
            weight_func[mask] = ++new_state_count;
        }
    }

    for (int i = 1; i <= edge_count[level - 1]; ++i) {
        if (dp[level - 1][i] == 0) continue;

        for (int mask = 0; mask < (1 << n); ++mask) {
            ll transition_prob = 1;
            for (int bit = 0; bit < n; ++bit) {
                if (mask & (1 << bit)) {
                    transition_prob = (transition_prob * prob_matrix[level][bit + 1]) % MOD;
                } else {
                    transition_prob = (transition_prob * ((1 - prob_matrix[level][bit + 1] + MOD) % MOD)) % MOD;
                }
            }

            Bitset new_bitset;
            bool changed = false;
            Bitset prev_bitset = bit_state[level - 1][i];

            for (int j = 1; j <= state_queue[level - 1][0]; ++j) {
                if (prev_bitset[state_queue[level - 1][j]]) {
                    for (int bit = 0; bit < n; ++bit) {
                        if ((mask & (1 << bit)) && !(state_queue[level - 1][j] & (1 << bit))) {
                            new_bitset[weight_func[state_queue[level - 1][j] | (1 << bit)]] = 1;
                            changed = true;
                        }
                    }
                }
            }

            if (!changed) continue;

            int new_index;
            if (state_map[level].find(new_bitset) == state_map[level].end()) {
                state_map[level][new_bitset] = ++edge_count[level];
                bit_state[level][edge_count[level]] = new_bitset;
            }
            new_index = state_map[level][new_bitset];

            dp[level][new_index] = (dp[level][new_index] + transition_prob * dp[level - 1][i]) % MOD;
        }
    }
}

int main() {
    n = fast_read();

    for (int mask = 0; mask < (1 << n); ++mask) {
        popcount_table[mask] = __builtin_popcount(mask);
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
