import sys
from collections import defaultdict

mod = 1000000007
inv = 570000004

def add(a, b):
    return a + b if a + b < mod else a + b - mod

def sub(a, b):
    return a - b + mod if a < b else a - b

def mul(a, b):
    return (a * b) % mod

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx])
    idx += 1

    # Create a mapping from bitset-like representation to integer IDs
    name = {}
    dfn = 0
    son = defaultdict(lambda: defaultdict(int))

    def dfs(s):
        nonlocal dfn
        if s in name:
            return name[s]
        ret = dfn
        name[s] = ret
        dfn += 1

        for i in range(1 << n):
            t = s
            for j in range(1 << n):
                if not (t >> j) & 1:
                    k = i & j
                    while k:
                        lowbit = k & -k
                        if (s >> (j ^ lowbit)) & 1:
                            t |= (1 << j)
                            break
                        k ^= lowbit
            son[ret][i] = dfs(t)
        return ret

