    def __neg__(self):
        return ModInt.make(self.normS(MOD - self.v))

    def __mul__(self, b):
        return ModInt.make((self.v * b.v) % MOD)

    def __truediv__(self, b):
        return self * b.inv()

    def __iadd__(self, b):
        self.v = self.normS(self.v + b.v)
        return self

    def __isub__(self, b):
        self.v = self.normS(self.v + MOD - b.v)
        return self

    def __imul__(self, b):
        self.v = (self.v * b.v) % MOD
        return self

    def __itruediv__(self, b):
        self.v = (self * b).v
        return self

    def __iadd1__(self):
        self.v = self.normS(self.v + 1)
        return self

    def __isub1__(self):
        self.v = self.normS(self.v + MOD - 1)
        return self

    def extgcd(self, a, b):
        p = [a, 1, 0]
        q = [b, 0, 1]
        while q[0]:
            t = p[0] // q[0]
            for i in range(3):
                p[i], q[i] = q[i], p[i] - t * q[i]
        if p[0] < 0:
            for i in range(3):
                p[i] = -p[i]
        return p[1], p[2], p[0]

    def inv(self):
        x, y, _ = self.extgcd(self.v, MOD)
        return ModInt.make(self.normS(x + MOD))

    def pow(self, p):
        if p < 0:
            return self.inv().pow(-p)
        a = ModInt(1)
        x = self
        while p:
            if p & 1:
                a *= x
            x *= x
            p >>= 1
        return a

    def __eq__(self, b):
        return self.v == b.v

    def __ne__(self, b):
        return self.v != b.v

    def __hash__(self):
        return hash(self.v)

    def __repr__(self):
        return str(self.v)

def main():
