    nxt = {}

    # Initialize with bitset where bit 0 is set
    initial_state = 1  # bit 0 set
    cur[initial_state] = ModInt(1)

    for i in range(N):
        for state, prob in cur.items():
            # Get positions where bit is set
            ones = []
            for pos in range(N):
                if state & (1 << pos):
                    ones.append(pos)

            # Iterate over all possible outcomes (2^N)
            for e in range(1 << N):
                pr = ModInt(1)
                for j in range(N):
                    if (e >> j) & 1:
                        pr *= p[i][j]
                    else:
                        pr *= (ModInt(1) - p[i][j])

                # Compute new state
                nb = 0
                for x in ones:
                    for r in range(N):
