    while (x < 0) x += MOD;
    return x;
}

struct Matrix {
    vector<vector<int>> mat;
    int n;

    Matrix(int sz = 0, int diag = 0) : n(sz), mat(sz, vector<int>(sz, 0)) {
        for (int i = 0; i < sz; ++i) mat[i][i] = diag;
    }

    vector<int>& operator[](int i) { return mat[i]; }

    Matrix operator*(const Matrix& other) const {
        Matrix res(n, 0);
        for (int i = 0; i < n; ++i)
            for (int k = 0; k < n; ++k)
                if (mat[i][k])
                    for (int j = 0; j < n; ++j)
                        res.mat[i][j] = norm(res.mat[i][j] + 1LL * mat[i][k] * other.mat[k][j]);
        return res;
    }

    Matrix operator+(const Matrix& other) const {
        Matrix res(n, 0);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                res.mat[i][j] = norm(mat[i][j] + other.mat[i][j]);
        return res;
    }

    bool operator==(const Matrix& other) const {
        if (n != other.n) return false;
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (mat[i][j] != other.mat[i][j]) return false;
        return true;
    }
};

Matrix matrix_exp(Matrix base, ll exp) {
    Matrix res(base.n, 1);
    while (exp) {
        if (exp & 1) res = res * base;
        base = base * base;
        exp >>= 1;
