        for (int j = 0; j <= m; ++j) {
            dp[pos][j][j] = 1;
        }

        for (int j = 0; j < m; ++j) {
            // Reset temp matrix
            memset(temp, 0, sizeof(temp));

            for (int a = 0; a <= m; ++a) {
                for (int b = 0; b <= m; ++b) {
                    for (int c = 0; c <= m; ++c) {
