def read_int():
    return int(sys.stdin.readline())

def add(x, y, mod=1000000007):
    return (x + y) % mod

class Matrix:
    def __init__(self, size):
        self.size = size
        self.a = [[0] * size for _ in range(size)]

    def toZero(self):
        self.a = [[0] * self.size for _ in range(self.size)]

    def toE(self):
        self.toZero()
        for i in range(self.size):
            self.a[i][i] = 1

    def __mul__(self, other):
        ret = Matrix(self.size)
        ret.toZero()
        for i in range(self.size):
            for j in range(self.size):
                for k in range(self.size):
                    ret.a[i][j] = add(ret.a[i][j], self.a[i][k] * other.a[k][j])
        return ret

def main():
    n, K = map(int, sys.stdin.readline().split())
    r = K + 1

