    for i in range(K + 1):
        rotr[i].toE()
        if i == 1:
            rotr[i].toZero()
            rotr[i].a[0][0] = 1
            rotr[i].a[1][K] = 1
            for j in range(2, K + 1):
                rotr[i].a[j][j - 1] = 1
        elif i > 1:
            rotr[i] = rotr[1] * rotr[i - 1]

    rotc = [Matrix(r) for _ in range(K + 1)]
    for i in range(K + 1):
        rotc[i].toE()
        if i == 1:
            rotc[i].toZero()
            rotc[i].a[0][0] = 1
            rotc[i].a[K][1] = 1
            for j in range(2, K + 1):
                rotc[i].a[j - 1][j] = 1
        elif i > 1:
            rotc[i] = rotc[i - 1] * rotc[1]

    two = [Matrix(r) for _ in range(70)]
    two[1].toE()
    for i in range(1, K + 1):
        two[1] = one[i] * two[1]

    bit = 0
    num = [0] * 70
    temp_n = n
