        num[bit] = temp_n % K
        temp_n //= K
        bit += 1

    for i in range(2, bit + 1):
        two[i].toE()
        for j in range(K):
            two[i] = rotr[j] * two[i - 1] * rotc[j] * two[i]

    num = num[:bit]
