using namespace std;

typedef long long ll;
typedef unsigned long long ull;

const int MAXN = 33;
const ll MOD = 1000000007;
const double EPS = 1e-8;
const double PI = acos(-1.0);
const ll INF = 0XFFFFFFFll;

inline void mod_add(ll &x, ll y) {
	x = (x + y) % MOD;
}

int size_r;

struct Matrix {
    ll mat[MAXN][MAXN];

    void clear() {
        memset(mat, 0, sizeof(mat));
    }

    void identity() {
        clear();
        for (int i = 0; i < size_r; ++i)
            mat[i][i] = 1;
    }

    Matrix operator * (const Matrix &other) const {
        Matrix res;
        res.clear();
        for (int i = 0; i < size_r; ++i)
            for (int j = 0; j < size_r; ++j)
                for (int k = 0; k < size_r; ++k)
                    mod_add(res.mat[i][j], mat[i][k] * other.mat[k][j]);
        return res;
    }
};

ll n_val, K_val;
Matrix unary_ops[70];
Matrix binary_ops[70];
Matrix row_transform[70];
Matrix col_transform[70];

int solve() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n_val >> K_val;
    size_r = K_val + 1;

    // Identity transformations for unary operations
    for (int i = 0; i <= K_val; ++i) {
        unary_ops[i].identity();
        if (i > 0) {
            for (int j = 0; j <= K_val; ++j)
                unary_ops[i].mat[i][j] = 1;
        }
    }

    // Precompute row transformations
    for (int i = 0; i <= K_val; ++i) {
        row_transform[i].identity();
        if (i == 1) {
            row_transform[i].clear();
            row_transform[i].mat[0][0] = 1;
            row_transform[i].mat[1][K_val] = 1;
            for (int j = 2; j <= K_val; ++j)
                row_transform[i].mat[j][j-1] = 1;
        } else if (i > 1) {
            row_transform[i] = row_transform[1] * row_transform[i-1];
        }
    }

    // Precompute column transformations
    for (int i = 0; i <= K_val; ++i) {
        col_transform[i].identity();
        if (i == 1) {
            col_transform[i].clear();
            col_transform[i].mat[0][0] = 1;
            col_transform[i].mat[K_val][1] = 1;
            for (int j = 2; j <= K_val; ++j)
                col_transform[i].mat[j-1][j] = 1;
        } else if (i > 1) {
            col_transform[i] = col_transform[i-1] * col_transform[1];
        }
    }

    // Initialize binary transformation
    binary_ops[1].identity();
    for (int i = 1; i <= K_val; ++i)
        binary_ops[1] = unary_ops[i] * binary_ops[1];

    // Convert n to base K
    vector<int> digits;
    ll temp = n_val;
    while (temp > 0) {
        digits.push_back(temp % K_val);
        temp /= K_val;
    }
    reverse(digits.begin(), digits.end());

    // Precompute combined binary transformations
    for (int idx = 2; idx <= (int)digits.size(); ++idx) {
        binary_ops[idx].identity();
