LL n,v[N];
struct node
{
	int v[35][35];
	node(){memset(v,0,sizeof(v));}
}S,T[N][35],s1[N][35],s2[N][35];
node operator * (node a,node b)
{
	node c;
	for(int i=0;i<=m;i++)
		for(int j=0;j<=m;j++)
			for(int k=0;k<=m;k++)
				c.v[i][j]=(c.v[i][j]+1ll*a.v[i][k]*b.v[k][j]%mod)%mod;
	return c;
}
int main()
{
	scanf("%lld%d",&n,&m);
	v[0]=n;while(v[len])v[len+1]=v[len]/m,v[len]%=m,len++;
	for(int i=0;i<len;i++)
	{
		if(!i)
		{
			for(int j=0;j<m;j++)
			{
				T[i][j].v[m][m]=1;
				for(int a=0;a<m;a++)
				{
