    Matrix C;
    const ll INF = 8e18;
    for (int k = 0; k < dim; ++k)
        for (int i = 0; i < dim; ++i)
            for (int j = 0; j < dim; ++j) {
                C.data[i][j] += A.data[i][k] * B.data[k][j];
                if (C.data[i][j] >= INF) C.data[i][j] %= MOD;
            }
    return C;
}

