    return s;
}
int sub(int a, int b) {
    int s = a - b;
    if (s < 0) s += mod;
    return s;
}
int mult(int a, int b) {
    return (1LL * a * b) % mod;
}
ll n;
int k;
vector < vector < int > > matrix_mult(vector < vector < int > > a, vector < vector < int > > b) {
    vector < vector < int > > c(k + 1, vector < int >(k + 1, 0));
    for (int i = 0; i <= k; i++) {
        for (int j = 0; j <= k; j++) {
            for (int t = 0; t <= k; t++) {
                c[i][t] = sum(c[i][t], mult(a[i][j], b[j][t]));
            }
        }
    }
    return c;
}
vector < vector < int > > pref[100];
vector < vector < int > > shift_by_1(vector < vector < int > > mat) {
    vector < vector < int > > c(k + 1, vector < int >(k + 1, 0));
    for (int i = 0; i <= k; i++) {
        for (int j = 0; j <= k; j++) {
            int ni = i;
            if (ni < k) ni = (ni + k - 1) % k;
            int nj = j;
            if (nj < k) nj = (nj + k - 1) % k;
            c[i][j] = mat[ni][nj];
        }
    }
    return c;
}
