sys.setrecursionlimit(10000)

mod = 10**9 + 7

def sum_mod(a, b):
    s = a + b
    if s >= mod:
        s -= mod
    return s

def sub_mod(a, b):
    s = a - b
    if s < 0:
        s += mod
    return s

def mult_mod(a, b):
    return (a * b) % mod

def matrix_mult(a, b, k):
    c = [[0] * (k + 1) for _ in range(k + 1)]
    for i in range(k + 1):
        for j in range(k + 1):
            for t in range(k + 1):
                c[i][t] = sum_mod(c[i][t], mult_mod(a[i][j], b[j][t]))
    return c

def shift_by_1(mat, k):
    c = [[0] * (k + 1) for _ in range(k + 1)]
    for i in range(k + 1):
        for j in range(k + 1):
            ni = i
            if ni < k:
                ni = (ni + k - 1) % k
            nj = j
            if nj < k:
                nj = (nj + k - 1) % k
            c[i][j] = mat[ni][nj]
    return c

def init(n_val, k_val, pref):
    digs = 0
    cop = n_val
    while cop > 0:
        cop //= k_val
        digs += 1

    pref[0] = [[0] * (k_val + 1) for _ in range(k_val + 1)]
    for i in range(1, k_val):
        pref[0][i][i] = 1
    pref[0][0][k_val] = 1
    pref[0][k_val][0] = mod - 1
    pref[0][k_val][k_val] = 2

    for step in range(digs):
        pref[step + 1] = [row[:] for row in pref[step]]
        cur = pref[step]
        for i in range(1, k_val):
            cur = shift_by_1(cur, k_val)
            pref[step + 1] = matrix_mult(pref[step + 1], cur, k_val)

def solve(n_val, k_val, pref):
    if n_val == 0:
        c = [[0] * (k_val + 1) for _ in range(k_val + 1)]
        for i in range(k_val + 1):
            c[i][i] = 1
        return c

    dig = 0
    pw = 1
    while pw <= n_val // k_val:
        pw *= k_val
        dig += 1

    if n_val == pw:
        return pref[dig]

    steps = n_val // pw
    left = n_val - steps * pw

    cur_mat = solve(0, k_val, pref)
    cur_coef = pref[dig]

    for i in range(steps):
        cur_mat = matrix_mult(cur_mat, cur_coef, k_val)
        cur_coef = shift_by_1(cur_coef, k_val)

    other_mat = solve(left, k_val, pref)
    for i in range(steps):
        other_mat = shift_by_1(other_mat, k_val)

    return matrix_mult(cur_mat, other_mat, k_val)

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n_val = int(data[0])
    k_val = int(data[1])

    pref = [None] * 100
    init(n_val, k_val, pref)
    mat = solve(n_val, k_val, pref)
    print(mat[k_val][k_val])

if __name__ == "__main__":
    main()

