#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using ld = long double;
constexpr int MOD = 1000000007;

int add_mod(int a, int b) {
    int res = a + b;
    if (res >= MOD) res -= MOD;
    return res;
}

int sub_mod(int a, int b) {
    int res = a - b;
    if (res < 0) res += MOD;
    return res;
}

int mul_mod(int a, int b) {
    return (1LL * a * b) % MOD;
}

ll N;
int K;
vector<vector<int>> multiply_matrices(const vector<vector<int>>& A, const vector<vector<int>>& B) {
    int size = K + 1;
    vector<vector<int>> C(size, vector<int>(size, 0));
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            for (int t = 0; t < size; ++t) {
                C[i][t] = add_mod(C[i][t], mul_mod(A[i][j], B[j][t]));
            }
        }
    }
    return C;
}

vector<vector<vector<int>>> precomputed(100);
vector<vector<int>> cyclic_shift(const vector<vector<int>>& mat) {
    int size = K + 1;
    vector<vector<int>> result(size, vector<int>(size, 0));
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            int ni = i;
            if (ni < K) ni = (ni + K - 1) % K;
            int nj = j;
            if (nj < K) nj = (nj + K - 1) % K;
            result[i][j] = mat[ni][nj];
        }
    }
    return result;
}

void build_tables() {
    ll digits = 0;
    ll temp = N;
    while (temp > 0) {
        temp /= K;
        digits++;
    }
    precomputed[0].resize(K + 1, vector<int>(K + 1, 0));
    for (int i = 1; i < K; ++i) {
        precomputed[0][i][i] = 1;
    }
    precomputed[0][0][K] = 1;
    precomputed[0][K][0] = MOD - 1;
    precomputed[0][K][K] = 2;

    for (int step = 0; step < digits; ++step) {
        precomputed[step + 1] = precomputed[step];
        auto current = precomputed[step];
        for (int i = 1; i <= K - 1; ++i) {
            current = cyclic_shift(current);
            precomputed[step + 1] = multiply_matrices(precomputed[step + 1], current);
        }
    }
}

vector<vector<int>> recursive_solve(ll n) {
    if (n == 0) {
        vector<vector<int>> result(K + 1, vector<int>(K + 1, 0));
        for (int i = 0; i <= K; ++i) {
            result[i][i] = 1;
        }
        return result;
    }
    ll digit = 0;
    ll power = 1;
    while (power <= n / K) {
        power *= K;
        digit++;
    }
    if (n == power) return precomputed[digit];
    ll steps = n / power;
    ll remainder = n - steps * power;
    auto base_matrix = recursive_solve(0);
    auto coefficient = precomputed[digit];
    for (int i = 0; i < steps; ++i) {
        base_matrix = multiply_matrices(base_matrix, coefficient);
        coefficient = cyclic_shift(coefficient);
    }
    auto other = recursive_solve(remainder);
    for (int i = 0; i < steps; ++i) {
        other = cyclic_shift(other);
    }
    return multiply_matrices(base_matrix, other);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> K;
    build_tables();
    auto result = recursive_solve(N);
    cout << result[K][K];
    return 0;
}

