import sys

MOD = 1000000007

def add(x, y):
    x += y
    return x - MOD if x >= MOD else x

def sub(x, y):
    x -= y
    return x + MOD if x < 0 else x

def mul(x, y):
    return (x * y) % MOD

def multiply(A, B, K):
    n = K + 1
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][k] = add(C[i][k], mul(A[i][j], B[j][k]))
    return C

def rotate(M, K):
    n = K + 1
    R = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            ni = i
            if ni < K:
                ni = (ni + K - 1) % K
            nj = j
            if nj < K:
                nj = (nj + K - 1) % K
            R[i][j] = M[ni][nj]
    return R

def preprocess(N, K):
    digits = 0
    x = N
    while x:
        x //= K
        digits += 1
    table = []
    table.append([[0] * (K + 1) for _ in range(K + 1)])

    for i in range(1, K):
        table[0][i][i] = 1
    table[0][0][K] = 1
    table[0][K][0] = MOD - 1
    table[0][K][K] = 2

    for step in range(digits):
        table.append([row[:] for row in table[step]])
        cur = table[step]
        for i in range(1, K):
            cur = rotate(cur, K)
            table[step + 1] = multiply(table[step + 1], cur, K)
    return table

def compute(n, K, table):
    if n == 0:
        I = [[0] * (K + 1) for _ in range(K + 1)]
        for i in range(K + 1):
            I[i][i] = 1
        return I

