    d = 0
    while p <= n // K:
        p *= K
        d += 1

    if n == p:
        return table[d]

    steps = n // p
    rem = n - steps * p
    res = compute(0, K, table)
    coef = table[d]
    for i in range(steps):
        res = multiply(res, coef, K)
        coef = rotate(coef, K)
    other = compute(rem, K, table)
    for i in range(steps):
        other = rotate(other, K)
    return multiply(res, other, K)

