    class Matrix:
        def __init__(self):
            self.t = [[0] * MAX for _ in range(MAX)]

        def id(self):
            for i in range(n):
                for j in range(n):
                    self.t[i][j] = 1 if i == j else 0

        def multiply(self, b, pom):
