using namespace std;

typedef long long ll;

const int K = 105, Mod = 1000000007;

ll n; int k;

struct Matrix {
	int a[K][K];
	Matrix() { memset(a, 0, sizeof(a)); }
	void Unit(int len) { for (int i = 1; i <= len; ++i) a[i][i] = 1; }
};

int id(int x, int step) {
	return x <= k ? ((x + step - 1) % k + 1) : x;
}

Matrix Move(const Matrix &Base, int step) {
	step %= k; Matrix res;
	for (int i = 1; i <= k + 1; ++i)
		for (int j = 1; j <= k + 1; ++j)
			res.a[id(i, step)][id(j, step)] = Base.a[i][j];
	return res;
}

Matrix multiply(const Matrix &lhs, const Matrix &rhs) {
	Matrix res;
	for (int i = 1; i <= k + 1; ++i)
		for (int kk = 1; kk <= k + 1; ++kk) if (lhs.a[i][kk])
			for (int j = 1; j <= k + 1; ++j)
				res.a[i][j] = (res.a[i][j] + 1ll * lhs.a[i][kk] * rhs.a[kk][j]) % Mod;
	return res;
}

Matrix A[K]; int ans[K];

