	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> n >> k;

	A[0].Unit(k + 1);
	for (int i = 1; i <= k + 1; ++i)
		A[0].a[1][i] = 1;

	vector<int> V;
	for (int len = 0; n; V.push_back(n % k), n /= k) {
		Matrix x = A[len]; A[++ len].Unit(k + 1);
		for (ll power = k, p = 0; power; power >>= 1) {
			if (power & 1) A[len] = multiply(A[len], Move(x, (power ^ 1) << p));
			x = multiply(Move(x, 1 << p), x); ++ p;
