                C[i][j] = add_mod(C[i][j], mul_mod(A[i][t], B[t][j]))
    return C

def solve_case(n_val, k_val):
    digits = []
    temp = n_val
    while temp > 0:
        digits.append(temp % k_val)
        temp //= k_val

    # Initialize base[0][d] for d in range(k_val)
    base = {}
    for d in range(k_val):
        base[0, d] = [[0] * (k_val + 1) for _ in range(k_val + 1)]
        for i in range(k_val + 1):
            base[0, d][i][i] = 1
        for i in range(k_val + 1):
            base[0, d][i][d] = 1

    # Build higher level bases
    for lvl in range(1, len(digits)):
        # Create prefix matrices
        prefix = []
        identity = [[1 if i == j else 0 for j in range(k_val + 1)] for i in range(k_val + 1)]
        prefix.append(identity)
        for i in range(k_val):
            prefix.append(mat_mult(prefix[-1], base[lvl - 1, i], k_val))

        for sh in range(k_val):
            base[lvl, sh] = [row[:] for row in prefix[0]]
            for i in range(k_val - sh):
                base[lvl, sh] = mat_mult(base[lvl, sh], base[lvl - 1, (i + sh) % k_val], k_val)
            base[lvl, sh] = mat_mult(base[lvl, sh], prefix[sh], k_val)

    # Initialize dp matrix
    dp = [[0] * (k_val + 1) for _ in range(k_val + 1)]
    dp[0][k_val] = 1

    rem = 0
    for i in range(len(digits) - 1, -1, -1):
        while digits[i] > 0:
            dp = mat_mult(dp, base.get((i, rem), [[0]*(k_val+1)]*(k_val+1)), k_val)
            rem = (rem + 1) % k_val
            digits[i] -= 1

    ans = 0
    for i in range(k_val + 1):
        ans = add_mod(ans, dp[0][i])
    print(ans)

if __name__ == "__main__":
    while True:
        n_val, k_val = read_input()
        if n_val is None:
            break
        solve_case(n_val, k_val)

