    x += y;
    return x >= MOD ? x - MOD : x;
}

long long multiply(long long x, long long y) {
    return (x * y) % MOD;
}

template<int R, int C>
struct Matrix {
    int entries[R][C];

    void clear() {
        memset(entries, 0, sizeof(entries));
    }

    void set_identity() {
        clear();
        for (int i = 0; i < min(R, C); ++i) entries[i][i] = 1;
    }

    template<int K>
    static Matrix<R, C> product(const Matrix<R, K>& a, const Matrix<K, C>& b) {
        Matrix<R, C> res;
        res.clear();
        for (int i = 0; i < R; ++i)
            for (int j = 0; j < K; ++j)
                if (a.entries[i][j])
                    for (int k = 0; k < C; ++k)
                        res.entries[i][k] = add(res.entries[i][k], (int)multiply(a.entries[i][j], b.entries[j][k]));
        return res;
    }

    Matrix<R, C> operator+(const Matrix<R, C>& other) const {
        Matrix<R, C> res;
        for (int i = 0; i < R; ++i)
            for (int j = 0; j < C; ++j)
                res.entries[i][j] = add(entries[i][j], other.entries[i][j]);
        return res;
    }

    Matrix<R, C> operator*(int scalar) const {
        Matrix<R, C> res = *this;
        for (int i = 0; i < R; ++i)
            for (int j = 0; j < C; ++j)
                res.entries[i][j] = (int)multiply(res.entries[i][j], scalar);
        return res;
    }

    int* operator[](int idx) { return entries[idx]; }
    const int* operator[](int idx) const { return entries[idx]; }
};

