import sys
from typing import List

def normalize(x: int, MOD: int) -> int:
    x %= MOD
    if x < 0:
        x += MOD
    return x

def fast_pow(base: int, exp: int, MOD: int) -> int:
    res = 1
    base = normalize(base, MOD)
    while exp:
        if exp & 1:
            res = (res * base) % MOD
        base = (base * base) % MOD
        exp >>= 1
    return res

def init_factorials(limit: int, MOD: int) -> tuple:
    FACT = [1] * (limit + 1)
    INV_FACT = [1] * (limit + 1)
    for i in range(1, limit + 1):
        FACT[i] = (FACT[i-1] * i) % MOD
    INV_FACT[limit] = fast_pow(FACT[limit], MOD - 2, MOD)
    for i in range(limit - 1, -1, -1):
        INV_FACT[i] = (INV_FACT[i+1] * (i+1)) % MOD
    return FACT, INV_FACT

def fwht(a: List[int], sign: int, MOD: int) -> None:
    n = len(a)
    len_ = 1
    while len_ < n:
        for i in range(0, n, len_ << 1):
