#include <iostream>
#include <cstdio>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

typedef long long LL;

void read_int(int &x) {
    char c;
    while ((c = getchar()) < '0' || c > '9');
    x = c - '0';
    while ((c = getchar()) >= '0' && c <= '9') x = x * 10 + c - '0';
}

LL mod_pow(LL base, int exp, int mod) {
    LL result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

LL perm(int n, int r, const vector<LL>& fact, const vector<LL>& inv_fact, int mod) {
    return fact[n] * inv_fact[n - r] % mod;
}

int main() {
    int n, k, mod;
    scanf("%d %d %d", &n, &k, &mod);

    if (n & 1) {
        cout << mod_pow(k, n, mod) << endl;
        return 0;
    }

    vector<LL> fact(n + 1), inv_fact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i-1] * i % mod;
    inv_fact[n] = mod_pow(fact[n], mod - 2, mod);
    for (int i = n - 1; i >= 0; --i) inv_fact[i] = inv_fact[i+1] * (i+1) % mod;

    vector<int> bits;
    int tmp = n;
    for (int i = 0; i <= 20; ++i) {
        if (tmp & 1) bits.push_back(1 << i);
        tmp >>= 1;
    }

    int N = 1 << bits.size();
    vector<int> S(N, 0);
    for (int mask = 0; mask < N; ++mask) {
        for (int j = 0; j < (int)bits.size(); ++j) {
            if (mask & (1 << j)) S[mask] += bits[j];
        }
    }

    vector<int> p(N);
    for (int mask = 0; mask < N; ++mask) {
        int last_bit = -1;
        for (int j = 0; j <= 20; ++j) {
            if (mask & (1 << j)) last_bit = j;
        }
        p[mask] = (1 << (last_bit + 1)) + mask;
    }

    vector<vector<LL>> dp(k + 1, vector<LL>(N, 0));
    dp[0][0] = 1;

    for (int i = 0; i < k; ++i) {
        for (int j = 0; j < N; ++j) {
            if (dp[i][j]) {
                for (int next = p[j]; next < N; next = (next + 1) | j) {
                    dp[i+1][next] = (dp[i+1][next] + dp[i][j] * inv_fact[S[next ^ j]]) % mod;
                }
            }
        }
    }

    LL answer = 0;
    for (int i = 0; i <= k; ++i) {
        answer = (answer + dp[i][N-1] * perm(k, i, fact, inv_fact, mod)) % mod;
    }
    answer = answer * fact[n] % mod;
    answer = (mod_pow(k, n, mod) - answer + mod) % mod;

    cout << answer << endl;
    return 0;
}

