#include <bits/stdc++.h>
using namespace std;

using i64 = long long;
using u64 = unsigned long long;
using u32 = unsigned int;
using ldouble = long double;
using vi = vector<int>;
using pii = pair<int, int>;

constexpr int MAX_SIZE = 300005;
int MOD = 1000000007;

inline void min_update(int& a, int b) { if (a > b) a = b; }
inline void max_update(int& a, int b) { if (a < b) a = b; }
inline void mod_inc(int& a, int b) { a = (a + b) % MOD; }

inline int fast_pow(int base, int exp, int mod_val) {
    int res = 1;
    base %= mod_val;
    while (exp > 0) {
        if (exp & 1) res = (i64)res * base % mod_val;
        base = (i64)base * base % mod_val;
        exp >>= 1;
    }
    return res;
}

int n_val, k_val;
int factorial[MAX_SIZE], inv_factorial[MAX_SIZE];
int dp_table[2][MAX_SIZE];

inline int comb_func(int total, int pick) {
    if (pick < 0 || pick > total) return 0;
    return (i64)factorial[total] * inv_factorial[total - pick] % MOD * inv_factorial[pick] % MOD;
}

int main() {
#ifdef rqgao2014
    freopen("input.txt", "r", stdin);
#endif
    scanf("%d %d %d", &n_val, &k_val, &MOD);

    factorial[0] = inv_factorial[0] = 1;
    for (int idx = 1; idx <= n_val; ++idx) {
        factorial[idx] = (i64)factorial[idx - 1] * idx % MOD;
    }

    inv_factorial[n_val] = fast_pow(factorial[n_val], MOD - 2, MOD);
    for (int idx = n_val - 1; idx >= 1; --idx) {
        inv_factorial[idx] = (i64)inv_factorial[idx + 1] * (idx + 1) % MOD;
    }

    if (n_val & 1) {
        printf("%d\n", fast_pow(k_val, n_val, MOD));
        return 0;
    }

    int final_ans = 0;
    dp_table[0][n_val] = 1;

    for (int round = 1; round <= k_val; ++round) {
        fill(dp_table[round & 1], dp_table[round & 1] + n_val + 1, 0);
        int local_sum = 0;

        for (int j = 1; j <= n_val; ++j) {
            int prev_val = dp_table[(round - 1) & 1][j];
            if (!prev_val) continue;

            int low_bit = j & -j;
            int cleared_val = j ^ low_bit;

            for (int sub = cleared_val; sub; sub = (sub - 1) & cleared_val) {
                mod_inc(dp_table[round & 1][sub], (i64)prev_val * comb_func(j, sub) % MOD);
            }
            mod_inc(local_sum, prev_val);
        }

        mod_inc(final_ans, (i64)local_sum * inv_factorial[k_val - round] % MOD);
    }

    final_ans = (i64)final_ans * factorial[k_val] % MOD;
    final_ans = (fast_pow(k_val, n_val, MOD) - final_ans + MOD) % MOD;
    printf("%d\n", final_ans);

