    int res = 1;
    base %= mod_val;
    while (exp) {
        if (exp & 1) res = (ll)res * base % mod_val;
        base = (ll)base * base % mod_val;
        exp >>= 1;
    }
    return res;
}

int N, K;
int fact[MAX_N], inv_fact[MAX_N];
int dp[2][MAX_N];

inline int binomial(int n, int r) {
    if (r < 0 || r > n) return 0;
    return (ll)fact[n] * inv_fact[n - r] % MOD * inv_fact[r] % MOD;
}

int main() {
