def pi(k, ch=0):
    if k < 0:
        k = -k
        sys.stdout.write('-')
    if k >= 10:
        pi(k // 10)
    sys.stdout.write(chr(k % 10 + 48))
    if ch:
        sys.stdout.write(chr(ch))

def fpow(a, b, c=1):
    P = globals()['P']
    while b:
        if b & 1:
            c = c * a % P
        a = a * a % P
        b >>= 1
    return c

def init(n):
    fac = globals()['fac']
    ifac = globals()['ifac']
    inv = globals()['inv']
    P = globals()['P']

    fac[0] = 1
    for i in range(1, n + 1):
        fac[i] = fac[i - 1] * i % P

    ifac[n] = fpow(fac[n], P - 2)
    for i in range(n - 1, -1, -1):
        ifac[i] = ifac[i + 1] * (i + 1) % P

    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = (P - P // i) * inv[P % i] % P

def add(x, y):
    x[0] = (x[0] + y)
    if x[0] >= globals()['P']:
        x[0] -= globals()['P']

