    P = globals()['P']
    for l in range(1, n):
        if l >= n:
            break
        for i in range(0, n, l << 1):
            for j in range(l):
                add(f[i + j + l], f[i + j])

def IFMT(f, n):
    P = globals()['P']
    for l in range(1, n):
        if l >= n:
            break
        for i in range(0, n, l << 1):
            for j in range(l):
                sub(f[i + j + l], f[i + j])

