    P = globals()['P']
    inv = globals()['inv']
    g[0] = 0
    for i in range(1, n):
        g[i] = 0
        for j in range(1, i):
            g[i] = (g[i] + f[i - j] * g[j] % P * j) % P
        g[i] = (f[i] + g[i] * (P - inv[i])) % P

