#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pii = pair<int, int>;
using pll = pair<ll, ll>;

const int MAX_LG = 18;
const int TW = 1 << MAX_LG;
const int MAX_SIZE = TW + 10;

int MOD = 1e9 + 7;
int N, original_n;
int ans_table[MAX_SIZE][MAX_LG + 3];
int temp_poly[MAX_LG + 3];
int temp2_poly[MAX_LG + 3];
int factorial[MAX_SIZE];
int inv_factorial[MAX_SIZE];

int mod_pow(int base, int exp) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = (1LL * result * base) % MOD;
        base = (1LL * base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

void poly_add(int *dest, const int *src) {
    for (int i = 0; i <= N; ++i) {
        dest[i] = (dest[i] + src[i]) % MOD;
        if (dest[i] < 0) dest[i] += MOD;
    }
}

void poly_subtract(int *dest, const int *src) {
    for (int i = 0; i <= N; ++i) {
        dest[i] = (dest[i] - src[i]) % MOD;
        if (dest[i] < 0) dest[i] += MOD;
    }
}

void poly_multiply(int *dest, const int *a, const int *b) {
    memset(temp_poly, 0, sizeof(temp_poly));
    for (int i = 0; i <= N; ++i) {
        for (int j = 0; j <= i; ++j) {
            temp_poly[i] = (temp_poly[i] + 1LL * a[j] * b[i - j]) % MOD;
        }
    }
    memcpy(dest, temp_poly, sizeof(temp_poly));
}

void forward_transform(int table[][MAX_LG + 3]) {
    for (int bit_pos = 0; bit_pos < N; ++bit_pos) {
        for (int mask = original_n; mask >= 0; --mask) {
            if (mask & (1 << bit_pos)) {
                poly_add(table[mask], table[mask ^ (1 << bit_pos)]);
            }
        }
    }
}

void backward_transform(int table[][MAX_LG + 3]) {
    for (int bit_pos = 0; bit_pos < N; ++bit_pos) {
        for (int mask = original_n; mask >= 0; --mask) {
            if (mask & (1 << bit_pos)) {
                poly_subtract(table[mask], table[mask ^ (1 << bit_pos)]);
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int K;
    cin >> original_n >> K >> MOD;

    int total = mod_pow(K, original_n);
    if (original_n & 1) {
        cout << total << '\n';
        return 0;
    }

    N = __builtin_popcount(original_n);
    vector<int> bit_positions;
    for (int i = 0; i < MAX_LG; ++i) {
        if (original_n & (1 << i)) {
            bit_positions.push_back(i);
        }
    }

    int compressed_n = (1 << N) - 1;

    factorial[0] = 1;
    for (int i = 1; i < MAX_SIZE; ++i) {
        factorial[i] = (1LL * i * factorial[i - 1]) % MOD;
    }

    inv_factorial[MAX_SIZE - 1] = mod_pow(factorial[MAX_SIZE - 1], MOD - 2);
    for (int i = MAX_SIZE - 2; i >= 0; --i) {
        inv_factorial[i] = (1LL * (i + 1) * inv_factorial[i + 1]) % MOD;
    }

    for (int mask = 0; mask <= compressed_n; ++mask) {
        int real_value = 0;
        for (int j = 0; j < N; ++j) {
            if (mask & (1 << j)) {
                real_value += 1 << bit_positions[j];
            }
        }
        ans_table[mask][__builtin_popcount(mask)] = inv_factorial[real_value];
    }

    forward_transform(ans_table);

    for (int mask = 0; mask <= compressed_n; ++mask) {
        int current_K = K;
        memset(temp2_poly, 0, sizeof(temp2_poly));
        temp2_poly[0] = 1;

        while (current_K) {
            if (current_K & 1) {
                poly_multiply(temp2_poly, temp2_poly, ans_table[mask]);
            }
            poly_multiply(ans_table[mask], ans_table[mask], ans_table[mask]);
            current_K >>= 1;
        }
        memcpy(ans_table[mask], temp2_poly, sizeof(temp2_poly));
    }

    backward_transform(ans_table);

    int result = (1LL * total - 1LL * ans_table[compressed_n][N] * factorial[original_n]) % MOD;
    if (result < 0) result += MOD;

    cout << result << '\n';
    return 0;
}

