import sys
import math

def input():
    return sys.stdin.readline().rstrip()

def geti():
    xi = 0
    ch = sys.stdin.read(1)
    f = False
    while not ch.isdigit():
        if ch == '-':
            f = True
        ch = sys.stdin.read(1)
    while ch.isdigit():
        xi = xi * 10 + ord(ch) - 48
        ch = sys.stdin.read(1)
    return -xi if f else xi

def pi(k, ch=0):
    if k < 0:
        k = -k
        sys.stdout.write('-')
    if k >= 10:
        pi(k // 10)
    sys.stdout.write(chr(k % 10 + 48))
    if ch:
        sys.stdout.write(chr(ch))

def fpow(a, b, c=1):
    P = globals()['P']
    while b:
        if b & 1:
            c = c * a % P
        a = a * a % P
        b >>= 1
    return c

def init(n):
    fac = globals()['fac']
    ifac = globals()['ifac']
    inv = globals()['inv']
    P = globals()['P']
    fac[0] = 1
    for i in range(1, n + 1):
        fac[i] = fac[i - 1] * i % P
    ifac[n] = fpow(fac[n], P - 2)
    for i in range(n - 1, -1, -1):
        ifac[i] = ifac[i + 1] * (i + 1) % P
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = (P - P // i) * inv[P % i] % P

def add(x, y):
    P = globals()['P']
    x[0] += y
    if x[0] >= P:
        x[0] -= P

def sub(x, y):
    P = globals()['P']
    x[0] -= y
    x[0] -= (x[0] >> 31) * P

def sub_val(x):
    P = globals()['P']
    return x - (x >> 31) * P

def fpow_arr(f, n, k):
    P = globals()['P']
    t = f[:]
    g = [0] * n
    f[0] = 1 - f[0]
    g[0] = 0
    inv = globals()['inv']
    for i in range(1, n):
        f[i] = g[i] = 0
        for j in range(1, i):
            f[i] = (f[i] + f[i - j] * g[j]) % P
            g[i] = (g[i] + t[i - j] * g[j]) % P
        f[i] = sub_val(f[i] - g[i])
        f[i] = (t[i] + f[i] * inv[i]) % P * k % P
        g[i] = (t[i] - g[i] * inv[i]) % P * i % P

def FMT(f, n):
    P = globals()['P']
    l = 1
    while l < n:
        for i in range(0, n, l << 1):
            for j in range(l):
                add([f[i + j + l]], f[i + j])
        l <<= 1

def IFMT(f, n):
    P = globals()['P']
    l = 1
    while l < n:
        for i in range(0, n, l << 1):
            for j in range(l):
                sub([f[i + j + l]], f[i + j])
        l <<= 1

def popcount(x):
    return bin(x).count('1')

def main():
    global P, fac, ifac, inv
    n = geti()
    k = geti()
    P = geti()

    ans = fpow(k, n)

    if n & 1 == 0:
        m = int(math.log2(n)) + 1
        size = 1 << m
        fac = [0] * (size + 1)
        ifac = [0] * (size + 1)
        inv = [0] * (size + 1)
        init(size)

        f = [[0] * size for _ in range(20)]
        for i in range(size):
            f[popcount(i)][i] = ifac[i]

        for i in range(m + 1):
            FMT(f[i], size)

        F = [0] * 20
        for i in range(n + 1):
            for j in range(m + 1):
                F[j] = f[j][i]
            fpow_arr(F, m + 1, k)
            for j in range(m + 1):
                f[j][i] = F[j]

        IFMT(f[popcount(n)], size)
        ans = (P + ans - f[popcount(n)][n] * fac[n] % P) % P

    pi(ans)

if __name__ == '__main__':
    main()

