import sys
import threading

def main():
    sys.setrecursionlimit(1 << 25)

    # Fast I/O
    input = sys.stdin.buffer.readline
    output = sys.stdout.buffer

    def read_ints():
        return list(map(int, input().split()))

    def read_int():
        return int(input().strip())

    # Read M first to set up modular arithmetic
    data = read_ints()
    n, k, M = data[0], data[1], data[2]

    # Modular arithmetic functions
    def add(x, y):
        return x + y if x + y < M else x + y - M

    def sub(x, y):
        return x - y if x - y >= 0 else x - y + M

    def mul(x, y):
        return (x * y) % M

    def power(x, y):
        res = 1
        x %= M
        while y:
            if y & 1:
                res = mul(res, x)
            x = mul(x, x)
            y >>= 1
        return res

    def inv(x):
        return power(x, M - 2)

    # Precompute factorials and inverse factorials
    N = n + 1
    fac = [1] * N
    ifac = [1] * N

    for i in range(1, N):
        fac[i] = mul(fac[i-1], i)

    ifac[n] = inv(fac[n])
    for i in range(n-1, -1, -1):
        ifac[i] = mul(ifac[i+1], i+1)

    # DP memoization
    f = [[-1] * k for _ in range(n+1)]

    def dp(s, c):
        if s == 0:
            return 1
        if c == k:
            return 0
        if f[s][c] != -1:
            return f[s][c]

        res = 0
        # Find highest bit
        hb = 1
        while hb <= s:
            hb <<= 1
        hb >>= 1

        t = s
        while t != -1:
            t &= s
            if not (t & hb):
                f[s][c] = res
                return res
            # Compute term: ifac[t] * (k - c) * dp(s ^ t, c + 1)
            term = mul(ifac[t], k - c)
            term = mul(term, dp(s ^ t, c + 1))
            res = add(res, term)
            t = (t - 1) & s

        f[s][c] = res
        return res

    # Main logic
    if n & 1:
        result = power(k, n)
        print(result)
    else:
        dp_result = dp(n, 0)
        term = mul(fac[n], dp_result)
        result = sub(power(k, n), term)
        print(result)

# Run main in a separate thread to avoid stack overflow issues
threading.Thread(target=main).start()

