import sys

def fpow(a, b, p):
    ans = 1
    t = a % p
    while b:
        if b & 1:
            ans = (ans * t) % p
        t = (t * t) % p
        b >>= 1
    return ans

def lowbit(x):
    return x & (-x)

def init(fac, inv, n, p):
    fac[0] = 1
    for i in range(1, n + 1):
        fac[i] = (fac[i - 1] * i) % p
    inv[n] = fpow(fac[n], p - 2, p)
    for i in range(n, 0, -1):
        inv[i - 1] = (inv[i] * i) % p

def solve(cur, S, f, n, k, p, fac, inv):
    if f[cur][S] != -1:
        return f[cur][S]
    if S == 0:
        f[cur][S] = fac[n]
        for i in range(1, cur + 1):
            f[cur][S] = (f[cur][S] * (k - i + 1)) % p
        return f[cur][S]
    f[cur][S] = 0
    U = S - lowbit(S)
    T = U
    while T:
        f[cur][S] = (f[cur][S] + (inv[S - T] * solve(cur + 1, T, f, n, k, p, fac, inv)) % p) % p
        T = (T - 1) & U
    f[cur][S] = (f[cur][S] + (inv[S] * solve(cur + 1, 0, f, n, k, p, fac, inv)) % p) % p
    return f[cur][S]

def main():
    data = sys.stdin.readline().split()
    n = int(data[0])
    k = int(data[1])
    p = int(data[2])

    ans = 1
    for i in range(1, n + 1):
        ans = (ans * k) % p

    if n % 2 == 0:
        # Initialize arrays
        max_n = n
        max_S = 250005
        fac = [0] * (max_n + 1)
        inv = [0] * (max_n + 1)
        f = [[-1] * max_S for _ in range(30)]

        init(fac, inv, n, p)
        ans = (ans - solve(0, n, f, n, k, p, fac, inv) + p) % p

    print(ans)

if __name__ == "__main__":
    main()

