#include<iostream>
#include<cstdio>
#include<cmath>
#include<cstring>
#include<algorithm>
using namespace std;
int n,k,mod;
int fac[250003],inv[250003];
int dp[27][250003];
int lowbit(int x){return x&(-x);}
int fpow(int x,int y)
{
	int res=1;
	while(y)
	{
		if(y&1) res=1ll*res*x%mod;
		x=1ll*x*x%mod;
		y>>=1;
	}
	return res;
}
void init()
{
	fac[0]=1;
	for(int i=1;i<=n;i++)
		fac[i]=1ll*fac[i-1]*i%mod;
	inv[n]=fpow(fac[n],mod-2);
	for(int i=n-1;i>=0;i--)
		inv[i]=1ll*inv[i+1]*(i+1)%mod;
}
int dfs(int x,int s)
{
	if(dp[x][s]!=-1) return dp[x][s];
	if(s==0) return dp[x][s]=1ll*fac[n]*fac[k]%mod*inv[k-x]%mod;
	int now=s-lowbit(s);
	dp[x][s]=0;
	for(int t=now;t;t=(t-1)&now)
		dp[x][s]=(dp[x][s]+1ll*dfs(x+1,t)*inv[s-t]%mod)%mod;
	dp[x][s]=(dp[x][s]+1ll*dfs(x+1,0)*inv[s]%mod)%mod;
	return dp[x][s];
}
int main()
{
	scanf("%d%d%d",&n,&k,&mod);
	init();
	int ans=fpow(k,n);
	if(n%2==0) 
	{
		memset(dp,-1,sizeof(dp));
		ans=(ans-dfs(0,n)+mod)%mod;
	}
	printf("%d",ans);
	return 0;
}

