long long com(int n, int m) {
    return fac[n] * inv[n - m] % mod * inv[m] % mod;
}

void add(long long &x, long long y) {
    x += y;
    if (x >= mod) x %= mod;
}

int main()
{
    cin >> n >> m >> mod;   
    inv[0] = fac[0] = inv[1] = fac[1] = 1;
    for (int i = 2; i <= n; i++) {
        int r = mod / i;
        int x = mod - i * r;
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = mod -1LL * r * inv[x] % mod;
    }
    for (int i = 2; i <= n; i++) inv[i] = inv[i - 1] * inv[i] % mod;
    long long ans = 1;
    for (int i = 1; i <= n; i++) ans = ans * m % mod;
    for (int i = 1; i <= n; i++) bit[i] = bit[i >> 1] + (i & 1);
    if (n & 1) {
        cout << ans << endl;
        return 0;
    }
    dp[0][0] = 1;
    for (int i = 0; i < min(0LL + bit[n], m); i++) {
        for (int j = 0; j < n; j++) {
            if (!dp[i][j]) continue;
            int x = n ^ j;
            for (int k = x, r; k > j; k = (k - 1) & x) {
                r = k | j;
                add(dp[i + 1][r], dp[i][j] * inv[k]); 
            }
        }
    }
    for (int i = 1; i <= m; i++) 
        ans -= dp[i][n] * fac[m] % mod * inv[m - i] % mod * fac[n] % mod;
    ans = (mod + ans % mod) % mod;
    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAX_N = 250010;
long long factorial[MAX_N], inverse[MAX_N];
long long dp[30][MAX_N];
int popcountArr[MAX_N];
long long n, m, modulus;

long long binomial(int n, int m) {
    return factorial[n] * inverse[n - m] % modulus * inverse[m] % modulus;
}

void accumulateMod(long long &x, long long y) {
    x = (x + y) % modulus;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m >> modulus;

    factorial[0] = inverse[0] = inverse[1] = factorial[1] = 1;
    for (int i = 2; i <= n; i++) {
        int r = modulus / i;
        int x = modulus - i * r;
        factorial[i] = factorial[i - 1] * i % modulus;
        inverse[i] = modulus - (1LL * r * inverse[x]) % modulus;
    }

    for (int i = 2; i <= n; i++) {
        inverse[i] = inverse[i - 1] * inverse[i] % modulus;
    }

    long long result = 1;
    for (int i = 1; i <= n; i++) {
        result = result * m % modulus;
    }

    for (int i = 1; i <= n; i++) {
        popcountArr[i] = popcountArr[i >> 1] + (i & 1);
    }

    if (n & 1) {
        cout << result << '\n';
        return 0;
    }

    dp[0][0] = 1;
    int maxBit = min<int>(popcountArr[n], m);

    for (int i = 0; i < maxBit; i++) {
        for (int j = 0; j <= n; j++) {
            if (!dp[i][j]) continue;
            int complement = n ^ j;
            for (int k = complement; k > j; k = (k - 1) & complement) {
                int combined = k | j;
                accumulateMod(dp[i + 1][combined], dp[i][j] * inverse[k] % modulus);
            }
        }
    }

    for (int i = 1; i <= m; i++) {
        long long term = dp[i][n] * factorial[m] % modulus;
        term = term * inverse[m - i] % modulus;
        term = term * factorial[n] % modulus;
        result = (result - term % modulus + modulus) % modulus;
    }

    cout << result << '\n';
    return 0;
}

