long long mod_pow(long long b, int e, int m) {
    long long r = 1;
    while (e) {
        if (e & 1) r = (r * b) % m;
        b = (b * b) % m;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
