        if ((i & n) != i) continue;
        int pb = msb[i];
        int rem = i ^ pb;
        for (int k = rem; ; k = (k - 1) & rem) {
            int a = k + pb, b = i ^ a;
            int lim = min(K - 1, bitcnt[b]);
            long long comb = C(i, a);
            for (int j = 0; j <= lim; j++) {
                dp[i][j + 1] = (dp[i][j + 1] + dp[b][j] * comb) % mod;
            }
            if (!k) break;
        }
    }

    long long ans = 0;
    int top = min(bitcnt[n], K);
    for (int j = 1; j <= top; j++) {
