    cin >> MOD;
    precompute();
    dp2[0][0] = {ModInt(1), ModInt(0)};
    for (int i = 0; i < n; ++i) {
        for (int k = 0; k <= i; ++k) {
            for (int j = i; j < n; ++j) {
