}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);

    int n, m, MOD;
    while (cin >> n >> m >> MOD) {

        auto add_mod = [&](lint& x, lint y) {
            x = norm(x + y, MOD);
        };

        vector<vector<lint>> C(m+1, vector<lint>(m+1, 0));
        for (int i = 0; i <= m; ++i) {
            C[i][0] = 1 % MOD;
            for (int j = 1; j <= i; ++j) {
                C[i][j] = norm(C[i-1][j-1] + C[i-1][j], MOD);
            }
        }

        vector<lint> dpW(m+1, 0), dpS(m+1, 0), prefix_n(m+1, 0);
        for (int i = 1; i <= m; ++i) prefix_n[i] = (lint)i * (i+1) / 2 % MOD;

        dpW[0] = 1 % MOD;
        for (int len = 1; len <= m; ++len) {
            for (int pos = 0; pos < len; ++pos) {
                int left = pos, right = len - 1 - pos;
                lint baseW = dpW[left] * dpW[right] % MOD;
                lint coeff = (len + 1LL) * C[len-1][pos] % MOD;
                add_mod(dpW[len], coeff * baseW);

                lint tmpS = (dpS[left] * dpW[right] + dpS[right] * dpW[left]) % MOD;
                add_mod(dpS[len], (coeff * tmpS) % MOD);
                add_mod(dpS[len], baseW * C[len-1][pos] % MOD * (prefix_n[left] + prefix_n[right]) % MOD);
            }
        }

        vector<vector<lint>> dpW2(n+1, vector<lint>(m+1, 0));
        vector<vector<lint>> dpS2(n+1, vector<lint>(m+1, 0));
        dpW2[0][0] = 1 % MOD;

