    f[0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < i; ++j) {
            inc(f[i], 1LL * f[j] * f[i - 1 - j] % mod * C(i - 1, j) % mod);
        }
        f[i] = 1LL * f[i] * (i + 1) % mod;
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < i; ++j) {
            int term1 = 2LL * f[j] * g[i - 1 - j] % mod * C(i - 1, j) % mod * (i + 1) % mod;
            int term2 = 1LL * C(i - 1, j) * (tri(j) + tri(i - 1 - j)) % mod * f[j] % mod * f[i - 1 - j] % mod;
            inc(g[i], (term1 + term2) % mod);
        }
    }

    f[0] = 0;
    for (int i = 0; i <= n; ++i) {
        f[i] = 1LL * f[i] * ifac[i] % mod;
        g[i] = 1LL * g[i] * ifac[i] % mod;
    }

    int ans = 0;
