    for (int i = n; i > 0; i--) invfact[i-1] = mul(invfact[i], i);
}

int comb(int n, int k) {
    if (k < 0 || k > n || n < 0) return 0;
    return mul(mul(fact[n], invfact[k]), invfact[n-k]);
}

int triangle(int x) {
    return x * (x + 1) / 2;
}

