#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int MOD;

inline int normalize(int x) {
    return (x % MOD + MOD) % MOD;
}

inline void increment(int& x, int y) {
    x = normalize(x + y);
}

int mod_exp(int base, int exp) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = (1LL * result * base) % MOD;
        base = (1LL * base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

vector<int> factorial, inv_factorial;

void precompute(int size) {
    factorial.resize(size + 1);
    inv_factorial.resize(size + 1);
    factorial[0] = 1;
    for (int i = 1; i <= size; ++i) {
        factorial[i] = (1LL * factorial[i - 1] * i) % MOD;
    }
    inv_factorial[size] = mod_exp(factorial[size], MOD - 2);
    for (int i = size; i >= 1; --i) {
        inv_factorial[i - 1] = (1LL * inv_factorial[i] * i) % MOD;
    }
}

int binomial(int n, int k) {
    if (k < 0 || k > n || n < 0) return 0;
    return (1LL * factorial[n] * inv_factorial[k] % MOD) * inv_factorial[n - k] % MOD;
}

int triangular_number(int x) {
    return x * (x + 1) / 2;
}

int G_func(int n, int m) {
    return binomial(m + n - 1, n - 1);
}

int main() {
#ifdef LOCAL
    freopen("1439D.in", "r", stdin);
    freopen("1439D.out", "w", stdout);
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int m, n;
    cin >> m >> n >> MOD;

    precompute(2 * m);

    vector<int> f(n + 1, 0), g(n + 1, 0);
    f[0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < i; ++j) {
            int add_val = (1LL * f[j] * f[i - 1 - j]) % MOD;
            add_val = (1LL * add_val * binomial(i - 1, j)) % MOD;
            f[i] = (f[i] + add_val) % MOD;
        }
        f[i] = (1LL * f[i] * (i + 1)) % MOD;
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < i; ++j) {
            int part1 = (2LL * f[j] * g[i - 1 - j]) % MOD;
            part1 = (1LL * part1 * binomial(i - 1, j)) % MOD;
            part1 = (1LL * part1 * (i + 1)) % MOD;

            int part2 = (1LL * binomial(i - 1, j) * (triangular_number(j) + triangular_number(i - 1 - j))) % MOD;
            part2 = (1LL * part2 * f[j]) % MOD;
            part2 = (1LL * part2 * f[i - 1 - j]) % MOD;

            g[i] = (g[i] + part1 + part2) % MOD;
        }
    }

    f[0] = 0;
    for (int i = 0; i <= n; ++i) {
        f[i] = (1LL * f[i] * inv_factorial[i]) % MOD;
        g[i] = (1LL * g[i] * inv_factorial[i]) % MOD;
