typedef long long ll;

int MOD;

int mod_add(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    if (a < 0) a += MOD;
    return a;
}

int mod_mul(int a, int b) {
    return (int)((ll)a * b % MOD);
}

int mod_pow(int b, int e) {
    int r = 1;
    while (e) {
        if (e & 1) r = mod_mul(r, b);
        b = mod_mul(b, b);
        e >>= 1;
    }
    return r;
}

vector<int> fact, inv_fact;

void prepare(int n) {
    fact.resize(n + 1);
    inv_fact.resize(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = mod_mul(fact[i-1], i);
    inv_fact[n] = mod_pow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i) inv_fact[i-1] = mod_mul(inv_fact[i], i);
}

int nCr(int n, int r) {
    if (r < 0 || r > n || n < 0) return 0;
    return mod_mul(fact[n], mod_mul(inv_fact[r], inv_fact[n - r]));
}

int tri(int x) {
    return x * (x + 1) / 2;
}

int G(int n, int m) {
    return nCr(m + n - 1, n - 1);
}

