        int sum = 0;
        for (int j = 0; j < i; ++j) {
            int term = mod_mul(f[j], f[i - 1 - j]);
            term = mod_mul(term, nCr(i - 1, j));
            sum = mod_add(sum, term);
        }
        f[i] = mod_mul(sum, i + 1);
    }

