            int t2 = nCr(i - 1, j) * (tri(j) + tri(i - 1 - j)) % MOD;
            t2 = t2 * f[j] % MOD * f[i - 1 - j] % MOD;

            sum = mod_add(sum, (t1 + t2) % MOD);
        }
        g[i] = sum;
    }

    f[0] = 0;
    for (int i = 0; i <= n; ++i) {
