    inv_fact[n] = power(fact[n], M - 2);
    for (int i = n; i > 0; --i) inv_fact[i-1] = (i64)inv_fact[i] * i % M;
}

int comb(int n, int k) {
    if (k < 0 || k > n || n < 0) return 0;
    return (i64)fact[n] * inv_fact[k] % M * inv_fact[n - k] % M;
}

int T(int x) { return x * (x + 1) / 2; }

int G(int n, int m) { return comb(m + n - 1, n - 1); }

