    // Precompute binomial coefficients
    for (int i = 0; i <= nodes; i++) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % MOD;
        }
    }

    // Calculate f_a and g_a arrays
    f_a[0] = 1;
    for (int i = 1; i <= nodes; i++) {
        for (int j = 1; j <= i; j++) {
            ll temp = (ll)f_a[j-1] * f_a[i-j] % MOD;
            temp = temp * comb[i-1][j-1] % MOD;
            f_a[i] = (f_a[i] + temp) % MOD;

            ll cross = ((ll)f_a[j-1] * g_a[i-j] + (ll)g_a[j-1] * f_a[i-j]) % MOD;
            cross = cross * (i + 1) % MOD;

            ll base = (ll)f_a[j-1] * f_a[i-j] % MOD;
            base = base * ((ll)comb[j][2] + comb[i-j+1][2]) % MOD;
            ll combined = (base + cross) % MOD;
            combined = combined * comb[i-1][j-1] % MOD;

            g_a[i] = (g_a[i] + combined) % MOD;
        }
        f_a[i] = (ll)(i + 1) * f_a[i] % MOD;
    }

    // DP setup
    f_b[0][0] = 1;

    for (int i = 1; i <= nodes; i++) {
        int max_j = min(i, limit);
        for (int j = 0; j <= max_j; j++) {
            f_b[i][j] = f_b[i-1][j];
            g_b[i][j] = g_b[i-1][j];

            for (int k = 1; k <= j; k++) {
                int val_f = (i != k) ? f_b[i-k-1][j-k] : 1;
                int val_g = (i != k) ? g_b[i-k-1][j-k] : 0;

                ll add_f = (ll)val_f * f_a[k] % MOD;
                add_f = add_f * comb[j][k] % MOD;
                f_b[i][j] = (f_b[i][j] + add_f) % MOD;

                ll add_g = ((ll)val_f * g_a[k] + (ll)val_g * f_a[k]) % MOD;
                add_g = add_g * comb[j][k] % MOD;
                g_b[i][j] = (g_b[i][j] + add_g) % MOD;
            }
        }
    }

    printf("%d\n", g_b[nodes][limit]);
    return 0;
}

