int main() {
    int n, m, P;
    scanf("%d %d %d", &n, &m, &P);

    const int N = 510;
    int C[N][N], f1[N], g1[N], f2[N][N], g2[N][N];

    memset(C, 0, sizeof(C));
    memset(f1, 0, sizeof(f1));
    memset(g1, 0, sizeof(g1));
    memset(f2, 0, sizeof(f2));
    memset(g2, 0, sizeof(g2));

    // Binomial coefficients with 1-based indexing
    for (int i = 0; i <= n; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % P;
    }

    // Base cases and recursion for f1/g1
    f1[0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            // f1 recurrence
            long long term = 1LL * f1[j-1] * f1[i-j] % P;
            term = term * C[i-1][j-1] % P;
            f1[i] = (f1[i] + term) % P;

            // Cross term for g1
            long long cross = (1LL * f1[j-1] * g1[i-j] + 1LL * g1[j-1] * f1[i-j]) % P;
            cross = cross * (i + 1) % P;

            // Base term for g1
            long long base = 1LL * f1[j-1] * f1[i-j] % P;
            base = base * ((1LL * C[j][2] + C[i-j+1][2]) % P) % P;

            long long add = (base + cross) % P;
            add = add * C[i-1][j-1] % P;
            g1[i] = (g1[i] + add) % P;
        }
        f1[i] = 1LL * (i + 1) * f1[i] % P;
    }

    // DP base
    f2[0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= min(i, m); ++j) {
            f2[i][j] = f2[i-1][j];
            g2[i][j] = g2[i-1][j];

            for (int k = 1; k <= j; ++k) {
                // Handle the conditional case
                int pf = (i != k) ? f2[i-k-1][j-k] : 1;
                int pg = (i != k) ? g2[i-k-1][j-k] : 0;

                long long f_term = 1LL * pf * f1[k] % P * C[j][k] % P;
                f2[i][j] = (f2[i][j] + f_term) % P;

                long long g_term = (1LL * pf * g1[k] + 1LL * pg * f1[k]) % P;
                g_term = g_term * C[j][k] % P;
                g2[i][j] = (g2[i][j] + g_term) % P;
            }
        }
    }

    printf("%d\n", g2[n][m]);
    return 0;
}

