const int MAX = 511;
int binom[MAX][MAX];
int cnt[MAX];
int dp1[MAX];
int dp2[MAX][MAX];
int dp3[MAX][MAX];

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  cin >> n >> m >> P;

  // Precompute binomial coefficients
  FOR(i, 0, n) {
    FOR(j, 0, i) {
      if (j == 0 || j == i) {
        binom[i][j] = 1;
      } else {
        binom[i][j] = binom[i-1][j-1] + binom[i-1][j];
        if (binom[i][j] >= P) binom[i][j] -= P;
      }
    }
  }

  // Initialize dp1 and cnt
  dp1[0] = 0;
  cnt[0] = 1;

  FOR(i, 1, m) {
    FOR(j, 0, i-1) {
      int term = 0;
      add_mod(term, mul_mod(dp1[j], cnt[i-j-1]));
      add_mod(term, mul_mod(dp1[i-j-1], cnt[j]));
      mulself_mod(term, j + 1);
      add_mod(term, mul_mod(mul_mod(cnt[i-j-1], cnt[j]), (1LL * j * (j + 1) / 2) % P));
      mulself_mod(term, binom[i-1][j]);
      add_mod(dp1[i], term);

      int cnt_term = binom[i-1][j];
      mulself_mod(cnt_term, cnt[j]);
      mulself_mod(cnt_term, cnt[i-j-1]);
      mulself_mod(cnt_term, j + 1);
      add_mod(cnt[i], cnt_term);
    }
    add_mod(cnt[i], cnt[i]);
    add_mod(dp1[i], dp1[i]);
  }

  // DP for dp2 and dp3
  dp2[0][0] = 1;
  dp3[0][0] = 0;

  FOR(i, 0, n) {
    FOR(j, 0, m) {
      FOR(k, 0, m) {
        if (j + k > m || i + k + 1 > n + 1) continue;

        int val2 = dp2[i][j];
        mulself_mod(val2, binom[m - j][k]);
        mulself_mod(val2, cnt[k]);

        int val3 = dp3[i][j];
        mulself_mod(val3, cnt[k]);
        add_mod(val3, mul_mod(dp1[k], dp2[i][j]));
        mulself_mod(val3, binom[m - j][k]);

        add_mod(dp2[i + k + 1][j + k], val2);
        add_mod(dp3[i + k + 1][j + k], val3);
      }
    }
  }

  cout << dp3[n + 1][m] << "\n";
  return 0;
}

