    m = int(input_data[1])
    mod = int(input_data[2])

    # Create a new StaticModint class for the specific modulus
    class ModInt:
        def __init__(self, v=0):
            self._v = v % mod
            if self._v < 0:
                self._v += mod

        def val(self):
            return self._v

        def __iadd__(self, other):
            self._v += other._v
            if self._v >= mod:
                self._v -= mod
            return self

        def __isub__(self, other):
            self._v -= other._v
            if self._v >= mod:
                self._v += mod
            return self

        def __imul__(self, other):
            self._v = (self._v * other._v) % mod
            return self

        def __add__(self, other):
            res = ModInt()
            res._v = (self._v + other._v) % mod
            return res

        def __sub__(self, other):
            res = ModInt()
            res._v = (self._v - other._v) % mod
            if res._v < 0:
                res._v += mod
            return res

        def __mul__(self, other):
            res = ModInt()
            res._v = (self._v * other._v) % mod
            return res

