            s -= t * u
            m0 -= m1 * u

            s, t = t, s
            m0, m1 = m1, m0

        if m0 < 0:
            m0 += b // s
        return (s, m0)

    @staticmethod
    def raw(v: int) -> 'StaticModint':
        return StaticModint(v)

