    def init():
        C[0][0] = 1
        for i in range(1, Maxn + 1):
            C[i][0] = 1
            C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i-1][j] + C[i-1][j-1]) % Mod

    init()

    f_1 = [0] * (Maxn + 5)
    f_2 = [0] * (Maxn + 5)
    f_3 = [[0] * (Maxn + 5) for _ in range(Maxn + 5)]
    f_4 = [[0] * (Maxn + 5) for _ in range(Maxn + 5)]

    f_1[0] = 1
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            f_1[i] = (f_1[i] + f_1[i - j] * f_1[j - 1] % Mod * C[i - 1][j - 1]) % Mod
        f_1[i] = f_1[i] * (i + 1) % Mod

    for i in range(1, n + 1):
        for j in range(1, i + 1):
            sum_val = 0
            for k in range(1, i + 1):
                sum_val += abs_val(k - j)
            term1 = (j * (j - 1) // 2 + (i - j) * (i - j + 1) // 2) % Mod
            term2 = term1 * f_1[j - 1] % Mod * f_1[i - j] % Mod * C[i - 1][j - 1]
            term3 = f_2[j - 1] * f_1[i - j] % Mod * C[i - 1][j - 1] % Mod * (i + 1)
            term4 = f_2[i - j] * f_1[j - 1] % Mod * C[i - 1][j - 1] % Mod * (i + 1)
            f_2[i] = (f_2[i] + term2 + term3 + term4) % Mod

