            long long term2 = (f[j-1] * g[i-j] + f[i-j] * g[j-1]) % P * (i+1) % P * C[i-1][j-1] % P;
            long long term3 = (C[j][2] + C[i-j+1][2]) % P * f[j-1] % P * f[i-j] % P * C[i-1][j-1] % P;
            g[i] = (g[i] + term2 + term3) % P;
        }
    }

    p[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        int limit = min(i-1, m);
        for (int j = 0; j <= limit; ++j) {
            for (int k = 0; k <= j; ++k) {
                long long term1 = p[i-k-1][j-k] * f[k] % P * C[j][k] % P;
                p[i][j] = (p[i][j] + term1) % P;

                long long term2 = (p[i-k-1][j-k] * g[k] + q[i-k-1][j-k] * f[k]) % P * C[j][k] % P;
                q[i][j] = (q[i][j] + term2) % P;
            }
        }
        if (i <= m) {
            p[i][i] = f[i];
            q[i][i] = g[i];
        }
    }

    long long result = q[n][m] % P;
    if (result < 0) result += P;
    cout << result << endl;
    return 0;
}

