    f[0] = 1;
    g[0] = 0;

    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            int comb = C[i-1][j-1];
            int base = mul_mod(mul_mod(comb, i+1), mul_mod(f[j-1], f[i-j]));
            f[i] = add_mod(f[i], base);

            int part1 = mul_mod(mul_mod(comb, i+1), add_mod(mul_mod(f[j-1], g[i-j]), mul_mod(g[j-1], f[i-j])));
            int part2 = mul_mod(mul_mod(comb, (j-1)*j/2 + (i-j+1)*(i-j)/2), mul_mod(f[j-1], f[i-j]));
