            for (int k = 0; j + k <= m && i + k + 1 <= n; ++k) {
                int coef = mul_mod(mul_mod(dp[i][j], f[k]), C[j+k][j]);
                dp[i+k+1][j+k] = add_mod(dp[i+k+1][j+k], coef);

                int inner = add_mod(mul_mod(dp2[i][j], f[k]), mul_mod(dp[i][j], g[k]));
