using namespace std;

using ll = long long;
using ld = long double;

const ld PI = acosl(-1.0);

ll mod_exp(ll base, ll exp, ll mod) {
    ll res = 1;
    base %= mod;
    while (exp) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(10);

    int N, M;
    ll mod;
    cin >> N >> M >> mod;

    vector<ll> fac(N+1, 1), inv(N+1, 1);
    for (int i = 1; i <= N; ++i) {
        fac[i] = fac[i-1] * i % mod;
        inv[i] = inv[i-1] * mod_exp(i, mod-2, mod) % mod;
    }

    vector<ll> cnt(M+1, 0), sum(M+1, 0);
    cnt[0] = 1;

    for (int m = 1; m <= M; ++m) {
        for (int k = 0; k < m; ++k) {
            ll cl = cnt[k] * inv[k] % mod;
            ll cr = cnt[m-1-k] * inv[m-1-k] % mod;
            ll sl = sum[k] * inv[k] % mod;
            ll sr = sum[m-1-k] * inv[m-1-k] % mod;

            cnt[m] = (cnt[m] + cl * cr % mod * (m+1)) % mod;
            sum[m] = (sum[m] + (cl * sr + sl * cr) % mod * (m+1)) % mod;
            sum[m] = (sum[m] + cl * cr % mod * ((1LL*k*(k+1) + 1LL*(m-k)*(m-k-1))/2 % mod)) % mod;
        }
        cnt[m] = cnt[m] * fac[m-1] % mod;
        sum[m] = sum[m] * fac[m-1] % mod;
    }

    vector<vector<ll>> cnt_ans(N+1, vector<ll>(M+1, 0));
    vector<vector<ll>> sum_ans(N+1, vector<ll>(M+1, 0));
    cnt_ans[0][0] = 1;

    for (int i = 1; i <= N; ++i) {
        for (int j = 0; j <= min(i, M); ++j) {
            cnt_ans[i][j] = cnt_ans[i-1][j];
            sum_ans[i][j] = sum_ans[i-1][j];
            if (j == i) {
                cnt_ans[i][j] = (cnt_ans[i][j] + cnt[i] * inv[i] % mod) % mod;
                sum_ans[i][j] = (sum_ans[i][j] + sum[i] * inv[i] % mod) % mod;
            }
            for (int k = 1; k <= min(j, i-1); ++k) {
                ll c = cnt[k] * inv[k] % mod;
                ll s = sum[k] * inv[k] % mod;
                cnt_ans[i][j] = (cnt_ans[i][j] + cnt_ans[i-1-k][j-k] * c % mod) % mod;
                sum_ans[i][j] = (sum_ans[i][j] + (sum_ans[i-1-k][j-k] * c % mod + cnt_ans[i-1-k][j-k] * s % mod)) % mod;
            }
        }
    }

    ll ans = sum_ans[N][M] * fac[M] % mod;
    cout << ans << '\n';
    return 0;
}

