inline i64 arithmetic_sum(i64 x) {
    return (x * (x + 1) / 2) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> M >> MOD;

    // Precompute combinations
    for (int i = 0; i < MAX_N; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            comb[i][j] = (comb[i-1][j] + comb[i-1][j-1]) % MOD;
        }
    }

    // Base cases
    dp_line[0] = 1;
    dp_line[1] = 2;
    sum_line[0] = sum_line[1] = 0;

    // Compute line-related DP values
    for (int len = 2; len <= M; ++len) {
        dp_line[len] = 0;
        sum_line[len] = 0;
        for (int left = 0; left < len; ++left) {
            i64 base = dp_line[left] * dp_line[len-left-1] % MOD * comb[len-1][left] % MOD;
            dp_line[len] = (dp_line[len] + base * (len + 1)) % MOD;

            i64 part1 = (dp_line[left] * sum_line[len-left-1] % MOD + sum_line[left] * dp_line[len-left-1] % MOD) * comb[len-1][left] % MOD;
            part1 = part1 * (len + 1) % MOD;
            i64 part2 = base * (arithmetic_sum(left) + arithmetic_sum(len-1-left)) % MOD;
            sum_line[len] = (sum_line[len] + part1 + part2) % MOD;
        }
    }

    // Grid DP initialization
    dp_grid[0][0] = 1;

    // Fill grid DP
    for (int rows = 0; rows < M; ++rows) {
        for (int cols = 0; cols <= rows; ++cols) {
            if (dp_grid[rows][cols] == 0) continue;
            for (int block = 1; rows + block <= M; ++block) {
                i64 coef = dp_grid[rows][cols] * dp_line[block] % MOD * comb[rows+block][block] % MOD;
                dp_grid[rows+block][cols+1] = (dp_grid[rows+block][cols+1] + coef) % MOD;

                i64 sum_coef = (dp_grid[rows][cols] * sum_line[block] % MOD + sum_grid[rows][cols] * dp_line[block] % MOD) * comb[rows+block][block] % MOD;
                sum_grid[rows+block][cols+1] = (sum_grid[rows+block][cols+1] + sum_coef) % MOD;
            }
        }
    }

    // Final answer calculation
    i64 answer = 0;
    for (int cols = 1; cols <= M; ++cols) {
        int remaining = N - (M - 1 + cols);
        if (remaining < 0) break;
        answer = (answer + sum_grid[M][cols] * comb[remaining + cols][cols]) % MOD;
    }

    cout << answer << '\n';

    return 0;
}

