        }
    }

    vector<int> f(n + 1, 0), g(n + 1, 0);
    f[0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            int term1 = (int)(((long long)f[j-1] * f[i-j] % mod) * C[i-1][j-1] % mod * (i + 1) % mod);
            f[i] = (f[i] + term1) % mod;

            int term2 = (int)(((long long)g[j-1] * f[i-j] % mod) * C[i-1][j-1] % mod * (i + 1) % mod);
            g[i] = (g[i] + term2) % mod;

            int term3 = (int)(((long long)g[i-j] * f[j-1] % mod) * C[i-1][j-1] % mod * (i + 1) % mod);
            g[i] = (g[i] + term3) % mod;

            int sum_abs = 0;
            for (int k = 1; k <= i; ++k) {
                sum_abs = (sum_abs + abs(k - j)) % mod;
            }
            int term4 = (int)(((long long)f[j-1] * f[i-j] % mod) * C[i-1][j-1] % mod * sum_abs % mod);
            g[i] = (g[i] + term4) % mod;
        }
    }

    vector<vector<int>> dp_f(n + 1, vector<int>(n + 1, 0));
    vector<vector<int>> dp_g(n + 1, vector<int>(n + 1, 0));
