    return binom(n, n) - (binom(n-1, n+1) if n-1 >= 0 else Modular(0))

def solve():
    n, m, mod = read_ints()
    global MOD
    MOD = mod

    init_fact()

    ans = Modular(0, mod)

    for length in range(1, m):
        f = Modular(length + 1, mod).pow(length) * length / (n - length) * FINV[length]

        for i in range(m - length):
