INF = BIG_INF

# Modular arithmetic
class Modular:
    def __init__(self, value=0, modulus=998244353):
        self.modulus = modulus
        self.normalize(value % modulus + modulus)

    def normalize(self, v):
        self.value = v if v < self.modulus else v - self.modulus

    def __neg__(self):
        return Modular(0, self.modulus) - self

    def __iadd__(self, rhs):
        self.normalize(self.value + rhs.value)
        return self

    def __isub__(self, rhs):
        self.normalize(self.value + self.modulus - rhs.value)
        return self

    def __imul__(self, rhs):
        self.value = (self.value * rhs.value) % self.modulus
        return self

    def __add__(self, rhs):
        result = Modular(self.value, self.modulus)
        result += rhs
        return result

    def __sub__(self, rhs):
        result = Modular(self.value, self.modulus)
        result -= rhs
        return result

    def __mul__(self, rhs):
        result = Modular(self.value, self.modulus)
        result *= rhs
        return result

    def __truediv__(self, rhs):
        return self * rhs.inverse()

    def __eq__(self, rhs):
        return self.value == rhs.value

    def __ne__(self, rhs):
        return self.value != rhs.value

    def __lt__(self, rhs):
        return self.value < rhs.value

    def __int__(self):
        return self.value

    def __repr__(self):
        return str(self.value)

    def exponentiate(self, exp):
        base = Modular(self.value, self.modulus)
        result = Modular(1, self.modulus)
        while exp:
            if exp & 1:
                result *= base
            base *= base
            exp >>= 1
        return result

    def inverse(self):
        return self.exponentiate(self.modulus - 2)

# Global variables for factorials
MAX_SIZE = 10010
factorial_table = [None] * MAX_SIZE
inv_factorial_table = [None] * MAX_SIZE
modular_inverse = [None] * MAX_SIZE

def initialize_factorials():
    factorial_table[0] = Modular(1)
    for i in range(1, MAX_SIZE):
        factorial_table[i] = factorial_table[i-1] * i

    inv_factorial_table[MAX_SIZE - 1] = factorial_table[MAX_SIZE - 1].inverse()
    for i in range(MAX_SIZE - 2, -1, -1):
        inv_factorial_table[i] = inv_factorial_table[i + 1] * (i + 1)

