            for (int k = 0; k <= min(j, total_m); ++k) {
                if (k == 0) {
                    dp_shift[step][j] = dp_memo[j][0];
                    ways_shift[step][j] = ways_memo[j][0];
                }
                plusmod(dp_tmp[j][0], dp_memo[j][k]);
                plusmod(ways_tmp[j][0], ways_memo[j][k]);
                int leftover = total_m - (j - k);
                llong c1 = ways_shift[step - k][j - k] * comb[leftover][k + 1] % modulus * funcG[k + 1] % modulus;
                llong c2 = dp_shift[step - k][j - k] * comb[leftover][k + 1] % modulus * funcG[k + 1] % modulus;
                llong c3 = ways_shift[step - k][j - k] * comb[leftover][k + 1] % modulus * funcF[k + 1] % modulus;
                plusmod(ways_tmp[j + 1][k + 1], c1);
                plusmod(dp_tmp[j + 1][k + 1], (c2 + c3) % modulus);
            }
        }
        copy_n(&dp_tmp[0][0], MX * MX, &dp_memo[0][0]);
        copy_n(&ways_tmp[0][0], MX * MX, &ways_memo[0][0]);
    }

    llong result = 0;
    for (int i = 0; i <= total_m; ++i) {
        plusmod(result, dp_memo[total_m][i]);
    }
    cout << result << '\n';
    return 0;
}

