#include <bits/stdc++.h>

#define err(A) cout << #A << " = " << (A) << endl

#define ll long long

using namespace std;

const int MAX_N = 512;

ll n, m, MOD;

ll comb[MAX_N][MAX_N];
ll power[MAX_N][MAX_N];

ll totalA, totalB;

ll computeG(ll a, ll b) {
  if (b == 0) return 1;
  return power[a + 1][b - 1] * power[2][b] % MOD * (a + 1 - b) % MOD;
}

signed main() {
  ios::sync_with_stdio(false); cin.tie(nullptr);

  cin >> n >> m >> MOD;

  // Precompute binomial coefficients modulo MOD
  for (int i = 0; i < MAX_N; i++) {
    comb[i][0] = 1;
    for (int j = 1; j <= i; j++) {
      comb[i][j] = (comb[i-1][j] + comb[i-1][j-1]) % MOD;
    }
  }

  // Precompute powers modulo MOD
  for (int i = 0; i < MAX_N; i++) {
    power[i][0] = 1;
    for (int j = 1; j < MAX_N; j++) {
      power[i][j] = power[i][j-1] * i % MOD;
    }
  }

  // Compute totalB accumulation
  for (int i = 2; i <= m; i++) {
    for (int d = 1; d < i; d++) {
      ll term1 = d * (d + 1) / 2 % MOD;
      ll term2 = comb[i - 1][d];
      ll term3 = power[d + 1][d - 1];
      ll term4 = computeG(n + 1 - (d + 1) - 1, i - (d + 1));
      ll term5 = power[2][d];
      ll term6 = power[n + 1][m - i];
      ll term7 = power[2][m - i];

      totalA = term1 * term2 % MOD;
      totalA = totalA * term3 % MOD;
      totalA = totalA * term4 % MOD;
      totalA = totalA * term5 % MOD;
      totalA = totalA * term6 % MOD;
      totalA = totalA * term7 % MOD;

      totalB = (totalB + totalA + totalA) % MOD;
    }
  }

  cout << totalB * (n + 1 - m) % MOD << endl;

  return 0;
}

