inline void add(int &x, int y) {
    x = (x + y) % MOD;
    if (x < 0) x += MOD;
}

inline int sum_tri(int n) {
    return 1LL * n * (n + 1) / 2;
}

int main() {
    int n, m;
    scanf("%d%d%d", &n, &m, &MOD);

    for (int i = 0; i <= m; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = (C[i-1][j] + C[i-1][j-1]) % MOD;
        }
    }

    dp1[0] = {1, 0};
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            int w = 1LL * dp1[j-1].first * dp1[i-j].first % MOD * C[i-1][j-1] % MOD;
            int term1 = 1LL * (sum_tri(j-1) + sum_tri(i-j)) * w % MOD;
            int term2 = 1LL * dp1[j-1].second * dp1[i-j].first % MOD * (i+1) % MOD * C[i-1][j-1] % MOD;
            int term3 = 1LL * dp1[j-1].first * dp1[i-j].second % MOD * (i+1) % MOD * C[i-1][j-1] % MOD;

            dp1[i].second = (dp1[i].second + term1 + term2 + term3) % MOD;
            dp1[i].first = (dp1[i].first + 1LL * w * (i+1) % MOD) % MOD;
        }
    }

    dp2[0][0][0] = dp2[1][0][0] = {1, 0};
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= i; ++j) {
            for (int ln = 1; ln <= n - i; ++ln) {
                dp2[1][i + ln][j].first = (dp2[1][i + ln][j].first + dp2[0][i][j].first) % MOD;
                dp2[1][i + ln][j].second = (dp2[1][i + ln][j].second + dp2[0][i][j].second) % MOD;

                int coef = 1LL * dp2[1][i][j].first * dp1[ln].first % MOD * C[j + ln][j] % MOD;
                dp2[0][i + ln][j + ln].first = (dp2[0][i + ln][j + ln].first + coef) % MOD;

                coef = 1LL * dp2[1][i][j].first * dp1[ln].second % MOD * C[j + ln][j] % MOD;
                dp2[0][i + ln][j + ln].second = (dp2[0][i + ln][j + ln].second + coef) % MOD;

                coef = 1LL * dp2[1][i][j].second * dp1[ln].first % MOD * C[j + ln][j] % MOD;
                dp2[0][i + ln][j + ln].second = (dp2[0][i + ln][j + ln].second + coef) % MOD;
            }
        }
    }

    int ans = (dp2[0][n][m].second + dp2[1][n][m].second) % MOD;
    printf("%d\n", ans);
}

