    for (int i = 0; i < n; ++i) {
        fill(dp2_nxt.begin(), dp2_nxt.end(), vector<pair<int, int>>(n + 1, {0, 0}));

        for (int j = 0; j <= i; ++j) {
            for (int ln = 1; ln <= n - i; ++ln) {
                dp2_nxt[i + ln][j].first = (dp2_nxt[i + ln][j].first + dp2_cur[i][j].first) % MOD;
                dp2_nxt[i + ln][j].second = (dp2_nxt[i + ln][j].second + dp2_cur[i][j].second) % MOD;

                int coef1 = (ll)dp2_nxt[i][j].first * dp1[ln].first % MOD * comb(j + ln, j, C) % MOD;
                dp2_cur[i + ln][j + ln].first = (dp2_cur[i + ln][j + ln].first + coef1) % MOD;

                int coef2 = (ll)dp2_nxt[i][j].first * dp1[ln].second % MOD * comb(j + ln, j, C) % MOD;
                dp2_cur[i + ln][j + ln].second = (dp2_cur[i + ln][j + ln].second + coef2) % MOD;

                int coef3 = (ll)dp2_nxt[i][j].second * dp1[ln].first % MOD * comb(j + ln, j, C) % MOD;
                dp2_cur[i + ln][j + ln].second = (dp2_cur[i + ln][j + ln].second + coef3) % MOD;
            }
        }
        swap(dp2_cur, dp2_nxt);
    }

    int ans = (dp2_cur[n][m].second + dp2_nxt[n][m].second) % MOD;
    cout << ans << endl;
}

