#include <bits/stdc++.h>
using namespace std;
using pii = pair<int, int>;

int MOD;

inline int add_mod(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}

inline int mul_mod(int a, int b) {
    return (int)((long long)a * b % MOD);
}

int main() {
    int n, m;
    scanf("%d%d%d", &n, &m, &MOD);

    vector<vector<int>> C(n + 1, vector<int>(n + 1, 0));
    for (int i = 0; i <= n; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = add_mod(C[i-1][j], C[i-1][j-1]);
        }
    }

    vector<pii> dp1(n + 1);
    dp1[0] = {1, 0};

    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            int w = mul_mod(mul_mod(dp1[j-1].first, dp1[i-j].first), C[i-1][j-1]);
            int tri_sum = (j-1)*j/2 + (i-j)*(i-j+1)/2;
            int term1 = mul_mod(tri_sum, w);
            int term2 = mul_mod(mul_mod(mul_mod(dp1[j-1].second, dp1[i-j].first), i+1), C[i-1][j-1]);
            int term3 = mul_mod(mul_mod(mul_mod(dp1[j-1].first, dp1[i-j].second), i+1), C[i-1][j-1]);

            dp1[i].second = add_mod(dp1[i].second, add_mod(term1, add_mod(term2, term3)));
            dp1[i].first = add_mod(dp1[i].first, mul_mod(w, i+1));
        }
    }

    vector<vector<pii>> dp2_0(n + 1, vector<pii>(n + 1, {0, 0}));
    vector<vector<pii>> dp2_1(n + 1, vector<pii>(n + 1, {0, 0}));
    dp2_0[0][0] = dp2_1[0][0] = {1, 0};

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= i; ++j) {
            for (int ln = 1; ln <= n - i; ++ln) {
                dp2_1[i + ln][j].first = add_mod(dp2_1[i + ln][j].first, dp2_0[i][j].first);
                dp2_1[i + ln][j].second = add_mod(dp2_1[i + ln][j].second, dp2_0[i][j].second);

                int coef1 = mul_mod(mul_mod(dp2_1[i][j].first, dp1[ln].first), C[j + ln][j]);
                dp2_0[i + ln][j + ln].first = add_mod(dp2_0[i + ln][j + ln].first, coef1);

                int coef2 = mul_mod(mul_mod(dp2_1[i][j].first, dp1[ln].second), C[j + ln][j]);
                dp2_0[i + ln][j + ln].second = add_mod(dp2_0[i + ln][j + ln].second, coef2);

                int coef3 = mul_mod(mul_mod(dp2_1[i][j].second, dp1[ln].first), C[j + ln][j]);
                dp2_0[i + ln][j + ln].second = add_mod(dp2_0[i + ln][j + ln].second, coef3);
            }
        }
    }

    int ans = add_mod(dp2_0[n][m].second, dp2_1[n][m].second);
    printf("%d\n", ans);
}

