using namespace std;

using ll = long long;

const int MAX_M = 500;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, MOD;
    cin >> n >> m >> MOD;

    // Use static arrays with fixed size
    array<array<int, MAX_M + 5>, MAX_M + 5> C{}, way{}, sum{}, g{}, f{};

    // Precompute binomial coefficients
    for (int i = 0; i <= m; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
            if (C[i][j] >= MOD) C[i][j] -= MOD;
        }
    }

    way[0] = 1;
    for (int i = 1; i <= m; ++i) {
        for (int j = 0; j < i; ++j) {
            // way[i] += (i+1) * C[i-1][j] * way[j] * way[i-j-1]
            ll term1 = (ll)(i+1) * C[i-1][j] % MOD;
            term1 = term1 * way[j] % MOD;
            term1 = term1 * way[i-j-1] % MOD;
            way[i] = (way[i] + term1) % MOD;

            // sum[i] += (tri(j) + tri(i-j-1)) * way[j] * way[i-j-1] * C[i-1][j]
            int tri_j = j * (j + 1) / 2;
            int tri_ij = (i - j - 1) * (i - j) / 2;
            ll term2 = (ll)(tri_j + tri_ij) * way[j] % MOD;
            term2 = term2 * way[i-j-1] % MOD;
            term2 = term2 * C[i-1][j] % MOD;
            sum[i] = (sum[i] + term2) % MOD;

            // sum[i] += (i+1) * (sum[j]*way[i-j-1] + way[j]*sum[i-j-1]) * C[i-1][j]
            ll term3 = (ll)sum[j] * way[i-j-1] % MOD;
            ll term4 = (ll)way[j] * sum[i-j-1] % MOD;
            ll term5 = (term3 + term4) % MOD;
            term5 = term5 * (i+1) % MOD;
            term5 = term5 * C[i-1][j] % MOD;
            sum[i] = (sum[i] + term5) % MOD;
        }
    }

    ++n;
    f[0][0] = 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= m; ++j) {
            for (int k = 0; j + k <= m && i + k + 1 <= n; ++k) {
                int comb = C[j+k][j];

                // f[i+k+1][j+k] += f[i][j] * way[k] * comb
                ll f_contrib = (ll)f[i][j] * way[k] % MOD;
                f_contrib = f_contrib * comb % MOD;
                f[i+k+1][j+k] = (f[i+k+1][j+k] + f_contrib) % MOD;

                // g[i+k+1][j+k] += (f[i][j] * sum[k] + g[i][j] * way[k]) * comb
                ll g_contrib1 = (ll)f[i][j] * sum[k] % MOD;
                ll g_contrib2 = (ll)g[i][j] * way[k] % MOD;
                ll g_contrib = (g_contrib1 + g_contrib2) % MOD;
                g_contrib = g_contrib * comb % MOD;
                g[i+k+1][j+k] = (g[i+k+1][j+k] + g_contrib) % MOD;
            }
        }
    }

    cout << g[n][m] % MOD << '\n';
    return 0;
}

