    for (int i = 1; i <= m; ++i) {
        for (int j = 0; j < i; ++j) {
            // way[i] += (i+1) * C[i-1][j] * way[j] * way[i-j-1]
            i64 term = (i64)(i+1) * C[i-1][j] % MOD;
            term = term * way[j] % MOD;
            term = term * way[i-j-1] % MOD;
            way[i] = (way[i] + term) % MOD;

            // sum[i] += (j*(j+1)/2 + (i-j-1)*(i-j)/2) * way[j] * way[i-j-1] * C[i-1][j]
            int tri_j = j * (j+1) / 2;
            int tri_ij = (i-j-1) * (i-j) / 2;
            i64 term2 = (i64)(tri_j + tri_ij) * way[j] % MOD;
            term2 = term2 * way[i-j-1] % MOD;
            term2 = term2 * C[i-1][j] % MOD;
            sum[i] = (sum[i] + term2) % MOD;

            // sum[i] += (i+1) * (sum[j]*way[i-j-1] + way[j]*sum[i-j-1]) * C[i-1][j]
            i64 s1 = (i64)sum[j] * way[i-j-1] % MOD;
            i64 s2 = (i64)way[j] * sum[i-j-1] % MOD;
            i64 term3 = (s1 + s2) % MOD;
            term3 = term3 * (i+1) % MOD;
            term3 = term3 * C[i-1][j] % MOD;
            sum[i] = (sum[i] + term3) % MOD;
        }
    }

    f[0][0] = 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= m; ++j) {
            for (int k = 0; j + k <= m && i + k + 1 <= n; ++k) {
                int comb = C[j+k][j];

                // f update
                i64 f_val = (i64)f[i][j] * way[k] % MOD;
                f_val = f_val * comb % MOD;
                f[i+k+1][j+k] = (f[i+k+1][j+k] + f_val) % MOD;

                // g update
                i64 g_val1 = (i64)f[i][j] * sum[k] % MOD;
                i64 g_val2 = (i64)g[i][j] * way[k] % MOD;
                i64 g_val = (g_val1 + g_val2) % MOD;
                g_val = g_val * comb % MOD;
                g[i+k+1][j+k] = (g[i+k+1][j+k] + g_val) % MOD;
            }
        }
    }

    cout << g[n][m] % MOD << '\n';
    return 0;
}

