	cnt[1]=2;dp[1]=0;
	FOR(i,2,m)
	{
		FOR(j,1,i)
		{
			zh=C(i-1,j-1);
			tmp=1ll*cnt[j-1]*cnt[i-j]%p*zh%p;
			dp[i]=(1ll*dp[i]+1ll*tmp*sum(j-1)+1ll*zh*j%p*(1ll*dp[j-1]*cnt[i-j]%p+1ll*dp[i-j]*cnt[j-1]%p)%p)%p;
			cnt[i]=(1ll*cnt[i]+1ll*tmp*j)%p;
			dp[i]=(1ll*dp[i]+1ll*tmp*sum(i-j)+1ll*zh*(i-j+1)%p*(1ll*dp[j-1]*cnt[i-j]%p+1ll*dp[i-j]*cnt[j-1]%p)%p)%p;
			cnt[i]=(1ll*cnt[i]+1ll*tmp*(i-j+1))%p;
		}
	}
	dp2[0][0]=0;tot[0][0]=1;
	FOR(i,1,n)
	{
		FOR(j,0,min(m,i))
		{
			dp2[i][j]=dp2[i-1][j];
			tot[i][j]=tot[i-1][j];
			FOR(k,1,j)
			{
				if(k<i)
				{
					zh=C(j,k);
					dp2[i][j]=(1ll*dp2[i][j]+1ll*dp[k]*zh%p*tot[i-k-1][j-k]%p+1ll*dp2[i-k-1][j-k]*zh%p*cnt[k]%p)%p;
					tot[i][j]=(1ll*tot[i][j]+1ll*cnt[k]*tot[i-k-1][j-k]%p*zh)%p;
				}
				else
				{
					dp2[i][j]=(dp2[i][j]+dp[i])%p;
					tot[i][j]=(tot[i][j]+cnt[i])%p;
				}
			}
		}
	}
	printf("%d\n",dp2[n][m]);
	return 0;
}

