ll modpow(ll a, ll b, int mod) {
    ll res = 1;
    while (b) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

ll C(int nn, int mm) {
    return fac[nn] * invfac[mm] % p * invfac[nn - mm] % p;
}

ll SUM(int x) {
    return 1LL * x * (x + 1) / 2 % p;
}

int main() {
