    for (int i = 499; i >= 0; --i) {
        invfac[i] = invfac[i + 1] * (i + 1) % p;
    }

    cnt[0] = 1; dp[0] = 0;
    cnt[1] = 2; dp[1] = 0;

    for (int i = 2; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            zh = C(i - 1, j - 1);
            tmp = cnt[j - 1] * cnt[i - j] % p * zh % p;
            dp[i] = (dp[i] + tmp * SUM(j - 1) % p + zh * j % p * (dp[j - 1] * cnt[i - j] % p + dp[i - j] * cnt[j - 1] % p) % p) % p;
            cnt[i] = (cnt[i] + tmp * j) % p;
            dp[i] = (dp[i] + tmp * SUM(i - j) % p + zh * (i - j + 1) % p * (dp[j - 1] * cnt[i - j] % p + dp[i - j] * cnt[j - 1] % p) % p) % p;
            cnt[i] = (cnt[i] + tmp * (i - j + 1)) % p;
        }
    }

    dp2[0][0] = 0; tot[0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= min(m, i); ++j) {
            dp2[i][j] = dp2[i - 1][j];
            tot[i][j] = tot[i - 1][j];
            for (int k = 1; k <= j; ++k) {
                if (k < i) {
                    zh = C(j, k);
                    dp2[i][j] = (dp2[i][j] + dp[k] * zh % p * tot[i - k - 1][j - k] % p + dp2[i - k - 1][j - k] * zh % p * cnt[k] % p) % p;
                    tot[i][j] = (tot[i][j] + cnt[k] * tot[i - k - 1][j - k] % p * zh) % p;
                } else {
                    dp2[i][j] = (dp2[i][j] + dp[i]) % p;
                    tot[i][j] = (tot[i][j] + cnt[i]) % p;
                }
            }
        }
    }

