                long long term6 = (long long)res2[i-h-1][j-h] * dp[h] % MOD;
                term6 = term6 * comb[h][j] % MOD;
                res2[i][j] = (res2[i][j] + (int)term6) % MOD;

                long long term7 = (long long)res[i-h-1][j-h] * dp2[h] % MOD;
                term7 = term7 * comb[h][j] % MOD;
                res2[i][j] = (res2[i][j] + (int)term7) % MOD;
            }

            res[i][j] = (res[i][j] + dp[j]) % MOD;
            res2[i][j] = (res2[i][j] + dp2[j]) % MOD;
