import sys

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx]); idx += 1
    m = int(input_data[idx]); idx += 1
    mod = int(input_data[idx]); idx += 1

    # Initialize arrays
    g = [0] * 505
    sg = [0] * 505
    f = [[0] * 505 for _ in range(505)]
    sf = [[0] * 505 for _ in range(505)]

    # C array for combinations
    C = [[0] * 505 for _ in range(505)]

    def add(ta, tb):
        return (ta + tb) % mod if (ta + tb) < mod else (ta + tb - mod)

    def sub(ta, tb):
        return (ta - tb) % mod if ta >= tb else (ta - tb + mod)

    def make_C():
        C[0][0] = 1
        for i in range(1, n + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = add(C[i-1][j], C[i-1][j-1])

    def S1(tn):
        return (tn * (tn + 1) // 2) % mod

    make_C()

    g[0] = 1
    for i in range(1, m + 1):
        for j in range(1, i + 1):
            tmp = (g[j-1] * g[i-j] % mod) * C[i-1][j-1] % mod
            g[i] = (g[i] + tmp * (i + 1)) % mod
            term1 = (sg[j-1] * g[i-j] % mod) * C[i-1][j-1] % mod * (i + 1) % mod
            term2 = (sg[i-j] * g[j-1] % mod) * C[i-1][j-1] % mod * (i + 1) % mod
            term3 = tmp * ((S1(i-j) + S1(j-1)) % mod) % mod
            sg[i] = (sg[i] + term1 + term2 + term3) % mod

    for i in range(0, n + 1):
        f[i][0] = 1

    for i in range(1, n + 1):
        if i <= m:
            f[i][i] = g[i]
            sf[i][i] = sg[i]
        for j in range(1, min(i - 1, m) + 1):
            for t in range(i, 0, -1):
                if i - t > j:
                    break
                tmp = g[i-t] * C[j][i-t] % mod
                f[i][j] = (f[i][j] + f[t-1][j-i+t] * tmp) % mod
