            nw.g = addmod((nw.g * (i + 1)) % mod + (nw.f * addmod(F(j - 1) + F(i - j))) % mod)
            nw.g = (nw.g * inv[i]) % mod
            nw.f = (nw.f * (i + 1) % mod * inv[i]) % mod
            dp[i] = dp[i] + nw

    up = [[pt() for _ in range(m + 1)] for _ in range(n + 1)]
    up[0][0] = pt(1, 0)

