    for (int i = at; i < ncomp; ++i) {
        int lcnt = i - at;
        int rcnt = cnt - lcnt;
        if (rcnt < 0 || rcnt > ncomp - i - 1) continue;
        Res lres = (i == at) ? Res(1, 0) : go2(lcnt);
        Res rres = (i + 1 == ncomp) ? Res(1, 0) : go1(i + 1, rcnt);
        int mlt = choose[lcnt + rcnt][lcnt];
        ret.ways = (ret.ways + (ll)lres.ways * rres.ways % MOD * mlt) % MOD;
        ret.summaddness = (ret.summaddness + 
            (ll)lres.summaddness * rres.ways % MOD * mlt +
            (ll)lres.ways * rres.summaddness % MOD * mlt) % MOD;
    }
    done1[at][cnt] = true;
    mem1[at][cnt] = ret;
    return ret;
}

int solve() {
    for (int i = 0; i <= ncomp; ++i) {
        choose[i][0] = choose[i][i] = 1;
        for (int j = 1; j < i; ++j)
            choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD;
    }
    for (int i = 0; i <= ncomp; ++i) done2[i] = false;
    for (int i = 0; i < ncomp; ++i)
        for (int j = 0; j <= npers; ++j)
            done1[i][j] = false;
    return go1(0, npers).summaddness;
}

void run() {
    scanf("%d%d%d", &ncomp, &npers, &MOD);
    printf("%d\n", solve());
}

