    for i in range(C + 1):
        if x & (1 << i):
            if S[len(S) - C - 1 + i] == 'B':
                return False
        else:
            if S[len(S) - C - 1 + i] == 'A':
                return False
    return True

def main():
    init()
    dfsL(0, R-1, R-1, 0, 0)
    dfsR(0, R+C, R+C, 0, 0)

    dif = INF
    for i in range(R + C + 1):
        dpL[i].sort()
        dpR[i].sort()
        dpR[i].reverse()
        ind = 0
        for t in dpL[i]:
            while ind + 1 < len(dpR[i]) and t[0] + dpR[i][ind+1][0] >= 0:
                ind += 1
            dif = min(dif, abs(t[0] + dpR[i][ind][0]))
            if ind + 1 < len(dpR[i]):
                dif = min(dif, abs(t[0] + dpR[i][ind+1][0]))

    for i in range(R + C + 1):
        z = []
        for t in dpR[i]:
            if ok(rev(t[1], C + 1)):
                z.append(t)
        l = 0
        r = -1
        for t in dpL[i]:
            while l < len(z) and t[0] + z[l][0] > dif:
                l += 1
            while r + 1 < len(z) and t[0] + z[r+1][0] >= -dif:
                r += 1
            if l <= r:
                check(t[0] | (rev(z[l][1], C + 1) << (C + 1)), r - l + 1)

