				if (S[j] == 'A') aa++;
				if (S[j] == 'B') bb++;
			}
			ll tmp = 0;
			if (x&(1LL<<i)) {
				tmp = comb[R-1-aa+b+R-1-bb][R-1-aa];
			} else {
				tmp = comb[a+R-1-aa+R-1-bb][a+R-1-aa];
			}
			ans += t*tmp;
			return;
		}
	}
}

bool ok(ll x) {
	for (int i = 0; i < C+1; i++) {
		if (x&(1<<i)) {
			if (S[S.size()-C-1+i] == 'B') return false;
		} else {
			if (S[S.size()-C-1+i] == 'A') return false;
		}
	}
	return true;
}

int main() {
	init();
	dfsL(0,R-1,R-1,0,0);
	dfsR(0,R+C,R+C,0,0);
	ll dif = INF;
