long long C[777][777];
int R, C_input;
long long total_paths;
long long min_diff = (long long)1e18;
long long best_x = -1;

void dfs(long long x_val, long long y_val, int i_idx, int j_idx) {
    long long diff = abs(x_val - y_val);
    if (min_diff <= 1 || diff - C[i_idx][R] * C[j_idx][R] >= min_diff)
        return;

    if (i_idx == R - 1 && j_idx == R - 1) {
        long long cur_diff = abs(x_val - y_val);
        if (cur_diff < min_diff) {
            min_diff = cur_diff;
            best_x = x_val;
        }
        return;
    }

    if (i_idx >= R) {
        long long delta_x = C[i_idx][R] - C[i_idx - 1][R];
        long long sum_y = C[j_idx][R];
        dfs(x_val, y_val + delta_x * sum_y, i_idx - 1, j_idx);
    }

    if (j_idx >= R) {
        long long sum_x = C[i_idx][R];
        long long delta_y = C[j_idx][R] - C[j_idx - 1][R];
        dfs(x_val + sum_x * delta_y, y_val, i_idx, j_idx - 1);
    }
}

char input_str[12345];
int cnt_A[12345], cnt_B[12345];
map<long long, long long> memo_map;

long long solve_dp(long long x_val, long long y_val, int i_idx, int j_idx) {
    long long state = x_val * 10000 + i_idx * 100 + j_idx;
    if (memo_map.count(state))
        return memo_map[state];

    long long &res = memo_map[state];
    long long diff = abs(x_val - y_val);
    if (diff - C[i_idx][R] * C[j_idx][R] > min_diff) {
        return res = 0;
    }

    if (i_idx < R || j_idx < R) {
        if (i_idx >= cnt_A[i_idx + j_idx] && j_idx >= cnt_B[i_idx + j_idx]) {
            int total = i_idx + j_idx;
            i_idx -= cnt_A[total];
            j_idx -= cnt_B[total];
            return res = C[total][i_idx];
        }
        return res = 0;
    }

    res = 0;
    char c = input_str[i_idx + j_idx - 1];
    if (c != 'B') {
        long long delta_x = C[i_idx][R] - C[i_idx - 1][R];
        long long sum_y = C[j_idx][R];
        res += solve_dp(x_val, y_val + delta_x * sum_y, i_idx - 1, j_idx);
    }
    if (c != 'A') {
        long long sum_x = C[i_idx][R];
        long long delta_y = C[j_idx][R] - C[j_idx - 1][R];
        res += solve_dp(x_val + sum_x * delta_y, y_val, i_idx, j_idx - 1);
    }
    return res;
}

int main() {
    scanf("%d %d", &R, &C_input);
    for (int i = 0; i <= 2 * (R + C_input); i++) {
        for (int j = 0; j <= 2 * (R + C_input); j++) {
            if (j == 0) C[i][j] = 1;
            else if (i == 0) C[i][j] = 0;
            else C[i][j] = C[i - 1][j] + C[i - 1][j - 1];
        }
    }

    total_paths = C[R + C_input][R] * C[R + C_input][R];

    {
        long long x = 0, y = 0;
        int i = R + C_input, j = R + C_input;
        while (i >= R && j >= R) {
            if (x > y) {
                long long delta_x = C[i][R] - C[i - 1][R];
                long long sum_y = C[j][R];
                y += delta_x * sum_y;
                i--;
            } else {
                long long sum_x = C[i][R];
                long long delta_y = C[j][R] - C[j - 1][R];
                x += sum_x * delta_y;
                j--;
            }
        }
        min_diff = abs(x - y);
    }

    dfs(0, 0, R + C_input, R + C_input);
    scanf("%s", input_str);
    cnt_A[0] = cnt_B[0] = 0;
    for (int i = 0; i < 2 * (R + C_input); i++) {
        cnt_A[i + 1] = cnt_A[i] + (input_str[i] == 'A');
        cnt_B[i + 1] = cnt_B[i] + (input_str[i] == 'B');
    }

    long long result = solve_dp(0, 0, R + C_input, R + C_input);
    cout << result << endl;
    return 0;
}

