            if (step + y + 1 <= 2*total - d && pattern[total - step + total - y - 1] != 'B') {
                for (auto& kv : backward_dp[step][y]) {
                    lli new_area = prefix_sum[total][total] - kv.first - prefix_sum[total-step][total-(y+1)];
