            if (step + y + 1 <= d && pattern[step + y] != 'A') {
                lli cell = prefix_sum[step+1][y] - prefix_sum[step][y];
                for (auto& kv : forward_dp[step][y]) {
                    lli new_val = kv.first + cell;
                    lli rem = prefix_sum[step+1][total] - new_val;
                    if (rem <= half2) {
                        forward_dp[step+1][y][new_val] += kv.second;
                    }
                }
            }
            if (step + y + 1 <= 2*total - d && pattern[total - step + total - y - 1] != 'A') {
                lli cell = prefix_sum[total-step][total-y] - prefix_sum[total-step-1][total-y];
                for (auto& kv : backward_dp[step][y]) {
                    if (kv.first + cell <= half2) {
                        backward_dp[step+1][y][kv.first + cell] += kv.second;
                    }
                }
            }
            if (step + y + 1 <= d) forward_dp[step][y].clear();
            if (step + y + 1 <= 2*total - d) backward_dp[step][y].clear();
        }
    }

    for (lli x = 0; x <= total; ++x) {
        lli y = d - x;
        if (y < 0 || y > total) continue;
        for (auto& kv : forward_dp[x][y]) {
            lli area = kv.first;
            lli cnt = kv.second;
            final_count += cnt * backward_dp[total-x][total-y][half1 - area];
            if (half1 != half2) {
                final_count += cnt * backward_dp[total-x][total-y][half2 - area];
            }
        }
    }

    cout << final_count << '\n';
    return 0;
}

