    for(long long step = 0; step <= totalSteps; step++){
        for(long long x = 0; x <= step && x <= totalSteps; x++){
            long long y = step - x;
            if(y > totalSteps) continue;

            if(step < totalSteps && pattern[step] != 'B' && x <= totalSteps && y+1 <= totalSteps){
                for(auto& kv : dp[x][y]){
                    long long newArea = kv.first + (prefixSum[totalSteps][y+1] - prefixSum[x][y+1]);
                    if(newArea <= otherHalf){
                        dp[x][y+1][kv.first] += kv.second;
                    }
                }
            }

            if(step < totalSteps && pattern[2*totalSteps-step-1] != 'B' && x <= totalSteps && y+1 <= totalSteps){
                for(auto& kv : bp[x][y]){
                    long long newArea = reverseSum[totalSteps][totalSteps] - kv.first - reverseSum[totalSteps-x][totalSteps-(y+1)];
                    if(newArea <= otherHalf){
                        bp[x][y+1][kv.first] += kv.second;
                    }
                }
            }

            if(step < totalSteps && x+1 <= totalSteps && y <= totalSteps){
                if(pattern[step] != 'A'){
                    long long newArea = prefixSum[x+1][y] - prefixSum[x][y];
                    for(auto& kv : dp[x][y]){
                        long long newTotal = kv.first + newArea;
                        if(newTotal <= otherHalf){
                            dp[x+1][y][newTotal] += kv.second;
                        }
                    }
                }

                if(pattern[2*totalSteps-step-1] != 'A'){
                    long long newArea = reverseSum[totalSteps-x][totalSteps-y] - reverseSum[totalSteps-x-1][totalSteps-y];
                    for(auto& kv : bp[x][y]){
                        if(kv.first + newArea <= otherHalf){
                            bp[x+1][y][kv.first + newArea] += kv.second;
                        }
                    }
                }
            }

            if(step < totalSteps) {
                dp[x][y].clear();
                bp[x][y].clear();
            }
        }
    }

    for(long long x = 0; x <= totalSteps; x++){
        long long y = totalSteps - x;
        if(y < 0 || y > totalSteps) continue;
        for(auto& kv : dp[x][y]){
            long long area1 = kv.first;
            long long count = kv.second;
            if(halfTotal >= area1){
                result += count * bp[totalSteps-x][totalSteps-y][halfTotal - area1];
            }
            if(otherHalf != halfTotal && otherHalf >= area1){
                result += count * bp[totalSteps-x][totalSteps-y][otherHalf - area1];
            }
        }
    }

    cout << result << endl;
    return 0;
}

