                }
            }
            if (x + y + 1 <= 2*N - d && pattern[N-x+N-y-1] != 'A') {
                lint area2 = prefix[N-x][N-y] - prefix[N-x-1][N-y];
                for (auto &[key, val] : bp[x][y]) {
                    if (key + area2 <= half2) bp[x+1][y][key + area2] += val;
                }
            }
            if (x + y + 1 <= d) dp[x][y].clear();
            if (x + y + 1 <= 2*N - d) bp[x][y].clear();
        }
    }

    for (int x = 0; x <= N; ++x) {
        int y = d - x;
        if (y < 0 || y > N) continue;
        for (auto &[key, val] : dp[x][y]) {
            lint target1 = half1 - key;
            lint target2 = half2 - key;
            count += val * bp[N-x][N-y][target1];
            if (half1 != half2) count += val * bp[N-x][N-y][target2];
        }
    }

